window.PeaWordUsage={"version":1,"updatedAt":"2026-10-26","source":"doc-026","count":400,"entries":{"1":{"sense":"v. 扩大；扩展","collocations":["expand access","expand the range"],"example":"The city plans to expand access to evening classes.","translation":"这座城市计划让更多人能参加夜校课程。","note":"expand常指规模或范围扩大；amplify常指放大声音、信号或强化说明，不能在本句直接替换。","number":1,"resourceId":"doc-026-1-0feed966b6f4","term":"expand","originalPair":"expand = amplify","needsCare":true,"sources":[{"title":"Merriam-Webster：expand","url":"https://www.merriam-webster.com/dictionary/expand"},{"title":"Merriam-Webster：amplify","url":"https://www.merriam-webster.com/dictionary/amplify"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"2":{"sense":"v. 完成；实现","collocations":["accomplish a task","achieve a goal"],"example":"Our team accomplished every task before Friday.","translation":"我们团队在星期五前完成了所有任务。","note":"accomplish常接任务或使命；achieve常接目标或成就，不必为换词强改自然搭配。","number":2,"resourceId":"doc-026-1-95772d378103","term":"accomplish","originalPair":"accomplish = achieve","needsCare":false,"sources":[{"title":"Merriam-Webster：accomplish","url":"https://www.merriam-webster.com/dictionary/accomplish"},{"title":"Merriam-Webster：achieve","url":"https://www.merriam-webster.com/dictionary/achieve"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"3":{"sense":"v. 获得；习得","collocations":["acquire skills","obtain permission"],"example":"Children acquire language through daily interaction.","translation":"儿童通过日常互动习得语言。","note":"acquire可强调逐渐习得；obtain常指取得物品、许可或结果，本句不宜机械替换。","number":3,"resourceId":"doc-026-1-ef26b7b86669","term":"acquire","originalPair":"acquire = obtain","needsCare":false,"sources":[{"title":"Merriam-Webster：acquire","url":"https://www.merriam-webster.com/dictionary/acquire"},{"title":"Merriam-Webster：obtain","url":"https://www.merriam-webster.com/dictionary/obtain"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"4":{"sense":"v. 提倡；公开支持","collocations":["advocate reform","champion a cause"],"example":"Several teachers advocate smaller classes.","translation":"几位教师主张缩小班级规模。","note":"champion也表示积极支持，但常强调维护某项事业；advocate后可接名词或动名词。","number":4,"resourceId":"doc-026-1-a311d8034310","term":"advocate","originalPair":"advocate = champion","needsCare":false,"sources":[{"title":"Merriam-Webster：advocate","url":"https://www.merriam-webster.com/dictionary/advocate"},{"title":"Merriam-Webster：champion","url":"https://www.merriam-webster.com/dictionary/champion"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"5":{"sense":"v. 减轻；缓解","collocations":["alleviate poverty","mitigate the impact"],"example":"Reliable buses could alleviate traffic congestion.","translation":"可靠的公交服务可以缓解交通拥堵。","note":"alleviate常接痛苦、贫困或问题；mitigate侧重降低不利影响或严重程度。","number":5,"resourceId":"doc-026-1-b4dca56e09ba","term":"alleviate","originalPair":"alleviate = mitigate","needsCare":false,"sources":[{"title":"Merriam-Webster：alleviate","url":"https://www.merriam-webster.com/dictionary/alleviate"},{"title":"Merriam-Webster：mitigate","url":"https://www.merriam-webster.com/dictionary/mitigate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"6":{"sense":"v. 分析","collocations":["analyze data","scrutinize details"],"example":"The researchers analyzed responses from three schools.","translation":"研究人员分析了来自三所学校的回答。","note":"analyze侧重分解分析；scrutinize侧重仔细审查，不能把一般分析都说成严格审查。","number":6,"resourceId":"doc-026-1-5ed7ca094448","term":"analyze","originalPair":"analyze = scrutinize","needsCare":false,"sources":[{"title":"Merriam-Webster：analyze","url":"https://www.merriam-webster.com/dictionary/analyze"},{"title":"Merriam-Webster：scrutinize","url":"https://www.merriam-webster.com/dictionary/scrutinize"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"7":{"sense":"v. 预期；预料","collocations":["anticipate demand","foresee problems"],"example":"We anticipate greater demand for online courses.","translation":"我们预计网络课程的需求会增加。","note":"anticipate可带有提前准备的意味；foresee侧重预见。anticipate后可接名词、动名词或从句。","number":7,"resourceId":"doc-026-1-194a40393f2d","term":"anticipate","originalPair":"anticipate = foresee","needsCare":false,"sources":[{"title":"Merriam-Webster：anticipate","url":"https://www.merriam-webster.com/dictionary/anticipate"},{"title":"Merriam-Webster：foresee","url":"https://www.merriam-webster.com/dictionary/foresee"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"8":{"sense":"v. 理解（正式）；逮捕","collocations":["comprehend an argument","apprehend a suspect"],"example":"I could not apprehend the meaning of the passage.","translation":"我没能理解这段文字的意思。","note":"apprehend表示理解时较正式，也常表示逮捕；日常写“理解”优先考虑understand或comprehend。","number":8,"resourceId":"doc-026-1-f755b6e49ee8","term":"apprehend","originalPair":"apprehend = comprehend","needsCare":true,"sources":[{"title":"Merriam-Webster：apprehend","url":"https://www.merriam-webster.com/dictionary/apprehend"},{"title":"Merriam-Webster：comprehend","url":"https://www.merriam-webster.com/dictionary/comprehend"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"9":{"sense":"adj. 人造的；非天然的","collocations":["artificial light","synthetic fibres"],"example":"Artificial light allows the plants to grow indoors.","translation":"人造光使这些植物能在室内生长。","note":"synthetic多指化学合成；artificial范围更广。artificial intelligence是固定术语。","number":9,"resourceId":"doc-026-1-08141d916edf","term":"artificial","originalPair":"artificial = synthetic","needsCare":false,"sources":[{"title":"Merriam-Webster：artificial","url":"https://www.merriam-webster.com/dictionary/artificial"},{"title":"Merriam-Webster：synthetic","url":"https://www.merriam-webster.com/dictionary/synthetic"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"10":{"sense":"v. 查明；确定","collocations":["ascertain the cause","determine whether"],"example":"The team tried to ascertain the cause of the delay.","translation":"团队试图查明延误的原因。","note":"ascertain强调查清事实；determine还可表示决定或影响，并非每个义项都相同。","number":10,"resourceId":"doc-026-1-c9226e3d48f8","term":"ascertain","originalPair":"ascertain = determine","needsCare":false,"sources":[{"title":"Merriam-Webster：ascertain","url":"https://www.merriam-webster.com/dictionary/ascertain"},{"title":"Merriam-Webster：determine","url":"https://www.merriam-webster.com/dictionary/determine"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"11":{"sense":"v. 集合；组装","collocations":["assemble a team","compile a report"],"example":"Volunteers assembled a team to repair the playground.","translation":"志愿者组建了一个修缮操场的团队。","note":"compile指汇编资料、清单等；assemble还可组装物品或召集人员，不宜将两者当通用同义词。","number":11,"resourceId":"doc-026-1-3bfd5a807efc","term":"assemble","originalPair":"assemble = compile","needsCare":true,"sources":[{"title":"Merriam-Webster：assemble","url":"https://www.merriam-webster.com/dictionary/assemble"},{"title":"Merriam-Webster：compile","url":"https://www.merriam-webster.com/dictionary/compile"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"12":{"sense":"v. 评估","collocations":["assess progress","evaluate a proposal"],"example":"The tutor assessed my progress after six lessons.","translation":"上了六节课后，导师评估了我的进步。","note":"evaluate也可指评估价值、质量或成效；两词在评估语境中接近，仍须保留合适宾语。","number":12,"resourceId":"doc-026-1-70eaffa97fa2","term":"assess","originalPair":"assess = evaluate","needsCare":false,"sources":[{"title":"Merriam-Webster：assess","url":"https://www.merriam-webster.com/dictionary/assess"},{"title":"Merriam-Webster：evaluate","url":"https://www.merriam-webster.com/dictionary/evaluate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"13":{"sense":"v. 吸收；同化","collocations":["assimilate information","integrate into society"],"example":"Students need time to assimilate unfamiliar information.","translation":"学生需要时间吸收不熟悉的信息。","note":"assimilate强调吸收或同化；integrate强调融入或整合，不一定意味着失去原有差异。","number":13,"resourceId":"doc-026-1-83ba5d43adb5","term":"assimilate","originalPair":"assimilate = integrate","needsCare":false,"sources":[{"title":"Merriam-Webster：assimilate","url":"https://www.merriam-webster.com/dictionary/assimilate"},{"title":"Merriam-Webster：integrate","url":"https://www.merriam-webster.com/dictionary/integrate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"14":{"sense":"v. 增加；扩大","collocations":["augment income","enhance quality"],"example":"She took weekend work to augment her income.","translation":"她做周末工作来增加收入。","note":"augment侧重增加数量；enhance侧重提升质量、价值或吸引力，增加未必等于改善。","number":14,"resourceId":"doc-026-1-ec71f1f31f50","term":"augment","originalPair":"augment = enhance","needsCare":false,"sources":[{"title":"Merriam-Webster：augment","url":"https://www.merriam-webster.com/dictionary/augment"},{"title":"Merriam-Webster：enhance","url":"https://www.merriam-webster.com/dictionary/enhance"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"15":{"sense":"adj. 真实的；非伪造的","collocations":["authentic documents","genuine interest"],"example":"The museum displayed an authentic nineteenth-century map.","translation":"博物馆展出了一张真正的十九世纪地图。","note":"genuine也可指非伪造，但还可表示真诚；authentic也常强调来源可信或符合原貌。","number":15,"resourceId":"doc-026-1-f5a311c9b9f2","term":"authentic","originalPair":"authentic = genuine","needsCare":false,"sources":[{"title":"Merriam-Webster：authentic","url":"https://www.merriam-webster.com/dictionary/authentic"},{"title":"Merriam-Webster：genuine","url":"https://www.merriam-webster.com/dictionary/genuine"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"16":{"sense":"adj. 自主的；自治的","collocations":["autonomous learning","independent research"],"example":"The course encourages autonomous learning.","translation":"这门课鼓励自主学习。","note":"autonomous强调自我管理；independent可泛指不依赖他人，两者不总是同一层面的独立。","number":16,"resourceId":"doc-026-1-6c9f39914616","term":"autonomous","originalPair":"autonomous = independent","needsCare":false,"sources":[{"title":"Merriam-Webster：autonomous","url":"https://www.merriam-webster.com/dictionary/autonomous"},{"title":"Merriam-Webster：independent","url":"https://www.merriam-webster.com/dictionary/independent"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"17":{"sense":"adj. 困惑的","collocations":["bewildered by","perplexed about"],"example":"New students looked bewildered by the complex timetable.","translation":"新生被复杂的课表弄得不知所措。","note":"两词都可描述困惑；bewildered常强调迷茫，perplexed常指难以理解某个问题。","number":17,"resourceId":"doc-026-1-effb7016a3b2","term":"bewildered","originalPair":"bewildered = perplexed","needsCare":false,"sources":[{"title":"Merriam-Webster：bewildered","url":"https://www.merriam-webster.com/dictionary/bewildered"},{"title":"Merriam-Webster：perplexed","url":"https://www.merriam-webster.com/dictionary/perplexed"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"18":{"sense":"adj. 钝的；直言的","collocations":["a blunt knife","a dull blade"],"example":"A blunt knife makes food preparation difficult.","translation":"钝刀会使备餐变得困难。","note":"与dull近义的是刀刃不锋利的义项；blunt表示直言不讳时不能直接换成dull。","number":18,"resourceId":"doc-026-1-4b174ebc6bbf","term":"blunt","originalPair":"blunt = dull","needsCare":false,"sources":[{"title":"Merriam-Webster：blunt","url":"https://www.merriam-webster.com/dictionary/blunt"},{"title":"Merriam-Webster：dull","url":"https://www.merriam-webster.com/dictionary/dull"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"19":{"sense":"v. 支持；增强","collocations":["bolster confidence","reinforce an argument"],"example":"Regular feedback can bolster learners' confidence.","translation":"经常获得反馈可以增强学习者的信心。","note":"bolster常指给予支持；reinforce还可指加固结构或强化已有观点。","number":19,"resourceId":"doc-026-1-8b8b0c51bd0b","term":"bolster","originalPair":"bolster = reinforce","needsCare":false,"sources":[{"title":"Merriam-Webster：bolster","url":"https://www.merriam-webster.com/dictionary/bolster"},{"title":"Merriam-Webster：reinforce","url":"https://www.merriam-webster.com/dictionary/reinforce"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"20":{"sense":"v. 集思广益；构思点子","collocations":["brainstorm ideas","contemplate a decision"],"example":"The group brainstormed ways to reduce plastic waste.","translation":"小组集思广益，想办法减少塑料垃圾。","note":"brainstorm重在提出点子，常用于讨论；contemplate是认真思考或考虑，两者不是直接同义词。","number":20,"resourceId":"doc-026-1-5607e93d1254","term":"brainstorm","originalPair":"brainstorm = contemplate","needsCare":true,"sources":[{"title":"Merriam-Webster：brainstorm","url":"https://www.merriam-webster.com/dictionary/brainstorm"},{"title":"Merriam-Webster：contemplate","url":"https://www.merriam-webster.com/dictionary/contemplate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"21":{"sense":"v. 违反；破坏","collocations":["breach a contract","violate a rule"],"example":"Publishing those records would breach the agreement.","translation":"公布那些记录会违反协议。","note":"breach常接合同、协议或保密义务；violate也可接法律、规则和权利。","number":21,"resourceId":"doc-026-2-1dae03272376","term":"breach","originalPair":"breach = violate","needsCare":false,"sources":[{"title":"Merriam-Webster：breach","url":"https://www.merriam-webster.com/dictionary/breach"},{"title":"Merriam-Webster：violate","url":"https://www.merriam-webster.com/dictionary/violate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"22":{"sense":"v. 迅速增长","collocations":["burgeon","flourish in"],"example":"Small businesses began to burgeon near the station.","translation":"车站附近的小企业开始迅速增加。","note":"burgeon强调迅速增长；flourish强调蓬勃发展或兴旺，兴旺不一定表现为数量增加。","number":22,"resourceId":"doc-026-2-0ebb171d6370","term":"burgeon","originalPair":"burgeon = flourish","needsCare":false,"sources":[{"title":"Merriam-Webster：burgeon","url":"https://www.merriam-webster.com/dictionary/burgeon"},{"title":"Merriam-Webster：flourish","url":"https://www.merriam-webster.com/dictionary/flourish"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"23":{"sense":"v. 停止","collocations":["cease production","terminate a contract"],"example":"The factory will cease production next month.","translation":"工厂将于下月停产。","note":"cease可表示活动停止；terminate强调使某事结束，常接合同、雇佣等。","number":23,"resourceId":"doc-026-2-92f44efaa661","term":"cease","originalPair":"cease = terminate","needsCare":false,"sources":[{"title":"Merriam-Webster：cease","url":"https://www.merriam-webster.com/dictionary/cease"},{"title":"Merriam-Webster：terminate","url":"https://www.merriam-webster.com/dictionary/terminate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"24":{"sense":"v. 绕过；设法避开","collocations":["circumvent restrictions","bypass a town"],"example":"Some drivers use side roads to circumvent the restrictions.","translation":"一些司机走小路来绕过限制。","note":"circumvent常指巧妙规避困难或规则；bypass还可指路线绕行，不一定涉及规避规定。","number":24,"resourceId":"doc-026-2-3d0bad74d428","term":"circumvent","originalPair":"circumvent = bypass","needsCare":false,"sources":[{"title":"Merriam-Webster：circumvent","url":"https://www.merriam-webster.com/dictionary/circumvent"},{"title":"Merriam-Webster：bypass","url":"https://www.merriam-webster.com/dictionary/bypass"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"25":{"sense":"adj. 连贯的；条理清楚的","collocations":["a coherent argument","a cohesive group"],"example":"Each paragraph contributes to a coherent argument.","translation":"每一段都为形成连贯的论证作出贡献。","note":"coherent侧重意思和逻辑可理解；cohesive侧重结合紧密。写作中衔接紧密不自动等于逻辑清楚。","number":25,"resourceId":"doc-026-2-71d19dbd9944","term":"coherent","originalPair":"coherent = cohesive","needsCare":true,"sources":[{"title":"Merriam-Webster：coherent","url":"https://www.merriam-webster.com/dictionary/coherent"},{"title":"Merriam-Webster：cohesive","url":"https://www.merriam-webster.com/dictionary/cohesive"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"26":{"sense":"v. 合作","collocations":["collaborate on","cooperate with"],"example":"Two colleges collaborated on a local history project.","translation":"两所学院合作开展了一项地方历史项目。","note":"collaborate常指共同创作或完成项目；cooperate范围更广，也可指配合要求。","number":26,"resourceId":"doc-026-2-1b642ee8cfff","term":"collaborate","originalPair":"collaborate = cooperate","needsCare":false,"sources":[{"title":"Merriam-Webster：collaborate","url":"https://www.merriam-webster.com/dictionary/collaborate"},{"title":"Merriam-Webster：cooperate","url":"https://www.merriam-webster.com/dictionary/cooperate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"27":{"sense":"adj. 值得称赞的","collocations":["a commendable effort","praiseworthy work"],"example":"Their effort to make the event accessible was commendable.","translation":"他们为提升活动无障碍条件所作的努力值得称赞。","note":"praiseworthy同样表示值得赞扬；二者语气较正式，宜说明具体值得称赞的行为。","number":27,"resourceId":"doc-026-2-4f454bfd5d06","term":"commendable","originalPair":"commendable = praiseworthy","needsCare":false,"sources":[{"title":"Merriam-Webster：commendable","url":"https://www.merriam-webster.com/dictionary/commendable"},{"title":"Merriam-Webster：praiseworthy","url":"https://www.merriam-webster.com/dictionary/praiseworthy"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"28":{"sense":"v. 补偿","collocations":["compensate someone for","recompense someone"],"example":"The company compensated passengers for the delay.","translation":"公司因延误向乘客作出了补偿。","note":"常用compensate someone for something；recompense较正式，也可作名词，句法不能整句照搬。","number":28,"resourceId":"doc-026-2-0542644bd51a","term":"compensate","originalPair":"compensate = recompense","needsCare":false,"sources":[{"title":"Merriam-Webster：compensate","url":"https://www.merriam-webster.com/dictionary/compensate"},{"title":"Merriam-Webster：recompense","url":"https://www.merriam-webster.com/dictionary/recompense"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"29":{"sense":"v. 补充；与……相配","collocations":["complement a course","enhance learning"],"example":"Practical workshops complement the online lectures.","translation":"实践工作坊对网络讲座形成补充。","note":"complement表示相互补足或相配；enhance表示提升。注意不要与表示赞美的compliment混淆。","number":29,"resourceId":"doc-026-2-d599ca32366d","term":"complement","originalPair":"complement = enhance","needsCare":false,"sources":[{"title":"Merriam-Webster：complement","url":"https://www.merriam-webster.com/dictionary/complement"},{"title":"Merriam-Webster：enhance","url":"https://www.merriam-webster.com/dictionary/enhance"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"30":{"sense":"adj. 全面的","collocations":["a comprehensive overview","an exhaustive list"],"example":"The guide provides a comprehensive overview of the course.","translation":"指南全面介绍了这门课程。","note":"exhaustive强调尽可能不遗漏，语气通常比comprehensive更强，不能轻易宣称穷尽全部内容。","number":30,"resourceId":"doc-026-2-bf2901be348e","term":"comprehensive","originalPair":"comprehensive = exhaustive","needsCare":false,"sources":[{"title":"Merriam-Webster：comprehensive","url":"https://www.merriam-webster.com/dictionary/comprehensive"},{"title":"Merriam-Webster：exhaustive","url":"https://www.merriam-webster.com/dictionary/exhaustive"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"31":{"sense":"v. 包含；由……组成","collocations":["comprise three parts","consist of three parts"],"example":"The course comprises three practical modules.","translation":"这门课程包含三个实践模块。","note":"主动结构用A comprises B；改写为A consists of B时必须保留of。","number":31,"resourceId":"doc-026-2-6d50b3651467","term":"comprise","originalPair":"comprise = consist of","needsCare":false,"sources":[{"title":"Merriam-Webster：comprise","url":"https://www.merriam-webster.com/dictionary/comprise"},{"title":"Merriam-Webster：consist of","url":"https://www.merriam-webster.com/dictionary/consist%20of"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"32":{"sense":"v. 构想；设想","collocations":["conceive of","conceptualize a model"],"example":"The researchers conceived of a simpler testing method.","translation":"研究人员构想出一种更简单的测试方法。","note":"conceive可用conceive of；conceptualize强调形成概念或模型，通常直接接宾语。","number":32,"resourceId":"doc-026-2-005d44eed1ea","term":"conceive","originalPair":"conceive = conceptualize","needsCare":false,"sources":[{"title":"Merriam-Webster：conceive","url":"https://www.merriam-webster.com/dictionary/conceive"},{"title":"Merriam-Webster：conceptualize","url":"https://www.merriam-webster.com/dictionary/conceptualize"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"33":{"sense":"adj. 简洁的","collocations":["a concise summary","a succinct explanation"],"example":"Please write a concise summary of the findings.","translation":"请简洁概括研究结果。","note":"两词都指表达简明；简短不等于遗漏关键内容，也不应只为缩短篇幅删掉必要信息。","number":33,"resourceId":"doc-026-2-f67a5198e34a","term":"concise","originalPair":"concise = succinct","needsCare":false,"sources":[{"title":"Merriam-Webster：concise","url":"https://www.merriam-webster.com/dictionary/concise"},{"title":"Merriam-Webster：succinct","url":"https://www.merriam-webster.com/dictionary/succinct"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"34":{"sense":"v. 面对；直面","collocations":["confront a problem","encounter difficulties"],"example":"The council must confront the shortage of affordable housing.","translation":"市议会必须直面可负担住房短缺的问题。","note":"encounter是遇到；confront常强调正面面对或处理，也可用be confronted with。","number":34,"resourceId":"doc-026-2-f8b9c5c6da01","term":"confront","originalPair":"confront = encounter","needsCare":false,"sources":[{"title":"Merriam-Webster：confront","url":"https://www.merriam-webster.com/dictionary/confront"},{"title":"Merriam-Webster：encounter","url":"https://www.merriam-webster.com/dictionary/encounter"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"35":{"sense":"adj. 相符的；全等的","collocations":["congruent with","compatible with"],"example":"The findings are congruent with our earlier observations.","translation":"这些发现与我们先前的观察相符。","note":"congruent侧重一致或数学中的全等；compatible指能共存或配合，不要求完全一致。","number":35,"resourceId":"doc-026-2-7c3c57cd3180","term":"congruent","originalPair":"congruent = compatible","needsCare":true,"sources":[{"title":"Merriam-Webster：congruent","url":"https://www.merriam-webster.com/dictionary/congruent"},{"title":"Merriam-Webster：compatible","url":"https://www.merriam-webster.com/dictionary/compatible"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"36":{"sense":"adj. 相当大的","collocations":["considerable expense","substantial savings"],"example":"The repair work required considerable investment.","translation":"维修工程需要相当大的投入。","note":"两词都可形容量或程度较大；considerable不等于considerate（体贴的）。","number":36,"resourceId":"doc-026-2-3d4c6e9c8473","term":"considerable","originalPair":"considerable = substantial","needsCare":false,"sources":[{"title":"Merriam-Webster：considerable","url":"https://www.merriam-webster.com/dictionary/considerable"},{"title":"Merriam-Webster：substantial","url":"https://www.merriam-webster.com/dictionary/substantial"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"37":{"sense":"adj. 一致的；稳定的","collocations":["consistent with","a coherent account"],"example":"The results are consistent with the original hypothesis.","translation":"结果与最初的假设一致。","note":"consistent with强调与某事相符；coherent强调整体连贯。逻辑连贯不等于与外部证据一致。","number":37,"resourceId":"doc-026-2-5e05acd178df","term":"consistent","originalPair":"consistent = coherent","needsCare":true,"sources":[{"title":"Merriam-Webster：consistent","url":"https://www.merriam-webster.com/dictionary/consistent"},{"title":"Merriam-Webster：coherent","url":"https://www.merriam-webster.com/dictionary/coherent"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"38":{"sense":"v. 思考；认真考虑","collocations":["contemplate doing","ponder a question"],"example":"She contemplated changing her study routine.","translation":"她认真考虑改变学习习惯。","note":"contemplate可接动名词；ponder常接问题或决定，也可用ponder over/on，不能无视结构替换。","number":38,"resourceId":"doc-026-2-3e3a0ae7fb0a","term":"contemplate","originalPair":"contemplate = ponder","needsCare":false,"sources":[{"title":"Merriam-Webster：contemplate","url":"https://www.merriam-webster.com/dictionary/contemplate"},{"title":"Merriam-Webster：ponder","url":"https://www.merriam-webster.com/dictionary/ponder"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"39":{"sense":"v. 与……矛盾；反驳","collocations":["contradict evidence","negate an effect"],"example":"The new evidence contradicts his explanation.","translation":"新证据与他的解释相矛盾。","note":"contradict强调不一致或反驳；negate可指使失效或否定，未必表示两项证据冲突。","number":39,"resourceId":"doc-026-2-0cb4e032fbe2","term":"contradict","originalPair":"contradict = negate","needsCare":true,"sources":[{"title":"Merriam-Webster：contradict","url":"https://www.merriam-webster.com/dictionary/contradict"},{"title":"Merriam-Webster：negate","url":"https://www.merriam-webster.com/dictionary/negate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"40":{"sense":"adj. 常规的；传统的","collocations":["conventional methods","orthodox views"],"example":"The team compared the device with conventional equipment.","translation":"团队将这台设备与常规设备进行了比较。","note":"conventional指惯常做法；orthodox强调符合公认信条或传统观点，语域不同。","number":40,"resourceId":"doc-026-2-837d419786a7","term":"conventional","originalPair":"conventional = orthodox","needsCare":false,"sources":[{"title":"Merriam-Webster：conventional","url":"https://www.merriam-webster.com/dictionary/conventional"},{"title":"Merriam-Webster：orthodox","url":"https://www.merriam-webster.com/dictionary/orthodox"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"41":{"sense":"v. 汇聚；趋同","collocations":["converge on","merge into"],"example":"Several cycle routes converge near the library.","translation":"几条自行车道在图书馆附近汇聚。","note":"converge可只表示趋近或会合；merge强调合并成为整体，汇聚不一定已合并。","number":41,"resourceId":"doc-026-2-454f423c332a","term":"converge","originalPair":"converge = merge","needsCare":false,"sources":[{"title":"Merriam-Webster：converge","url":"https://www.merriam-webster.com/dictionary/converge"},{"title":"Merriam-Webster：merge","url":"https://www.merriam-webster.com/dictionary/merge"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"42":{"sense":"adv. 反过来；相反地","collocations":["conversely","on the contrary"],"example":"Urban rents rose; conversely, rural rents fell.","translation":"城市租金上涨；相反，乡村租金下降。","note":"conversely用于反向或对照关系；on the contrary通常反驳前述说法，并非普通转折连接词。","number":42,"resourceId":"doc-026-2-1983c15382b9","term":"conversely","originalPair":"conversely = on the contrary","needsCare":true,"sources":[{"title":"Merriam-Webster：conversely","url":"https://www.merriam-webster.com/dictionary/conversely"},{"title":"Merriam-Webster：on the contrary","url":"https://www.merriam-webster.com/dictionary/on%20the%20contrary"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"43":{"sense":"adj. 至关重要的","collocations":["crucial to","a pivotal role"],"example":"Reliable evidence is crucial to sound decision-making.","translation":"可靠证据对作出合理决策至关重要。","note":"pivotal常强调核心或转折作用；crucial强调极其重要，注意a pivotal role等自然搭配。","number":43,"resourceId":"doc-026-3-d3431fb3055a","term":"crucial","originalPair":"crucial = pivotal","needsCare":false,"sources":[{"title":"Merriam-Webster：crucial","url":"https://www.merriam-webster.com/dictionary/crucial"},{"title":"Merriam-Webster：pivotal","url":"https://www.merriam-webster.com/dictionary/pivotal"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"44":{"sense":"v. 达到高潮；以……告终","collocations":["culminate in","climax with"],"example":"Months of preparation culminated in a successful exhibition.","translation":"数月的准备最终促成了一场成功的展览。","note":"culminate常用in接最终结果；climax侧重高潮。不要写culminate the exhibition来表达同一结构。","number":44,"resourceId":"doc-026-3-99cefe8b8e41","term":"culminate","originalPair":"culminate = climax","needsCare":false,"sources":[{"title":"Merriam-Webster：culminate","url":"https://www.merriam-webster.com/dictionary/culminate"},{"title":"Merriam-Webster：climax","url":"https://www.merriam-webster.com/dictionary/climax"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"45":{"sense":"adj. 笨重的；繁琐的","collocations":["cumbersome procedures","unwieldy equipment"],"example":"The school replaced its cumbersome registration process.","translation":"学校替换了繁琐的注册流程。","note":"两词都可表示难处理；cumbersome还常形容程序繁琐，unwieldy常突出体积或组织难驾驭。","number":45,"resourceId":"doc-026-3-e07152447754","term":"cumbersome","originalPair":"cumbersome = unwieldy","needsCare":false,"sources":[{"title":"Merriam-Webster：cumbersome","url":"https://www.merriam-webster.com/dictionary/cumbersome"},{"title":"Merriam-Webster：unwieldy","url":"https://www.merriam-webster.com/dictionary/unwieldy"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"46":{"sense":"v. 辨认；破译","collocations":["decipher handwriting","decode a message"],"example":"I could barely decipher the faded handwriting.","translation":"我几乎辨认不出褪色的字迹。","note":"decipher可指读懂潦草或模糊文字；decode强调解码，不是所有辨认文字都涉及密码。","number":46,"resourceId":"doc-026-3-82bda1f63f64","term":"decipher","originalPair":"decipher = decode","needsCare":false,"sources":[{"title":"Merriam-Webster：decipher","url":"https://www.merriam-webster.com/dictionary/decipher"},{"title":"Merriam-Webster：decode","url":"https://www.merriam-webster.com/dictionary/decode"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"47":{"sense":"adj. 决定性的；果断的","collocations":["a decisive factor","a definitive account"],"example":"Affordable transport was a decisive factor in her choice.","translation":"价格可承受的交通是她作出选择的决定性因素。","note":"decisive指影响结果或果断；definitive指权威、最终或确定，不宜混同。","number":47,"resourceId":"doc-026-3-954372ec8ebb","term":"decisive","originalPair":"decisive = definitive","needsCare":true,"sources":[{"title":"Merriam-Webster：decisive","url":"https://www.merriam-webster.com/dictionary/decisive"},{"title":"Merriam-Webster：definitive","url":"https://www.merriam-webster.com/dictionary/definitive"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"48":{"sense":"v. 推断；演绎得出","collocations":["deduce from","infer from"],"example":"We can deduce the direction of travel from these tracks.","translation":"我们可以根据这些足迹推断行进方向。","note":"deduce常突出依据事实或逻辑得出结论；infer更宽泛。都不能与imply（暗示）混淆。","number":48,"resourceId":"doc-026-3-3e5824c34be3","term":"deduce","originalPair":"deduce = infer","needsCare":false,"sources":[{"title":"Merriam-Webster：deduce","url":"https://www.merriam-webster.com/dictionary/deduce"},{"title":"Merriam-Webster：infer","url":"https://www.merriam-webster.com/dictionary/infer"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"49":{"sense":"v. 认为（正式）","collocations":["deem something necessary","consider doing"],"example":"The committee deemed further testing necessary.","translation":"委员会认为有必要进一步测试。","note":"deem常用宾语加形容词；consider可接动名词，不能将consider doing机械改成deem doing。","number":49,"resourceId":"doc-026-3-a6ffe10e579d","term":"deem","originalPair":"deem = consider","needsCare":false,"sources":[{"title":"Merriam-Webster：deem","url":"https://www.merriam-webster.com/dictionary/deem"},{"title":"Merriam-Webster：consider","url":"https://www.merriam-webster.com/dictionary/consider"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"50":{"sense":"n. 缺乏；不足","collocations":["a deficiency in","an insufficiency of"],"example":"The review revealed a deficiency in staff training.","translation":"审查发现员工培训存在不足。","note":"deficiency常指缺陷或特定成分缺乏；insufficiency偏重数量或程度不够。","number":50,"resourceId":"doc-026-3-75c57f808088","term":"deficiency","originalPair":"deficiency = insufficiency","needsCare":false,"sources":[{"title":"Merriam-Webster：deficiency","url":"https://www.merriam-webster.com/dictionary/deficiency"},{"title":"Merriam-Webster：insufficiency","url":"https://www.merriam-webster.com/dictionary/insufficiency"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"51":{"sense":"v. 勾勒；详细描述","collocations":["delineate responsibilities","depict a scene"],"example":"The document delineates each department's responsibilities.","translation":"文件清楚列明了各部门的职责。","note":"delineate侧重划清轮廓或详细界定；depict常通过图像或文字描绘。","number":51,"resourceId":"doc-026-3-2cbdd75573ab","term":"delineate","originalPair":"delineate = depict","needsCare":false,"sources":[{"title":"Merriam-Webster：delineate","url":"https://www.merriam-webster.com/dictionary/delineate"},{"title":"Merriam-Webster：depict","url":"https://www.merriam-webster.com/dictionary/depict"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"52":{"sense":"v. 表示；指称","collocations":["denote a quantity","signify a change"],"example":"In this chart, blue denotes the lowest income group.","translation":"在这张图中，蓝色表示最低收入组。","note":"denote常用于符号、词语的指代；signify也可强调意味着某种重要变化。","number":52,"resourceId":"doc-026-3-b02cc55aad75","term":"denote","originalPair":"denote = signify","needsCare":false,"sources":[{"title":"Merriam-Webster：denote","url":"https://www.merriam-webster.com/dictionary/denote"},{"title":"Merriam-Webster：signify","url":"https://www.merriam-webster.com/dictionary/signify"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"53":{"sense":"v. 部署；调配","collocations":["deploy staff","utilize resources"],"example":"The hospital deployed extra staff during the weekend.","translation":"医院在周末增派了员工。","note":"deploy侧重有计划地部署人员、设备等；utilize是利用，不包含部署这一具体含义。","number":53,"resourceId":"doc-026-3-9777c74baed7","term":"deploy","originalPair":"deploy = utilize","needsCare":false,"sources":[{"title":"Merriam-Webster：deploy","url":"https://www.merriam-webster.com/dictionary/deploy"},{"title":"Merriam-Webster：utilize","url":"https://www.merriam-webster.com/dictionary/utilize"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"54":{"sense":"v. 消耗；使枯竭","collocations":["deplete reserves","exhaust supplies"],"example":"Overuse can deplete the region's groundwater reserves.","translation":"过度使用会耗竭该地区的地下水储备。","note":"deplete指显著减少，未必全部用完；exhaust更容易表达耗尽，程度需要核对。","number":54,"resourceId":"doc-026-3-ecd923f64f8f","term":"deplete","originalPair":"deplete = exhaust","needsCare":true,"sources":[{"title":"Merriam-Webster：deplete","url":"https://www.merriam-webster.com/dictionary/deplete"},{"title":"Merriam-Webster：exhaust","url":"https://www.merriam-webster.com/dictionary/exhaust"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"55":{"sense":"v. 获得；源自","collocations":["derive benefits from","obtain a permit"],"example":"Residents derive several benefits from the new park.","translation":"居民从新公园获得了多种好处。","note":"derive常用from说明来源；obtain一般直接接所得物，不能把derive from的结构原样套用。","number":55,"resourceId":"doc-026-3-c4f76fb2f33d","term":"derive","originalPair":"derive = obtain","needsCare":false,"sources":[{"title":"Merriam-Webster：derive","url":"https://www.merriam-webster.com/dictionary/derive"},{"title":"Merriam-Webster：obtain","url":"https://www.merriam-webster.com/dictionary/obtain"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"56":{"sense":"v. 指定；命名","collocations":["designate as","appoint someone to"],"example":"The council designated the building as a public library.","translation":"市议会将这栋建筑指定为公共图书馆。","note":"appoint多指任命人员担任职务；designate也可指定地点或用途，不局限于任命。","number":56,"resourceId":"doc-026-3-a3ff4d6f2b14","term":"designate","originalPair":"designate = appoint","needsCare":false,"sources":[{"title":"Merriam-Webster：designate","url":"https://www.merriam-webster.com/dictionary/designate"},{"title":"Merriam-Webster：appoint","url":"https://www.merriam-webster.com/dictionary/appoint"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"57":{"sense":"v. 察觉；检测出","collocations":["detect a change","discern a pattern"],"example":"The sensor can detect small changes in temperature.","translation":"传感器能够检测到微小的温度变化。","note":"discern常指通过观察或判断辨明；detect也用于仪器检测，宾语虽相近，侧重点不同。","number":57,"resourceId":"doc-026-3-a7143f291ce4","term":"detect","originalPair":"detect = discern","needsCare":false,"sources":[{"title":"Merriam-Webster：detect","url":"https://www.merriam-webster.com/dictionary/detect"},{"title":"Merriam-Webster：discern","url":"https://www.merriam-webster.com/dictionary/discern"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"58":{"sense":"v. 恶化","collocations":["deteriorate rapidly","worsen over time"],"example":"Road conditions deteriorated after several days of rain.","translation":"连日降雨后路况恶化了。","note":"deteriorate通常不及物；worsen既可及物也可不及物，替换时需检查主宾语。","number":58,"resourceId":"doc-026-3-76edc9314a56","term":"deteriorate","originalPair":"deteriorate = worsen","needsCare":false,"sources":[{"title":"Merriam-Webster：deteriorate","url":"https://www.merriam-webster.com/dictionary/deteriorate"},{"title":"Merriam-Webster：worsen","url":"https://www.merriam-webster.com/dictionary/worsen"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"59":{"sense":"v. 偏离","collocations":["deviate from","diverge from"],"example":"The final design deviates from the original plan.","translation":"最终设计偏离了最初的计划。","note":"deviate常强调偏离标准或路线；diverge也可表示两条路径或观点逐渐分开。","number":59,"resourceId":"doc-026-3-708d14dfb0d6","term":"deviate","originalPair":"deviate = diverge","needsCare":false,"sources":[{"title":"Merriam-Webster：deviate","url":"https://www.merriam-webster.com/dictionary/deviate"},{"title":"Merriam-Webster：diverge","url":"https://www.merriam-webster.com/dictionary/diverge"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"60":{"sense":"v. 减少；减弱","collocations":["diminish confidence","reduce costs"],"example":"Repeated delays diminished public confidence in the project.","translation":"反复延误削弱了公众对项目的信心。","note":"diminish可及物或不及物；reduce常直接接减少的对象，描述数值时还要注明幅度。","number":60,"resourceId":"doc-026-3-08d81b7d4d6b","term":"diminish","originalPair":"diminish = reduce","needsCare":false,"sources":[{"title":"Merriam-Webster：diminish","url":"https://www.merriam-webster.com/dictionary/diminish"},{"title":"Merriam-Webster：reduce","url":"https://www.merriam-webster.com/dictionary/reduce"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"61":{"sense":"v. 披露；透露","collocations":["disclose information","reveal a result"],"example":"The report discloses how the funds were allocated.","translation":"报告披露了资金的分配方式。","note":"disclose常指正式披露原先不公开的信息；reveal范围更广，也可揭示事实或露出物体。","number":61,"resourceId":"doc-026-3-3316568bc9a2","term":"disclose","originalPair":"disclose = reveal","needsCare":false,"sources":[{"title":"Merriam-Webster：disclose","url":"https://www.merriam-webster.com/dictionary/disclose"},{"title":"Merriam-Webster：reveal","url":"https://www.merriam-webster.com/dictionary/reveal"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"62":{"sense":"n. 抑制因素；阻碍因素","collocations":["a disincentive to","a deterrent to"],"example":"High fees can be a disincentive to further study.","translation":"高额费用可能降低继续学习的意愿。","note":"disincentive侧重削弱动机；deterrent侧重阻止某行为，常见于威慑违法行为的语境。","number":62,"resourceId":"doc-026-3-133018340f0d","term":"disincentive","originalPair":"disincentive = deterrent","needsCare":false,"sources":[{"title":"Merriam-Webster：disincentive","url":"https://www.merriam-webster.com/dictionary/disincentive"},{"title":"Merriam-Webster：deterrent","url":"https://www.merriam-webster.com/dictionary/deterrent"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"63":{"sense":"v. 不予考虑；驳回","collocations":["dismiss a claim","disregard advice"],"example":"The board dismissed the proposal as too expensive.","translation":"董事会以成本过高为由否决了提案。","note":"dismiss常含判断后拒绝或不当回事；disregard侧重不理会，dismiss还可表示解雇。","number":63,"resourceId":"doc-026-3-0ce6473ba759","term":"dismiss","originalPair":"dismiss = disregard","needsCare":true,"sources":[{"title":"Merriam-Webster：dismiss","url":"https://www.merriam-webster.com/dictionary/dismiss"},{"title":"Merriam-Webster：disregard","url":"https://www.merriam-webster.com/dictionary/disregard"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"64":{"sense":"v. 歪曲；使失真","collocations":["distort evidence","misrepresent facts"],"example":"Selective quotations can distort the author's argument.","translation":"选择性引用可能歪曲作者的论点。","note":"distort可指图像、声音或事实失真；misrepresent强调错误呈现，未必适用于物理变形。","number":64,"resourceId":"doc-026-3-ad0bd2112a79","term":"distort","originalPair":"distort = misrepresent","needsCare":false,"sources":[{"title":"Merriam-Webster：distort","url":"https://www.merriam-webster.com/dictionary/distort"},{"title":"Merriam-Webster：misrepresent","url":"https://www.merriam-webster.com/dictionary/misrepresent"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"65":{"sense":"v. 转移；使改道","collocations":["divert traffic","redirect funding"],"example":"Police diverted traffic away from the damaged bridge.","translation":"警方让车辆绕开受损的桥梁。","note":"redirect强调重新指向；divert还可指分散注意力或挪用，两词并非所有义项相同。","number":65,"resourceId":"doc-026-4-2a6fe752b20a","term":"divert","originalPair":"divert = redirect","needsCare":false,"sources":[{"title":"Merriam-Webster：divert","url":"https://www.merriam-webster.com/dictionary/divert"},{"title":"Merriam-Webster：redirect","url":"https://www.merriam-webster.com/dictionary/redirect"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"66":{"sense":"adj. 休眠的；暂不活跃的","collocations":["a dormant volcano","inactive accounts"],"example":"Some seeds remain dormant throughout the winter.","translation":"有些种子在整个冬季保持休眠。","note":"dormant常暗示暂时休眠、以后可能恢复；inactive更一般地指不活跃。","number":66,"resourceId":"doc-026-4-793fa3a757d3","term":"dormant","originalPair":"dormant = inactive","needsCare":false,"sources":[{"title":"Merriam-Webster：dormant","url":"https://www.merriam-webster.com/dictionary/dormant"},{"title":"Merriam-Webster：inactive","url":"https://www.merriam-webster.com/dictionary/inactive"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"67":{"sense":"n. 表里不一；欺骗行为","collocations":["political duplicity","deliberate deceit"],"example":"The investigation exposed the official's duplicity.","translation":"调查揭露了这名官员的两面派行为。","note":"duplicity特别强调两面性或言行不一；deceit是更广义的欺骗。","number":67,"resourceId":"doc-026-4-f255d0e73ab7","term":"duplicity","originalPair":"duplicity = deceit","needsCare":false,"sources":[{"title":"Merriam-Webster：duplicity","url":"https://www.merriam-webster.com/dictionary/duplicity"},{"title":"Merriam-Webster：deceit","url":"https://www.merriam-webster.com/dictionary/deceit"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"68":{"sense":"v. 逐渐减少","collocations":["dwindle to","diminish over time"],"example":"The number of volunteers dwindled to ten.","translation":"志愿者人数逐渐减少到十人。","note":"dwindle通常不及物且强调逐渐变少；diminish范围更广，也可及物。","number":68,"resourceId":"doc-026-4-7c9efb7342d2","term":"dwindle","originalPair":"dwindle = diminish","needsCare":false,"sources":[{"title":"Merriam-Webster：dwindle","url":"https://www.merriam-webster.com/dictionary/dwindle"},{"title":"Merriam-Webster：diminish","url":"https://www.merriam-webster.com/dictionary/diminish"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"69":{"sense":"v. 引出；诱出","collocations":["elicit a response","evoke a memory"],"example":"Open questions can elicit detailed responses.","translation":"开放式问题可以引出详细回答。","note":"elicit常接回答、反应或信息；evoke常接情感、记忆或意象，不能一概互换。","number":69,"resourceId":"doc-026-4-24c8ec2e66a8","term":"elicit","originalPair":"elicit = evoke","needsCare":false,"sources":[{"title":"Merriam-Webster：elicit","url":"https://www.merriam-webster.com/dictionary/elicit"},{"title":"Merriam-Webster：evoke","url":"https://www.merriam-webster.com/dictionary/evoke"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"70":{"sense":"v. 体现；具体表现","collocations":["embody a principle","exemplify a problem"],"example":"The design embodies the principle of equal access.","translation":"这一设计体现了平等使用的原则。","note":"embody指将抽象特质具体体现出来；exemplify指作为例证或典型。","number":70,"resourceId":"doc-026-4-d1c7ade16a97","term":"embody","originalPair":"embody = exemplify","needsCare":false,"sources":[{"title":"Merriam-Webster：embody","url":"https://www.merriam-webster.com/dictionary/embody"},{"title":"Merriam-Webster：exemplify","url":"https://www.merriam-webster.com/dictionary/exemplify"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"71":{"sense":"v. 仿效；努力赶上","collocations":["emulate success","imitate a style"],"example":"Other towns hope to emulate this recycling programme.","translation":"其他城镇希望效仿这个回收项目。","note":"emulate常含以优秀对象为榜样、努力达到其水平；imitate可只是模仿外形或行为。","number":71,"resourceId":"doc-026-4-6c4a43e81389","term":"emulate","originalPair":"emulate = imitate","needsCare":false,"sources":[{"title":"Merriam-Webster：emulate","url":"https://www.merriam-webster.com/dictionary/emulate"},{"title":"Merriam-Webster：imitate","url":"https://www.merriam-webster.com/dictionary/imitate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"72":{"sense":"v. 包含；涵盖","collocations":["encompass a range","include examples"],"example":"The course encompasses reading, writing and discussion.","translation":"课程涵盖阅读、写作和讨论。","note":"encompass常强调范围广、把相关部分纳入；include未必表示列举了全部内容。","number":72,"resourceId":"doc-026-4-ad95e98f91c3","term":"encompass","originalPair":"encompass = include","needsCare":false,"sources":[{"title":"Merriam-Webster：encompass","url":"https://www.merriam-webster.com/dictionary/encompass"},{"title":"Merriam-Webster：include","url":"https://www.merriam-webster.com/dictionary/include"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"73":{"sense":"v. 公开支持；认可","collocations":["endorse a proposal","support a policy"],"example":"The teachers' union endorsed the new training scheme.","translation":"教师工会公开支持了新的培训计划。","note":"endorse常指公开或正式认可；support还可指实际帮助或提供资金。","number":73,"resourceId":"doc-026-4-8ef91c423d05","term":"endorse","originalPair":"endorse = support","needsCare":false,"sources":[{"title":"Merriam-Webster：endorse","url":"https://www.merriam-webster.com/dictionary/endorse"},{"title":"Merriam-Webster：support","url":"https://www.merriam-webster.com/dictionary/support"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"74":{"sense":"v. 涵盖；包括","collocations":["encompass several areas","comprise parts"],"example":"The survey encompasses several aspects of urban life.","translation":"调查涵盖城市生活的多个方面。","note":"comprise常描述整体由哪些部分组成；encompass强调所覆盖的范围，两者句法虽像，关系未必相同。","number":74,"resourceId":"doc-026-4-f6a7ec73b312","term":"encompass","originalPair":"encompass = comprise","needsCare":true,"sources":[{"title":"Merriam-Webster：encompass","url":"https://www.merriam-webster.com/dictionary/encompass"},{"title":"Merriam-Webster：comprise","url":"https://www.merriam-webster.com/dictionary/comprise"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"75":{"sense":"v. 提高；增强","collocations":["enhance quality","enrich an experience"],"example":"Better lighting can enhance the quality of the exhibition.","translation":"更好的照明可以提升展览质量。","note":"enrich侧重使内容、体验或生活更充实；enhance泛指提升价值、质量或效果。","number":75,"resourceId":"doc-026-4-c7cf593f47ec","term":"enhance","originalPair":"enhance = enrich","needsCare":false,"sources":[{"title":"Merriam-Webster：enhance","url":"https://www.merriam-webster.com/dictionary/enhance"},{"title":"Merriam-Webster：enrich","url":"https://www.merriam-webster.com/dictionary/enrich"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"76":{"sense":"n. 谜；难解之事","collocations":["remain an enigma","solve a puzzle"],"example":"The purpose of the ancient structure remains an enigma.","translation":"这座古建筑的用途仍然是个谜。","note":"enigma常指难以理解的人或事；puzzle还可指供人解答的拼图或智力题。","number":76,"resourceId":"doc-026-4-60f2f3c9e07c","term":"enigma","originalPair":"enigma = puzzle","needsCare":false,"sources":[{"title":"Merriam-Webster：enigma","url":"https://www.merriam-webster.com/dictionary/enigma"},{"title":"Merriam-Webster：puzzle","url":"https://www.merriam-webster.com/dictionary/puzzle"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"77":{"sense":"v. 想象；展望","collocations":["envision a future","imagine doing"],"example":"The planners envision a city with fewer private cars.","translation":"规划者设想了一座私家车更少的城市。","note":"envision常指设想未来情景；imagine使用范围更广。不要把imagine doing改成envision to do。","number":77,"resourceId":"doc-026-4-416b66281fc0","term":"envision","originalPair":"envision = imagine","needsCare":false,"sources":[{"title":"Merriam-Webster：envision","url":"https://www.merriam-webster.com/dictionary/envision"},{"title":"Merriam-Webster：imagine","url":"https://www.merriam-webster.com/dictionary/imagine"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"78":{"sense":"n. 典型；缩影","collocations":["the epitome of","the embodiment of"],"example":"The quiet garden is the epitome of tranquillity.","translation":"这座安静的花园堪称宁静的典范。","note":"epitome强调典型或缩影；embodiment强调某特质的具体体现，常见结构均为the ... of。","number":78,"resourceId":"doc-026-4-e221300cacc9","term":"epitome","originalPair":"epitome = embodiment","needsCare":false,"sources":[{"title":"Merriam-Webster：epitome","url":"https://www.merriam-webster.com/dictionary/epitome"},{"title":"Merriam-Webster：embodiment","url":"https://www.merriam-webster.com/dictionary/embodiment"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"79":{"sense":"v. 根除；彻底消除","collocations":["eradicate a disease","eliminate an error"],"example":"The campaign aims to eradicate the disease locally.","translation":"这项行动旨在当地根除这种疾病。","note":"eradicate强调连根清除；eliminate还可表示淘汰或排除，不一定对应根除疾病。","number":79,"resourceId":"doc-026-4-17a19df75a93","term":"eradicate","originalPair":"eradicate = eliminate","needsCare":false,"sources":[{"title":"Merriam-Webster：eradicate","url":"https://www.merriam-webster.com/dictionary/eradicate"},{"title":"Merriam-Webster：eliminate","url":"https://www.merriam-webster.com/dictionary/eliminate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"80":{"sense":"v. 升级；加剧","collocations":["escalate into","intensify pressure"],"example":"A minor disagreement escalated into a serious dispute.","translation":"一场小分歧升级成了严重争端。","note":"escalate常指程度或规模逐步升级；intensify侧重强度增加，不一定形成新的阶段。","number":80,"resourceId":"doc-026-4-c2208d7496a5","term":"escalate","originalPair":"escalate = intensify","needsCare":false,"sources":[{"title":"Merriam-Webster：escalate","url":"https://www.merriam-webster.com/dictionary/escalate"},{"title":"Merriam-Webster：intensify","url":"https://www.merriam-webster.com/dictionary/intensify"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"81":{"sense":"v. 唤起","collocations":["evoke memories","elicit information"],"example":"The smell of bread evokes memories of my childhood.","translation":"面包的气味唤起了我童年的回忆。","note":"evoke常指唤起记忆或感受；elicit常指通过提问等引出回答或反应。","number":81,"resourceId":"doc-026-4-c3b3c0cfa6f1","term":"evoke","originalPair":"evoke = elicit","needsCare":false,"sources":[{"title":"Merriam-Webster：evoke","url":"https://www.merriam-webster.com/dictionary/evoke"},{"title":"Merriam-Webster：elicit","url":"https://www.merriam-webster.com/dictionary/elicit"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"82":{"sense":"v. 加剧；使恶化","collocations":["exacerbate a problem","worsen a condition"],"example":"Poor ventilation can exacerbate indoor air pollution.","translation":"通风不良可能加剧室内空气污染。","note":"exacerbate通常及物，表示使已有问题更严重；worsen可及物或不及物。","number":82,"resourceId":"doc-026-4-72c999107609","term":"exacerbate","originalPair":"exacerbate = worsen","needsCare":false,"sources":[{"title":"Merriam-Webster：exacerbate","url":"https://www.merriam-webster.com/dictionary/exacerbate"},{"title":"Merriam-Webster：worsen","url":"https://www.merriam-webster.com/dictionary/worsen"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"83":{"sense":"v. 举例说明；作为典型","collocations":["exemplify a trend","illustrate a point"],"example":"This case exemplifies the difficulties faced by small firms.","translation":"这个案例体现了小企业面临的困难。","note":"exemplify可指本身就是典型；illustrate还可用图画或例子解释，不一定本身是典型。","number":83,"resourceId":"doc-026-4-1ca2f348a0c5","term":"exemplify","originalPair":"exemplify = illustrate","needsCare":false,"sources":[{"title":"Merriam-Webster：exemplify","url":"https://www.merriam-webster.com/dictionary/exemplify"},{"title":"Merriam-Webster：illustrate","url":"https://www.merriam-webster.com/dictionary/illustrate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"84":{"sense":"v. 利用；剥削","collocations":["exploit an opportunity","utilize a tool"],"example":"The firm was accused of exploiting temporary workers.","translation":"这家公司被指控剥削临时工。","note":"exploit在此带负面意义；utilize不表示剥削。利用机会的义项才可能较接近。","number":84,"resourceId":"doc-026-4-2d6853f07576","term":"exploit","originalPair":"exploit = utilize","needsCare":true,"sources":[{"title":"Merriam-Webster：exploit","url":"https://www.merriam-webster.com/dictionary/exploit"},{"title":"Merriam-Webster：utilize","url":"https://www.merriam-webster.com/dictionary/utilize"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"85":{"sense":"v. 促进；使更容易","collocations":["facilitate learning","ease the process"],"example":"Clear instructions facilitate independent study.","translation":"清楚的说明有助于自主学习。","note":"facilitate接活动或过程；ease也可表示减轻疼痛、焦虑。不要写facilitate someone to do。","number":85,"resourceId":"doc-026-4-b12b8227ec30","term":"facilitate","originalPair":"facilitate = ease","needsCare":false,"sources":[{"title":"Merriam-Webster：facilitate","url":"https://www.merriam-webster.com/dictionary/facilitate"},{"title":"Merriam-Webster：ease","url":"https://www.merriam-webster.com/dictionary/ease"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"86":{"sense":"v. 动摇；迟疑；衰弱","collocations":["falter during","hesitate to do"],"example":"Her voice faltered as she described the accident.","translation":"她描述事故时声音颤抖起来。","note":"falter可指声音不稳或力量减弱；hesitate通常指行动前迟疑，不能覆盖这些义项。","number":86,"resourceId":"doc-026-4-e488ac78f252","term":"falter","originalPair":"falter = hesitate","needsCare":false,"sources":[{"title":"Merriam-Webster：falter","url":"https://www.merriam-webster.com/dictionary/falter"},{"title":"Merriam-Webster：hesitate","url":"https://www.merriam-webster.com/dictionary/hesitate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"87":{"sense":"adj. 可实行的","collocations":["a feasible plan","a viable business"],"example":"The engineers proposed a feasible low-cost solution.","translation":"工程师提出了一个可行的低成本方案。","note":"feasible强调能够实行；viable还强调能持续运作或生存，如商业模式能否维持。","number":87,"resourceId":"doc-026-5-025c64bec434","term":"feasible","originalPair":"feasible = viable","needsCare":false,"sources":[{"title":"Merriam-Webster：feasible","url":"https://www.merriam-webster.com/dictionary/feasible"},{"title":"Merriam-Webster：viable","url":"https://www.merriam-webster.com/dictionary/viable"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"88":{"sense":"adj. 有限的","collocations":["finite resources","a limited supply"],"example":"Fresh water is a finite resource in this region.","translation":"在该地区，淡水是一种有限资源。","note":"finite表示有界限、并非无限；limited还可表示数量少或能力受限，不必然对应同一判断。","number":88,"resourceId":"doc-026-5-b24e091dba51","term":"finite","originalPair":"finite = limited","needsCare":false,"sources":[{"title":"Merriam-Webster：finite","url":"https://www.merriam-webster.com/dictionary/finite"},{"title":"Merriam-Webster：limited","url":"https://www.merriam-webster.com/dictionary/limited"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"89":{"sense":"v. 波动","collocations":["fluctuate between","vary by"],"example":"Electricity demand fluctuates throughout the day.","translation":"用电需求在一天中不断波动。","note":"fluctuate强调上下变化，通常不及物；vary可表示不同对象之间有差异，也可及物。","number":89,"resourceId":"doc-026-5-f63de70e105f","term":"fluctuate","originalPair":"fluctuate = vary","needsCare":false,"sources":[{"title":"Merriam-Webster：fluctuate","url":"https://www.merriam-webster.com/dictionary/fluctuate"},{"title":"Merriam-Webster：vary","url":"https://www.merriam-webster.com/dictionary/vary"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"90":{"sense":"adj. 难对付的；令人敬畏的","collocations":["a formidable challenge","a challenging task"],"example":"Funding remains a formidable obstacle for the project.","translation":"资金仍是这个项目难以克服的障碍。","note":"formidable常强调强大到令人畏惧或敬畏；challenging只表示有挑战性，程度不必相同。","number":90,"resourceId":"doc-026-5-95c75448b2f3","term":"formidable","originalPair":"formidable = challenging","needsCare":true,"sources":[{"title":"Merriam-Webster：formidable","url":"https://www.merriam-webster.com/dictionary/formidable"},{"title":"Merriam-Webster：challenging","url":"https://www.merriam-webster.com/dictionary/challenging"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"91":{"sense":"v. 培养；促进","collocations":["foster cooperation","nurture talent"],"example":"Shared projects can foster cooperation between schools.","translation":"共同项目可以促进学校之间的合作。","note":"nurture强调长期照料、培育；foster可泛指创造有利条件，不能把所有培养都理解为照顾。","number":91,"resourceId":"doc-026-5-26b5dd78d219","term":"foster","originalPair":"foster = nurture","needsCare":false,"sources":[{"title":"Merriam-Webster：foster","url":"https://www.merriam-webster.com/dictionary/foster"},{"title":"Merriam-Webster：nurture","url":"https://www.merriam-webster.com/dictionary/nurture"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"92":{"sense":"adj. 欺诈的","collocations":["fraudulent claims","deceptive advertising"],"example":"The agency rejected several fraudulent applications.","translation":"机构驳回了几份欺诈性申请。","note":"fraudulent涉及欺诈或骗取利益；deceptive可只是误导性的，不能未经证据就指控为欺诈。","number":92,"resourceId":"doc-026-5-e1c723d150e1","term":"fraudulent","originalPair":"fraudulent = deceptive","needsCare":false,"sources":[{"title":"Merriam-Webster：fraudulent","url":"https://www.merriam-webster.com/dictionary/fraudulent"},{"title":"Merriam-Webster：deceptive","url":"https://www.merriam-webster.com/dictionary/deceptive"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"93":{"sense":"adj. 徒劳的","collocations":["a futile attempt","a fruitless search"],"example":"Without reliable data, further debate would be futile.","translation":"没有可靠数据，继续争论将是徒劳的。","note":"fruitless也指没有成果；futile常强调难以产生有用结果，语气偏强。","number":93,"resourceId":"doc-026-5-43edc5735a3e","term":"futile","originalPair":"futile = fruitless","needsCare":false,"sources":[{"title":"Merriam-Webster：futile","url":"https://www.merriam-webster.com/dictionary/futile"},{"title":"Merriam-Webster：fruitless","url":"https://www.merriam-webster.com/dictionary/fruitless"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"94":{"sense":"v. 测量；估计","collocations":["gauge demand","measure distance"],"example":"The survey will gauge demand for evening buses.","translation":"调查将估计夜间公交的需求。","note":"gauge常用于判断程度或需求，也可测量；measure更常用于按尺度量化。","number":94,"resourceId":"doc-026-5-36b10399c024","term":"gauge","originalPair":"gauge = measure","needsCare":false,"sources":[{"title":"Merriam-Webster：gauge","url":"https://www.merriam-webster.com/dictionary/gauge"},{"title":"Merriam-Webster：measure","url":"https://www.merriam-webster.com/dictionary/measure"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"95":{"sense":"v. 产生","collocations":["generate income","produce electricity"],"example":"The new centre could generate income for local businesses.","translation":"新中心可能为当地企业带来收入。","note":"generate常指引发或产生收益、能量等；produce还可指制造实物，搭配需逐项核对。","number":95,"resourceId":"doc-026-5-1c8441cc0157","term":"generate","originalPair":"generate = produce","needsCare":false,"sources":[{"title":"Merriam-Webster：generate","url":"https://www.merriam-webster.com/dictionary/generate"},{"title":"Merriam-Webster：produce","url":"https://www.merriam-webster.com/dictionary/produce"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"96":{"sense":"adj. 真的；真诚的","collocations":["genuine concern","authentic art"],"example":"The tutor showed genuine concern for her students.","translation":"导师真诚地关心学生。","note":"genuine表示真诚时不宜直接换成authentic；authentic常强调非伪造或符合原貌。","number":96,"resourceId":"doc-026-5-0659a24df4d1","term":"genuine","originalPair":"genuine = authentic","needsCare":false,"sources":[{"title":"Merriam-Webster：genuine","url":"https://www.merriam-webster.com/dictionary/genuine"},{"title":"Merriam-Webster：authentic","url":"https://www.merriam-webster.com/dictionary/authentic"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"97":{"sense":"v. 理解；抓住","collocations":["grasp a concept","comprehend a text"],"example":"It took me several examples to grasp the concept.","translation":"看了几个例子后，我才理解这个概念。","note":"comprehend对应理解义；grasp还可指用手抓牢，不能在物理抓取义中替换。","number":97,"resourceId":"doc-026-5-71a1b7bab4ee","term":"grasp","originalPair":"grasp = comprehend","needsCare":false,"sources":[{"title":"Merriam-Webster：grasp","url":"https://www.merriam-webster.com/dictionary/grasp"},{"title":"Merriam-Webster：comprehend","url":"https://www.merriam-webster.com/dictionary/comprehend"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"98":{"sense":"v. 阻碍","collocations":["hinder progress","impede access"],"example":"Limited internet access can hinder students' progress.","translation":"上网条件有限可能阻碍学生进步。","note":"impede也指妨碍进展，语气较正式；两词可接过程或行动，不表示完全使其不可能。","number":98,"resourceId":"doc-026-5-ee1d9455805d","term":"hinder","originalPair":"hinder = impede","needsCare":false,"sources":[{"title":"Merriam-Webster：hinder","url":"https://www.merriam-webster.com/dictionary/hinder"},{"title":"Merriam-Webster：impede","url":"https://www.merriam-webster.com/dictionary/impede"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"99":{"sense":"v. 使浸入；使沉浸","collocations":["immerse yourself in","be engrossed in"],"example":"She immersed herself in the study of local history.","translation":"她潜心研究当地历史。","note":"immerse常用immerse yourself in；engross更常用be engrossed in，改写时要调整结构，不能只换一个动词。","number":99,"resourceId":"doc-026-5-ab7a1860c353","term":"immerse","originalPair":"immerse = engross","needsCare":true,"sources":[{"title":"Merriam-Webster：immerse","url":"https://www.merriam-webster.com/dictionary/immerse"},{"title":"Merriam-Webster：engross","url":"https://www.merriam-webster.com/dictionary/engross"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"100":{"sense":"v. 损害；削弱功能","collocations":["impair memory","damage a building"],"example":"Lack of sleep can impair concentration.","translation":"睡眠不足可能损害专注力。","note":"impair常强调功能或能力受损；damage范围更广。","number":100,"resourceId":"doc-026-5-9447b9a8aae4","term":"impair","originalPair":"impair = damage","needsCare":false,"sources":[{"title":"Merriam-Webster：impair","url":"https://www.merriam-webster.com/dictionary/impair"},{"title":"Merriam-Webster：damage","url":"https://www.merriam-webster.com/dictionary/damage"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"101":{"sense":"adj. 必要的；紧迫的","collocations":["it is imperative that","crucial to"],"example":"It is imperative that every participant receives clear instructions.","translation":"每位参与者都得到清楚的说明，这一点至关重要。","note":"imperative常强调必须做某事；crucial表示非常重要，不一定带义务或命令色彩。","number":101,"resourceId":"doc-026-5-455f95d22c79","term":"imperative","originalPair":"imperative = crucial","needsCare":false,"sources":[{"title":"Merriam-Webster：imperative","url":"https://www.merriam-webster.com/dictionary/imperative"},{"title":"Merriam-Webster：crucial","url":"https://www.merriam-webster.com/dictionary/crucial"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"102":{"sense":"v. 实施；执行","collocations":["implement a policy","execute a plan"],"example":"The school will implement the new policy in September.","translation":"学校将于九月实施新政策。","note":"execute可指执行计划，也有处决等义项；此处只比较实施计划的义项。","number":102,"resourceId":"doc-026-5-3ed583f4cce6","term":"implement","originalPair":"implement = execute","needsCare":false,"sources":[{"title":"Merriam-Webster：implement","url":"https://www.merriam-webster.com/dictionary/implement"},{"title":"Merriam-Webster：execute","url":"https://www.merriam-webster.com/dictionary/execute"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"103":{"sense":"v. 牵涉；显示与不良行为有关","collocations":["implicate someone in","involve someone in"],"example":"The emails implicated two managers in the fraud.","translation":"这些邮件显示两名经理牵涉该欺诈案。","note":"implicate常涉及犯罪、责任或不良后果；involve较中性，不能随意把一般参与写成涉嫌。","number":103,"resourceId":"doc-026-5-3d2709f57f3b","term":"implicate","originalPair":"implicate = involve","needsCare":true,"sources":[{"title":"Merriam-Webster：implicate","url":"https://www.merriam-webster.com/dictionary/implicate"},{"title":"Merriam-Webster：involve","url":"https://www.merriam-webster.com/dictionary/involve"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"104":{"sense":"adj. 含蓄的；未明说的","collocations":["implicit in","implied criticism"],"example":"There is an implicit assumption that all users have internet access.","translation":"这里隐含着所有用户都能上网的假设。","note":"implicit指未明确说出但可理解的；implied突出被话语或情境暗示，具体语法不同。","number":104,"resourceId":"doc-026-5-60da2c8c75c1","term":"implicit","originalPair":"implicit = implied","needsCare":false,"sources":[{"title":"Merriam-Webster：implicit","url":"https://www.merriam-webster.com/dictionary/implicit"},{"title":"Merriam-Webster：implied","url":"https://www.merriam-webster.com/dictionary/implied"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"105":{"sense":"v. 强加；征收","collocations":["impose a tax on","enforce a law"],"example":"The city imposed a charge on vehicles entering the centre.","translation":"城市对进入市中心的车辆收取费用。","note":"impose指施加规则或负担；enforce指执行已有规则，使人遵守，阶段不同。","number":105,"resourceId":"doc-026-5-d9a56807599c","term":"impose","originalPair":"impose = enforce","needsCare":true,"sources":[{"title":"Merriam-Webster：impose","url":"https://www.merriam-webster.com/dictionary/impose"},{"title":"Merriam-Webster：enforce","url":"https://www.merriam-webster.com/dictionary/enforce"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"106":{"sense":"n. 激励因素","collocations":["an incentive to do","motivation for"],"example":"A small grant gave residents an incentive to insulate their homes.","translation":"一小笔补助激励居民给住宅加装保温层。","note":"incentive常指外部奖励或刺激；motivation可指内在动力，不是所有动力都来自奖励。","number":106,"resourceId":"doc-026-5-f636713d2c43","term":"incentive","originalPair":"incentive = motivation","needsCare":false,"sources":[{"title":"Merriam-Webster：incentive","url":"https://www.merriam-webster.com/dictionary/incentive"},{"title":"Merriam-Webster：motivation","url":"https://www.merriam-webster.com/dictionary/motivation"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"107":{"sense":"adj. 附带的；偶然的","collocations":["incidental to","secondary importance"],"example":"Travel expenses are incidental to the main cost of the project.","translation":"差旅费用是项目主要成本之外的附带支出。","note":"incidental可指附带或偶然；secondary指次要或第二位，不能覆盖所有偶然义。","number":107,"resourceId":"doc-026-5-876cfa9737eb","term":"incidental","originalPair":"incidental = secondary","needsCare":true,"sources":[{"title":"Merriam-Webster：incidental","url":"https://www.merriam-webster.com/dictionary/incidental"},{"title":"Merriam-Webster：secondary","url":"https://www.merriam-webster.com/dictionary/secondary"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"108":{"sense":"v. 纳入；并入","collocations":["incorporate into","integrate into"],"example":"The revised course incorporates feedback from students.","translation":"修改后的课程纳入了学生的反馈。","note":"incorporate强调将某部分纳入；integrate强调结合成协调的整体，不一定涉及同样的修改方式。","number":108,"resourceId":"doc-026-5-98dc4f2ed297","term":"incorporate","originalPair":"incorporate = integrate","needsCare":false,"sources":[{"title":"Merriam-Webster：incorporate","url":"https://www.merriam-webster.com/dictionary/incorporate"},{"title":"Merriam-Webster：integrate","url":"https://www.merriam-webster.com/dictionary/integrate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"109":{"sense":"adj. 本土的；原住的","collocations":["indigenous to","native species"],"example":"These plants are indigenous to the island.","translation":"这些植物原产于这座岛。","note":"两词都可指本土物种；谈人群时应尊重具体社群的自称，不能当作随意替换的标签。","number":109,"resourceId":"doc-026-6-0d2a844c533e","term":"indigenous","originalPair":"indigenous = native","needsCare":false,"sources":[{"title":"Merriam-Webster：indigenous","url":"https://www.merriam-webster.com/dictionary/indigenous"},{"title":"Merriam-Webster：native","url":"https://www.merriam-webster.com/dictionary/native"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"110":{"sense":"v. 引起；诱导","collocations":["induce sleep","provoke a reaction"],"example":"The medicine may induce drowsiness.","translation":"这种药可能引起困倦。","note":"induce常指导致某状态；provoke常引发强烈或负面反应，不适合所有生理状态。","number":110,"resourceId":"doc-026-6-7f45ce025e7a","term":"induce","originalPair":"induce = provoke","needsCare":false,"sources":[{"title":"Merriam-Webster：induce","url":"https://www.merriam-webster.com/dictionary/induce"},{"title":"Merriam-Webster：provoke","url":"https://www.merriam-webster.com/dictionary/provoke"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"111":{"sense":"v. 推断","collocations":["infer from","deduce from"],"example":"We should not infer a general trend from one response.","translation":"我们不应根据一个回答推断整体趋势。","note":"infer是读者或观察者得出结论；imply是信息或说话者暗示。deduce强调推理依据。","number":111,"resourceId":"doc-026-6-2af94c779b8f","term":"infer","originalPair":"infer = deduce","needsCare":false,"sources":[{"title":"Merriam-Webster：infer","url":"https://www.merriam-webster.com/dictionary/infer"},{"title":"Merriam-Webster：deduce","url":"https://www.merriam-webster.com/dictionary/deduce"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"112":{"sense":"adj. 巧妙的；有独创性的","collocations":["an ingenious solution","an innovative product"],"example":"The students devised an ingenious way to reuse rainwater.","translation":"学生想出了一个巧妙的雨水再利用办法。","note":"ingenious强调聪明巧妙；innovative强调采用新方法，新的设计未必一定巧妙。","number":112,"resourceId":"doc-026-6-335fdc6584a5","term":"ingenious","originalPair":"ingenious = innovative","needsCare":true,"sources":[{"title":"Merriam-Webster：ingenious","url":"https://www.merriam-webster.com/dictionary/ingenious"},{"title":"Merriam-Webster：innovative","url":"https://www.merriam-webster.com/dictionary/innovative"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"113":{"sense":"adj. 内在的；固有的","collocations":["inherent in","intrinsic to"],"example":"Some uncertainty is inherent in long-term forecasting.","translation":"长期预测本身就存在一定不确定性。","note":"两词都可表示内在属性；常见介词分别有inherent in与intrinsic to，不能漏掉介词。","number":113,"resourceId":"doc-026-6-bb39ec15b129","term":"inherent","originalPair":"inherent = intrinsic","needsCare":false,"sources":[{"title":"Merriam-Webster：inherent","url":"https://www.merriam-webster.com/dictionary/inherent"},{"title":"Merriam-Webster：intrinsic","url":"https://www.merriam-webster.com/dictionary/intrinsic"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"114":{"sense":"v. 抑制；妨碍","collocations":["inhibit growth","restrain spending"],"example":"Poor lighting can inhibit plant growth.","translation":"光线不足会抑制植物生长。","note":"inhibit可指阻碍过程或心理上的抑制；restrain更常指约束行为、情绪或身体动作。","number":114,"resourceId":"doc-026-6-2862a0cb5dfa","term":"inhibit","originalPair":"inhibit = restrain","needsCare":false,"sources":[{"title":"Merriam-Webster：inhibit","url":"https://www.merriam-webster.com/dictionary/inhibit"},{"title":"Merriam-Webster：restrain","url":"https://www.merriam-webster.com/dictionary/restrain"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"115":{"sense":"v. 发起；开始","collocations":["initiate a project","commence work"],"example":"The charity initiated a programme for adult learners.","translation":"慈善机构发起了一项成人学习项目。","note":"initiate强调启动或发起；commence通常表示开始，未必说明谁发起。","number":115,"resourceId":"doc-026-6-f5918d410e1c","term":"initiate","originalPair":"initiate = commence","needsCare":false,"sources":[{"title":"Merriam-Webster：initiate","url":"https://www.merriam-webster.com/dictionary/initiate"},{"title":"Merriam-Webster：commence","url":"https://www.merriam-webster.com/dictionary/commence"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"116":{"sense":"v. 创新","collocations":["innovate in","pioneer a technique"],"example":"Local firms need to innovate to remain competitive.","translation":"本地企业需要创新才能保持竞争力。","note":"innovate常不及物；pioneer可直接接开创的技术或方法，不能原样替换句法。","number":116,"resourceId":"doc-026-6-f296c36a40cc","term":"innovate","originalPair":"innovate = pioneer","needsCare":true,"sources":[{"title":"Merriam-Webster：innovate","url":"https://www.merriam-webster.com/dictionary/innovate"},{"title":"Merriam-Webster：pioneer","url":"https://www.merriam-webster.com/dictionary/pioneer"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"117":{"sense":"n. 询问；调查","collocations":["an inquiry into","conduct an investigation"],"example":"The council launched an inquiry into the bridge collapse.","translation":"市议会启动了对桥梁坍塌的调查。","note":"inquiry既可询问也可正式调查；investigation强调系统调查，普通问询不一定构成调查。","number":117,"resourceId":"doc-026-6-4a88cba14519","term":"inquiry","originalPair":"inquiry = investigation","needsCare":false,"sources":[{"title":"Merriam-Webster：inquiry","url":"https://www.merriam-webster.com/dictionary/inquiry"},{"title":"Merriam-Webster：investigation","url":"https://www.merriam-webster.com/dictionary/investigation"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"118":{"sense":"n. 洞察；深入理解","collocations":["insight into","an understanding of"],"example":"The interviews provided insight into students' daily challenges.","translation":"访谈让人更深入地了解学生日常面临的困难。","note":"insight常强调新颖或深入的认识；understanding较宽泛，通常用of连接所理解的对象。","number":118,"resourceId":"doc-026-6-5234bf219550","term":"insight","originalPair":"insight = understanding","needsCare":false,"sources":[{"title":"Merriam-Webster：insight","url":"https://www.merriam-webster.com/dictionary/insight"},{"title":"Merriam-Webster：understanding","url":"https://www.merriam-webster.com/dictionary/understanding"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"119":{"sense":"adj. 必不可少的；组成整体的","collocations":["integral to","an integral part of"],"example":"Public libraries are an integral part of community life.","translation":"公共图书馆是社区生活不可或缺的组成部分。","note":"integral常强调属于整体且重要；essential强调必要，不一定是组成部分。","number":119,"resourceId":"doc-026-6-9c4e1eec705b","term":"integral","originalPair":"integral = essential","needsCare":false,"sources":[{"title":"Merriam-Webster：integral","url":"https://www.merriam-webster.com/dictionary/integral"},{"title":"Merriam-Webster：essential","url":"https://www.merriam-webster.com/dictionary/essential"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"120":{"sense":"n. 正直；完整性","collocations":["personal integrity","structural integrity"],"example":"Researchers must protect the integrity of their data.","translation":"研究者必须维护数据的完整性与可信性。","note":"honesty对应诚实义；integrity还可指数据或结构的完整，不能都译成诚实。","number":120,"resourceId":"doc-026-6-9447d4e8b825","term":"integrity","originalPair":"integrity = honesty","needsCare":true,"sources":[{"title":"Merriam-Webster：integrity","url":"https://www.merriam-webster.com/dictionary/integrity"},{"title":"Merriam-Webster：honesty","url":"https://www.merriam-webster.com/dictionary/honesty"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"121":{"sense":"adj. 错综复杂的","collocations":["intricate details","a complex system"],"example":"The map shows an intricate network of narrow streets.","translation":"地图显示了一套错综复杂的狭窄街道网络。","note":"intricate强调细节交织精密；complex泛指组成或理解困难，侧重点不同。","number":121,"resourceId":"doc-026-6-1f5072ace043","term":"intricate","originalPair":"intricate = complex","needsCare":false,"sources":[{"title":"Merriam-Webster：intricate","url":"https://www.merriam-webster.com/dictionary/intricate"},{"title":"Merriam-Webster：complex","url":"https://www.merriam-webster.com/dictionary/complex"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"122":{"sense":"v. 援引；诉诸","collocations":["invoke a rule","evoke a feeling"],"example":"The committee invoked a safety rule to postpone the event.","translation":"委员会援引安全规则推迟了活动。","note":"invoke常指援引法律、原则或权威；evoke指唤起记忆或情感，原配对不宜作为普通同义替换。","number":122,"resourceId":"doc-026-6-0e44e8148df8","term":"invoke","originalPair":"invoke = evoke","needsCare":true,"sources":[{"title":"Merriam-Webster：invoke","url":"https://www.merriam-webster.com/dictionary/invoke"},{"title":"Merriam-Webster：evoke","url":"https://www.merriam-webster.com/dictionary/evoke"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"123":{"sense":"adj. 无法修复的","collocations":["irreparable damage","irreversible change"],"example":"The fire caused irreparable damage to the collection.","translation":"大火对藏品造成了无法修复的损害。","note":"irreparable指不能修好；irreversible指不能逆转。不可逆的改变未必是损害。","number":123,"resourceId":"doc-026-6-73d892103193","term":"irreparable","originalPair":"irreparable = irreversible","needsCare":true,"sources":[{"title":"Merriam-Webster：irreparable","url":"https://www.merriam-webster.com/dictionary/irreparable"},{"title":"Merriam-Webster：irreversible","url":"https://www.merriam-webster.com/dictionary/irreversible"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"124":{"sense":"adj. 孤立的；偏远的","collocations":["an isolated village","a secluded beach"],"example":"The clinic serves several isolated mountain villages.","translation":"诊所服务于几个偏远的山村。","note":"isolated强调分离、远离或缺乏联系；secluded常强调僻静隐蔽，未必缺乏联系。","number":124,"resourceId":"doc-026-6-e4a26d2c4285","term":"isolated","originalPair":"isolated = secluded","needsCare":false,"sources":[{"title":"Merriam-Webster：isolated","url":"https://www.merriam-webster.com/dictionary/isolated"},{"title":"Merriam-Webster：secluded","url":"https://www.merriam-webster.com/dictionary/secluded"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"125":{"sense":"v. 危及","collocations":["jeopardize safety","endanger wildlife"],"example":"Ignoring maintenance could jeopardize passenger safety.","translation":"忽视维护可能危及乘客安全。","note":"两词在使某事面临危险时接近；jeopardize常用于机会、计划或安全，不等于已经造成损失。","number":125,"resourceId":"doc-026-6-9965d622f47c","term":"jeopardize","originalPair":"jeopardize = endanger","needsCare":false,"sources":[{"title":"Merriam-Webster：jeopardize","url":"https://www.merriam-webster.com/dictionary/jeopardize"},{"title":"Merriam-Webster：endanger","url":"https://www.merriam-webster.com/dictionary/endanger"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"126":{"sense":"adj. 渴望的；热切的","collocations":["keen to do","eager to do"],"example":"Many residents are keen to join the gardening project.","translation":"许多居民热切希望参加园艺项目。","note":"eager对应热切义；keen还可指敏锐或锋利。英式keen on后常接名词或动名词。","number":126,"resourceId":"doc-026-6-b2ffe82863a6","term":"keen","originalPair":"keen = eager","needsCare":false,"sources":[{"title":"Merriam-Webster：keen","url":"https://www.merriam-webster.com/dictionary/keen"},{"title":"Merriam-Webster：eager","url":"https://www.merriam-webster.com/dictionary/eager"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"127":{"sense":"adj. 合法的；正当的","collocations":["legitimate concerns","a valid argument"],"example":"Residents have legitimate concerns about road safety.","translation":"居民对道路安全的担忧是正当的。","note":"legitimate可指合法或合理；valid可指论证成立或证件有效，不能都译为合法。","number":127,"resourceId":"doc-026-6-6122bce93e2f","term":"legitimate","originalPair":"legitimate = valid","needsCare":false,"sources":[{"title":"Merriam-Webster：legitimate","url":"https://www.merriam-webster.com/dictionary/legitimate"},{"title":"Merriam-Webster：valid","url":"https://www.merriam-webster.com/dictionary/valid"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"128":{"sense":"v. 放大","collocations":["magnify an image","amplify a signal"],"example":"The lens can magnify tiny details on the surface.","translation":"镜片能够放大表面的微小细节。","note":"magnify常指视觉放大，也可夸大问题；amplify常指声音或信号增强，不适用于所有镜片语境。","number":128,"resourceId":"doc-026-6-f96475e2eeb5","term":"magnify","originalPair":"magnify = amplify","needsCare":false,"sources":[{"title":"Merriam-Webster：magnify","url":"https://www.merriam-webster.com/dictionary/magnify"},{"title":"Merriam-Webster：amplify","url":"https://www.merriam-webster.com/dictionary/amplify"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"129":{"sense":"v. 显示；表明","collocations":["manifest itself in","demonstrate an effect"],"example":"Stress can manifest itself in changes in sleep patterns.","translation":"压力可能表现为睡眠模式的变化。","note":"manifest常用反身或被动结构；demonstrate还可指通过证据证明，不能忽略论证强度。","number":129,"resourceId":"doc-026-6-d74c14992199","term":"manifest","originalPair":"manifest = demonstrate","needsCare":false,"sources":[{"title":"Merriam-Webster：manifest","url":"https://www.merriam-webster.com/dictionary/manifest"},{"title":"Merriam-Webster：demonstrate","url":"https://www.merriam-webster.com/dictionary/demonstrate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"130":{"sense":"v. 操纵；控制","collocations":["manipulate data","exploit a weakness"],"example":"The report warns that images can be manipulated.","translation":"报告警告图像可能被人为篡改。","note":"manipulate可指技术操作或不当操纵；exploit指利用或剥削，不等于修改图像。","number":130,"resourceId":"doc-026-6-6ed004aa5c8b","term":"manipulate","originalPair":"manipulate = exploit","needsCare":true,"sources":[{"title":"Merriam-Webster：manipulate","url":"https://www.merriam-webster.com/dictionary/manipulate"},{"title":"Merriam-Webster：exploit","url":"https://www.merriam-webster.com/dictionary/exploit"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"131":{"sense":"adj. 微小的；边缘的","collocations":["a marginal increase","negligible costs"],"example":"The change produced only a marginal improvement.","translation":"这项改变只带来了微小的改善。","note":"marginal表示小或处在边缘；negligible强调小到可以忽略，不能把任何微小变化都说成可忽略。","number":131,"resourceId":"doc-026-7-23c8b9959198","term":"marginal","originalPair":"marginal = negligible","needsCare":true,"sources":[{"title":"Merriam-Webster：marginal","url":"https://www.merriam-webster.com/dictionary/marginal"},{"title":"Merriam-Webster：negligible","url":"https://www.merriam-webster.com/dictionary/negligible"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"132":{"sense":"v. 调解","collocations":["mediate between","intervene in"],"example":"A neutral adviser mediated between the two groups.","translation":"一位中立顾问在两组人之间进行调解。","note":"mediate以促成双方达成一致为目的；intervene只是介入，不一定调解或保持中立。","number":132,"resourceId":"doc-026-7-4692bc309643","term":"mediate","originalPair":"mediate = intervene","needsCare":false,"sources":[{"title":"Merriam-Webster：mediate","url":"https://www.merriam-webster.com/dictionary/mediate"},{"title":"Merriam-Webster：intervene","url":"https://www.merriam-webster.com/dictionary/intervene"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"133":{"sense":"v. 合并","collocations":["merge with","amalgamate into"],"example":"The two colleges plan to merge next year.","translation":"两所学院计划明年合并。","note":"amalgamate也可指合并，较正式；注意merge with和merge into分别表示与谁合并、并入何处。","number":133,"resourceId":"doc-026-7-636bccf4b1fb","term":"merge","originalPair":"merge = amalgamate","needsCare":false,"sources":[{"title":"Merriam-Webster：merge","url":"https://www.merriam-webster.com/dictionary/merge"},{"title":"Merriam-Webster：amalgamate","url":"https://www.merriam-webster.com/dictionary/amalgamate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"134":{"sense":"adj. 有条理的","collocations":["a methodical approach","a systematic review"],"example":"Her methodical approach reduced errors in the records.","translation":"她有条理的方法减少了记录中的错误。","note":"methodical强调按部就班；systematic强调按系统或方法组织，学术中的systematic review另有具体要求。","number":134,"resourceId":"doc-026-7-837163256bc6","term":"methodical","originalPair":"methodical = systematic","needsCare":false,"sources":[{"title":"Merriam-Webster：methodical","url":"https://www.merriam-webster.com/dictionary/methodical"},{"title":"Merriam-Webster：systematic","url":"https://www.merriam-webster.com/dictionary/systematic"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"135":{"sense":"v. 减轻；缓和","collocations":["mitigate risks","alleviate pain"],"example":"Additional training could mitigate the risk of accidents.","translation":"额外培训可以降低事故风险。","note":"mitigate常接风险、影响或严重程度；alleviate常接痛苦、负担或问题，不保证每个宾语都同样自然。","number":135,"resourceId":"doc-026-7-2b87db3bc805","term":"mitigate","originalPair":"mitigate = alleviate","needsCare":false,"sources":[{"title":"Merriam-Webster：mitigate","url":"https://www.merriam-webster.com/dictionary/mitigate"},{"title":"Merriam-Webster：alleviate","url":"https://www.merriam-webster.com/dictionary/alleviate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"136":{"sense":"v. 动员","collocations":["mobilize support","assemble a group"],"example":"The campaign mobilized volunteers across the region.","translation":"这项活动动员了整个地区的志愿者。","note":"mobilize强调使资源或人员准备行动；assemble可能仅仅聚集起来，并未动员投入行动。","number":136,"resourceId":"doc-026-7-70312479b3bb","term":"mobilize","originalPair":"mobilize = assemble","needsCare":false,"sources":[{"title":"Merriam-Webster：mobilize","url":"https://www.merriam-webster.com/dictionary/mobilize"},{"title":"Merriam-Webster：assemble","url":"https://www.merriam-webster.com/dictionary/assemble"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"137":{"sense":"v. 修改；调整","collocations":["modify a design","alter a plan"],"example":"The team modified the design after testing the prototype.","translation":"团队在测试原型后修改了设计。","note":"modify常指局部调整；alter一般指改变，不一定说明改变范围很小。","number":137,"resourceId":"doc-026-7-44ffc67637f5","term":"modify","originalPair":"modify = alter","needsCare":false,"sources":[{"title":"Merriam-Webster：modify","url":"https://www.merriam-webster.com/dictionary/modify"},{"title":"Merriam-Webster：alter","url":"https://www.merriam-webster.com/dictionary/alter"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"138":{"sense":"v. 监测；持续观察","collocations":["monitor progress","supervise staff"],"example":"Sensors monitor air quality near the main road.","translation":"传感器监测主干道附近的空气质量。","note":"monitor重在观察或记录变化；supervise重在监督指导人员或活动，不能用来泛指传感器测量。","number":138,"resourceId":"doc-026-7-22b5c71824f4","term":"monitor","originalPair":"monitor = supervise","needsCare":true,"sources":[{"title":"Merriam-Webster：monitor","url":"https://www.merriam-webster.com/dictionary/monitor"},{"title":"Merriam-Webster：supervise","url":"https://www.merriam-webster.com/dictionary/supervise"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"139":{"sense":"adj. 平凡的；乏味的","collocations":["mundane tasks","an ordinary day"],"example":"The app handles mundane tasks such as sorting receipts.","translation":"应用程序处理整理收据等日常琐事。","note":"mundane常带平淡乏味意味；ordinary只是普通，不必带负面评价。","number":139,"resourceId":"doc-026-7-b65c73671efc","term":"mundane","originalPair":"mundane = ordinary","needsCare":false,"sources":[{"title":"Merriam-Webster：mundane","url":"https://www.merriam-webster.com/dictionary/mundane"},{"title":"Merriam-Webster：ordinary","url":"https://www.merriam-webster.com/dictionary/ordinary"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"140":{"sense":"v. 抵消；使无效；否定","collocations":["negate benefits","nullify an agreement"],"example":"High fees can negate the benefits of a discount.","translation":"高额费用可能抵消折扣带来的好处。","note":"nullify常指使协议或结果无效；negate还可指否定或抵消，不一定涉及正式撤销。","number":140,"resourceId":"doc-026-7-3a24caa93bcc","term":"negate","originalPair":"negate = nullify","needsCare":true,"sources":[{"title":"Merriam-Webster：negate","url":"https://www.merriam-webster.com/dictionary/negate"},{"title":"Merriam-Webster：nullify","url":"https://www.merriam-webster.com/dictionary/nullify"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"141":{"sense":"adj. 微不足道的","collocations":["a negligible effect","statistically insignificant"],"example":"The extra page added a negligible amount of weight.","translation":"多出的一页增加的重量微不足道。","note":"negligible指小到可忽略；insignificant可指不重要，统计学中的不显著另有含义。","number":141,"resourceId":"doc-026-7-27d8778aeb95","term":"negligible","originalPair":"negligible = insignificant","needsCare":false,"sources":[{"title":"Merriam-Webster：negligible","url":"https://www.merriam-webster.com/dictionary/negligible"},{"title":"Merriam-Webster：insignificant","url":"https://www.merriam-webster.com/dictionary/insignificant"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"142":{"sense":"adj. 新颖的","collocations":["a novel approach","an innovative solution"],"example":"The study proposes a novel approach to adult education.","translation":"研究提出了一种新颖的成人教育方法。","note":"novel强调新或不同寻常；innovative强调引入新方法。novel作名词时是小说。","number":142,"resourceId":"doc-026-7-7a72c10842ee","term":"novel","originalPair":"novel = innovative","needsCare":false,"sources":[{"title":"Merriam-Webster：novel","url":"https://www.merriam-webster.com/dictionary/novel"},{"title":"Merriam-Webster：innovative","url":"https://www.merriam-webster.com/dictionary/innovative"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"143":{"sense":"v. 培育；滋养","collocations":["nurture talent","cultivate interest"],"example":"Patient feedback can nurture a learner's confidence.","translation":"耐心的反馈能够培养学习者的信心。","note":"nurture偏重持续照料和支持；cultivate也可指有意培养技能、关系或兴趣。","number":143,"resourceId":"doc-026-7-472ebf4b5362","term":"nurture","originalPair":"nurture = cultivate","needsCare":false,"sources":[{"title":"Merriam-Webster：nurture","url":"https://www.merriam-webster.com/dictionary/nurture"},{"title":"Merriam-Webster：cultivate","url":"https://www.merriam-webster.com/dictionary/cultivate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"144":{"sense":"adj. 已淘汰的；过时不用的","collocations":["obsolete equipment","outdated information"],"example":"The museum keeps obsolete computers for teaching purposes.","translation":"博物馆保留已淘汰的电脑用于教学。","note":"obsolete常指已不再使用；outdated可只是落后于现状，尚未完全淘汰。","number":144,"resourceId":"doc-026-7-5deeaf272439","term":"obsolete","originalPair":"obsolete = outdated","needsCare":true,"sources":[{"title":"Merriam-Webster：obsolete","url":"https://www.merriam-webster.com/dictionary/obsolete"},{"title":"Merriam-Webster：outdated","url":"https://www.merriam-webster.com/dictionary/outdated"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"145":{"sense":"adj. 不祥的","collocations":["an ominous sign","a threatening message"],"example":"Dark clouds were an ominous sign for the outdoor concert.","translation":"乌云对户外音乐会来说是个不祥的征兆。","note":"ominous表示预示坏事；threatening可指直接带威胁性，未必是预兆。","number":145,"resourceId":"doc-026-7-9e2fb121ffe3","term":"ominous","originalPair":"ominous = threatening","needsCare":false,"sources":[{"title":"Merriam-Webster：ominous","url":"https://www.merriam-webster.com/dictionary/ominous"},{"title":"Merriam-Webster：threatening","url":"https://www.merriam-webster.com/dictionary/threatening"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"146":{"sense":"adj. 适时的；有利的","collocations":["an opportune moment","a timely reminder"],"example":"The break came at an opportune moment.","translation":"休息来得正是时候。","note":"opportune强调时机适宜或有利；timely强调及时、不耽误，两者不总对应同样的时机评价。","number":146,"resourceId":"doc-026-7-964e806042a1","term":"opportune","originalPair":"opportune = timely","needsCare":false,"sources":[{"title":"Merriam-Webster：opportune","url":"https://www.merriam-webster.com/dictionary/opportune"},{"title":"Merriam-Webster：timely","url":"https://www.merriam-webster.com/dictionary/timely"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"147":{"sense":"v. 选择","collocations":["opt for","opt to do"],"example":"Many students opt for shorter evening courses.","translation":"许多学生选择时间较短的夜间课程。","note":"opt不直接接选择的物品，常用opt for；choose可直接接宾语，换词时必须改结构。","number":147,"resourceId":"doc-026-7-9f26bf9df7e3","term":"opt","originalPair":"opt = choose","needsCare":false,"sources":[{"title":"Merriam-Webster：opt","url":"https://www.merriam-webster.com/dictionary/opt"},{"title":"Merriam-Webster：choose","url":"https://www.merriam-webster.com/dictionary/choose"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"148":{"sense":"v. 使最优化","collocations":["optimize a process","maximize output"],"example":"The team optimized the timetable to reduce unnecessary travel.","translation":"团队优化了时间表，以减少不必要的出行。","note":"optimize追求条件约束下的最佳效果；maximize追求某量最大。最佳安排不一定让数量最大。","number":148,"resourceId":"doc-026-7-3b5e63d65769","term":"optimize","originalPair":"optimize = maximize","needsCare":true,"sources":[{"title":"Merriam-Webster：optimize","url":"https://www.merriam-webster.com/dictionary/optimize"},{"title":"Merriam-Webster：maximize","url":"https://www.merriam-webster.com/dictionary/maximize"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"149":{"sense":"v. 使朝向；使适应","collocations":["orient towards","align with"],"example":"The course is oriented towards practical workplace skills.","translation":"这门课侧重实用的职场技能。","note":"orient强调方向或定位；align强调对齐、使一致，不是所有课程定位都能直接替换。","number":149,"resourceId":"doc-026-7-39971037401e","term":"orient","originalPair":"orient = align","needsCare":false,"sources":[{"title":"Merriam-Webster：orient","url":"https://www.merriam-webster.com/dictionary/orient"},{"title":"Merriam-Webster：align","url":"https://www.merriam-webster.com/dictionary/align"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"150":{"sense":"v. 使相形见绌；遮蔽","collocations":["overshadow achievements","dominate a debate"],"example":"The funding dispute overshadowed the project's achievements.","translation":"资金争议使项目的成果黯然失色。","note":"overshadow强调使另一事物不受重视；dominate强调支配或占主导。","number":150,"resourceId":"doc-026-7-b0444ff7ff5f","term":"overshadow","originalPair":"overshadow = dominate","needsCare":true,"sources":[{"title":"Merriam-Webster：overshadow","url":"https://www.merriam-webster.com/dictionary/overshadow"},{"title":"Merriam-Webster：dominate","url":"https://www.merriam-webster.com/dictionary/dominate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"151":{"sense":"n. 悖论；看似矛盾的情况","collocations":["a paradox","a contradiction between"],"example":"The report describes the paradox of choice in digital shopping.","translation":"报告描述了数字购物中的选择悖论。","note":"paradox常指看似矛盾却可能有道理的现象；contradiction也可是真正的逻辑冲突。","number":151,"resourceId":"doc-026-7-647f7d53c6e1","term":"paradox","originalPair":"paradox = contradiction","needsCare":true,"sources":[{"title":"Merriam-Webster：paradox","url":"https://www.merriam-webster.com/dictionary/paradox"},{"title":"Merriam-Webster：contradiction","url":"https://www.merriam-webster.com/dictionary/contradiction"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"152":{"sense":"adj. 首要的；最重要的","collocations":["of paramount importance","supreme authority"],"example":"Passenger safety is of paramount importance.","translation":"乘客安全是头等重要的事。","note":"paramount强调超过其他考虑的重要性；supreme还可指最高权力或等级，并非一概替换。","number":152,"resourceId":"doc-026-7-0836dbb4575f","term":"paramount","originalPair":"paramount = supreme","needsCare":false,"sources":[{"title":"Merriam-Webster：paramount","url":"https://www.merriam-webster.com/dictionary/paramount"},{"title":"Merriam-Webster：supreme","url":"https://www.merriam-webster.com/dictionary/supreme"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"153":{"sense":"v. 察觉；看待","collocations":["perceive as","discern differences"],"example":"Some residents perceive the new road as a threat.","translation":"一些居民把这条新路视为威胁。","note":"perceive可表示如何看待；discern侧重辨明或察觉细节，不能照搬perceive A as B的全部用法。","number":153,"resourceId":"doc-026-8-12796a1ef76f","term":"perceive","originalPair":"perceive = discern","needsCare":false,"sources":[{"title":"Merriam-Webster：perceive","url":"https://www.merriam-webster.com/dictionary/perceive"},{"title":"Merriam-Webster：discern","url":"https://www.merriam-webster.com/dictionary/discern"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"154":{"sense":"adj. 有洞察力的","collocations":["a perceptive comment","an insightful analysis"],"example":"She made a perceptive comment about the survey design.","translation":"她对调查设计提出了一个有洞察力的意见。","note":"perceptive强调善于注意和理解；insightful常形容见解或分析深入。","number":154,"resourceId":"doc-026-8-bec9eb66b3b6","term":"perceptive","originalPair":"perceptive = insightful","needsCare":false,"sources":[{"title":"Merriam-Webster：perceptive","url":"https://www.merriam-webster.com/dictionary/perceptive"},{"title":"Merriam-Webster：insightful","url":"https://www.merriam-webster.com/dictionary/insightful"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"155":{"sense":"adj. 危险的","collocations":["a perilous journey","hazardous waste"],"example":"The climbers avoided a perilous route across the ice.","translation":"登山者避开了一条穿越冰面的危险路线。","note":"两词都可指危险；hazardous常见于有害材料和工作环境，perilous常突出严重风险。","number":155,"resourceId":"doc-026-8-361634a0c134","term":"perilous","originalPair":"perilous = hazardous","needsCare":false,"sources":[{"title":"Merriam-Webster：perilous","url":"https://www.merriam-webster.com/dictionary/perilous"},{"title":"Merriam-Webster：hazardous","url":"https://www.merriam-webster.com/dictionary/hazardous"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"156":{"sense":"v. 渗透；弥漫","collocations":["permeate through","penetrate a barrier"],"example":"The smell of smoke permeated the entire building.","translation":"烟味弥漫了整栋建筑。","note":"permeate强调散布各处；penetrate强调进入或穿透屏障，穿透不代表已经弥漫全体。","number":156,"resourceId":"doc-026-8-9485292283ea","term":"permeate","originalPair":"permeate = penetrate","needsCare":false,"sources":[{"title":"Merriam-Webster：permeate","url":"https://www.merriam-webster.com/dictionary/permeate"},{"title":"Merriam-Webster：penetrate","url":"https://www.merriam-webster.com/dictionary/penetrate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"157":{"sense":"adj. 持续的；执着的","collocations":["persistent problems","tenacious effort"],"example":"Persistent noise made it difficult to concentrate.","translation":"持续的噪声使人难以集中注意力。","note":"persistent既可形容人坚持也可形容问题持续；tenacious常强调紧抓不放或顽强，不能都当赞美词。","number":157,"resourceId":"doc-026-8-d1fedb43b9a3","term":"persistent","originalPair":"persistent = tenacious","needsCare":false,"sources":[{"title":"Merriam-Webster：persistent","url":"https://www.merriam-webster.com/dictionary/persistent"},{"title":"Merriam-Webster：tenacious","url":"https://www.merriam-webster.com/dictionary/tenacious"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"158":{"sense":"adj. 关键的；起枢纽作用的","collocations":["a pivotal role","crucial evidence"],"example":"Teachers play a pivotal role in developing reading habits.","translation":"教师对培养阅读习惯起着关键作用。","note":"pivotal突出核心或转折作用；crucial泛指至关重要，二者的修辞重点不同。","number":158,"resourceId":"doc-026-8-76f3e5742fcf","term":"pivotal","originalPair":"pivotal = crucial","needsCare":false,"sources":[{"title":"Merriam-Webster：pivotal","url":"https://www.merriam-webster.com/dictionary/pivotal"},{"title":"Merriam-Webster：crucial","url":"https://www.merriam-webster.com/dictionary/crucial"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"159":{"sense":"adj. 貌似合理的","collocations":["a plausible explanation","a credible witness"],"example":"The report offers a plausible explanation for the decline.","translation":"报告为这一下降提供了一个看似合理的解释。","note":"plausible指听起来合理，未必真实；credible强调值得相信。合理解释仍需证据支持。","number":159,"resourceId":"doc-026-8-bc488425edc3","term":"plausible","originalPair":"plausible = credible","needsCare":true,"sources":[{"title":"Merriam-Webster：plausible","url":"https://www.merriam-webster.com/dictionary/plausible"},{"title":"Merriam-Webster：credible","url":"https://www.merriam-webster.com/dictionary/credible"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"160":{"sense":"v. 暴跌；骤降","collocations":["plummet to","plunge by"],"example":"Ticket sales plummeted after the event was postponed.","translation":"活动推迟后，门票销量骤降。","note":"二者可指急降；plummet常不及物。写图表要区分降至to与降幅by。","number":160,"resourceId":"doc-026-8-46250d9cfa45","term":"plummet","originalPair":"plummet = plunge","needsCare":false,"sources":[{"title":"Merriam-Webster：plummet","url":"https://www.merriam-webster.com/dictionary/plummet"},{"title":"Merriam-Webster：plunge","url":"https://www.merriam-webster.com/dictionary/plunge"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"161":{"sense":"v. 仔细思考","collocations":["ponder a question","contemplate doing"],"example":"The committee paused to ponder the long-term effects.","translation":"委员会停下来认真思考长期影响。","note":"ponder常接需要深入思考的问题；contemplate还可表示考虑采取某行动，结构可能不同。","number":161,"resourceId":"doc-026-8-7d681539945b","term":"ponder","originalPair":"ponder = contemplate","needsCare":false,"sources":[{"title":"Merriam-Webster：ponder","url":"https://www.merriam-webster.com/dictionary/ponder"},{"title":"Merriam-Webster：contemplate","url":"https://www.merriam-webster.com/dictionary/contemplate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"162":{"sense":"adj. 强有力的；效力强的","collocations":["a potent argument","a powerful engine"],"example":"The report presents a potent argument for better public transport.","translation":"报告为改善公共交通提出了有力论证。","note":"potent常指药物、影响或论据效力强；powerful更宽泛，不必带同样的效力含义。","number":162,"resourceId":"doc-026-8-ea4514590d8a","term":"potent","originalPair":"potent = powerful","needsCare":false,"sources":[{"title":"Merriam-Webster：potent","url":"https://www.merriam-webster.com/dictionary/potent"},{"title":"Merriam-Webster：powerful","url":"https://www.merriam-webster.com/dictionary/powerful"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"163":{"sense":"v. 先于","collocations":["precede an event","come before"],"example":"A short introduction precedes the main discussion.","translation":"主要讨论之前有一段简短介绍。","note":"precede直接接后发生的事，不用precede before；come before须保留before。","number":163,"resourceId":"doc-026-8-28cf83a04540","term":"precede","originalPair":"precede = come before","needsCare":false,"sources":[{"title":"Merriam-Webster：precede","url":"https://www.merriam-webster.com/dictionary/precede"},{"title":"Merriam-Webster：come before","url":"https://www.merriam-webster.com/dictionary/before"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"164":{"sense":"adj. 精确的","collocations":["precise measurements","the exact time"],"example":"The experiment requires precise measurements of temperature.","translation":"实验需要精确测量温度。","note":"precise强调精度或明确程度；exact强调完全准确或恰好一致，数值语境要核对所需精度。","number":164,"resourceId":"doc-026-8-d94abc0c6c47","term":"precise","originalPair":"precise = exact","needsCare":false,"sources":[{"title":"Merriam-Webster：precise","url":"https://www.merriam-webster.com/dictionary/precise"},{"title":"Merriam-Webster：exact","url":"https://www.merriam-webster.com/dictionary/exact"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"165":{"sense":"adj. 占主要地位的","collocations":["the predominant cause","a dominant position"],"example":"Cars remain the predominant mode of transport in this area.","translation":"汽车仍是这一地区主要的交通方式。","note":"predominant强调最常见或最有影响；dominant还可强调控制力或强势地位。","number":165,"resourceId":"doc-026-8-32a8003dab96","term":"predominant","originalPair":"predominant = dominant","needsCare":false,"sources":[{"title":"Merriam-Webster：predominant","url":"https://www.merriam-webster.com/dictionary/predominant"},{"title":"Merriam-Webster：dominant","url":"https://www.merriam-webster.com/dictionary/dominant"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"166":{"sense":"v. 开处方；规定","collocations":["prescribe medication","recommend exercise"],"example":"The doctor prescribed a lower dose of the medicine.","translation":"医生开了较低剂量的药。","note":"prescribe有医疗处方或正式规定的含义；recommend只是建议，不能把建议写成已开具处方。","number":166,"resourceId":"doc-026-8-231788b4368e","term":"prescribe","originalPair":"prescribe = recommend","needsCare":true,"sources":[{"title":"Merriam-Webster：prescribe","url":"https://www.merriam-webster.com/dictionary/prescribe"},{"title":"Merriam-Webster：recommend","url":"https://www.merriam-webster.com/dictionary/recommend"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"167":{"sense":"adj. 普遍的；流行的","collocations":["prevalent among","widespread use"],"example":"This belief is prevalent among first-year students.","translation":"这种看法在一年级学生中很普遍。","note":"prevalent常形容观点、习惯或现象；widespread强调分布广，不一定说明在某群体中占多大比例。","number":167,"resourceId":"doc-026-8-c59838a33045","term":"prevalent","originalPair":"prevalent = widespread","needsCare":false,"sources":[{"title":"Merriam-Webster：prevalent","url":"https://www.merriam-webster.com/dictionary/prevalent"},{"title":"Merriam-Webster：widespread","url":"https://www.merriam-webster.com/dictionary/widespread"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"168":{"sense":"adj. 深刻的；深远的","collocations":["a profound effect","deep concern"],"example":"The library closure had a profound effect on the community.","translation":"图书馆关闭对社区产生了深远影响。","note":"deep可以描述物理深度；profound常用于影响、认识或情感，不能套用于所有深浅描述。","number":168,"resourceId":"doc-026-8-8bf87faaed95","term":"profound","originalPair":"profound = deep","needsCare":false,"sources":[{"title":"Merriam-Webster：profound","url":"https://www.merriam-webster.com/dictionary/profound"},{"title":"Merriam-Webster：deep","url":"https://www.merriam-webster.com/dictionary/deep"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"169":{"sense":"v. 迅速增多","collocations":["proliferate rapidly","multiply"],"example":"Short video platforms have proliferated in recent years.","translation":"短视频平台近年来迅速增多。","note":"proliferate通常不及物且强调快速大量增加；multiply还可表示乘法或繁殖。","number":169,"resourceId":"doc-026-8-e11a8c32dc53","term":"proliferate","originalPair":"proliferate = multiply","needsCare":false,"sources":[{"title":"Merriam-Webster：proliferate","url":"https://www.merriam-webster.com/dictionary/proliferate"},{"title":"Merriam-Webster：multiply","url":"https://www.merriam-webster.com/dictionary/multiply"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"170":{"sense":"adj. 显著的；重要的","collocations":["a prominent feature","a notable example"],"example":"A prominent feature of the design is its wide entrance.","translation":"这项设计的一个显著特征是宽敞的入口。","note":"prominent可指位置显眼或人物重要；notable强调值得注意，并非所有显眼事物都重要。","number":170,"resourceId":"doc-026-8-ed89ebb3bb17","term":"prominent","originalPair":"prominent = notable","needsCare":false,"sources":[{"title":"Merriam-Webster：prominent","url":"https://www.merriam-webster.com/dictionary/prominent"},{"title":"Merriam-Webster：notable","url":"https://www.merriam-webster.com/dictionary/notable"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"171":{"sense":"v. 传播；繁殖","collocations":["propagate ideas","spread information"],"example":"Social media can propagate misleading health claims.","translation":"社交媒体可能传播误导性的健康说法。","note":"propagate常指传播思想或繁殖生物；spread范围更广，不能忽视搭配和褒贬语境。","number":171,"resourceId":"doc-026-8-7cbf7ef16061","term":"propagate","originalPair":"propagate = spread","needsCare":false,"sources":[{"title":"Merriam-Webster：propagate","url":"https://www.merriam-webster.com/dictionary/propagate"},{"title":"Merriam-Webster：spread","url":"https://www.merriam-webster.com/dictionary/spread"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"172":{"sense":"n. 前景；可能性","collocations":["the prospect of","a possibility of"],"example":"The prospect of cheaper travel attracted many residents.","translation":"出行成本有望降低吸引了许多居民。","note":"prospect常带对未来的期待或担忧；possibility泛指可能性。prospect也可用复数表示前景。","number":172,"resourceId":"doc-026-8-c2b6ac3e6dd9","term":"prospect","originalPair":"prospect = possibility","needsCare":true,"sources":[{"title":"Merriam-Webster：prospect","url":"https://www.merriam-webster.com/dictionary/prospect"},{"title":"Merriam-Webster：possibility","url":"https://www.merriam-webster.com/dictionary/possibility"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"173":{"sense":"v. 激起；引发","collocations":["provoke a reaction","incite violence"],"example":"The proposal provoked a lively public debate.","translation":"提案引发了热烈的公众讨论。","note":"incite常指煽动他人采取暴力或违法行动；provoke可引起反应，不一定涉及煽动。","number":173,"resourceId":"doc-026-8-12c409cb619d","term":"provoke","originalPair":"provoke = incite","needsCare":true,"sources":[{"title":"Merriam-Webster：provoke","url":"https://www.merriam-webster.com/dictionary/provoke"},{"title":"Merriam-Webster：incite","url":"https://www.merriam-webster.com/dictionary/incite"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"174":{"sense":"adj. 审慎的","collocations":["a prudent decision","cautious about"],"example":"Keeping a backup copy is a prudent precaution.","translation":"保留备份是一项审慎的预防措施。","note":"prudent强调考虑后果后的明智谨慎；cautious侧重避免风险，未必含同样的判断评价。","number":174,"resourceId":"doc-026-8-f3b94b533a24","term":"prudent","originalPair":"prudent = cautious","needsCare":false,"sources":[{"title":"Merriam-Webster：prudent","url":"https://www.merriam-webster.com/dictionary/prudent"},{"title":"Merriam-Webster：cautious","url":"https://www.merriam-webster.com/dictionary/cautious"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"175":{"sense":"v. 追求；继续从事","collocations":["pursue a career","seek advice"],"example":"She plans to pursue a career in environmental science.","translation":"她计划从事环境科学方面的职业。","note":"pursue常指持续追求目标或从事事业；seek可指寻找或请求，不适用于所有持续行动。","number":175,"resourceId":"doc-026-9-aa9f1df216c4","term":"pursue","originalPair":"pursue = seek","needsCare":false,"sources":[{"title":"Merriam-Webster：pursue","url":"https://www.merriam-webster.com/dictionary/pursue"},{"title":"Merriam-Webster：seek","url":"https://www.merriam-webster.com/dictionary/seek"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"176":{"sense":"n. 困境；左右为难","collocations":["in a quandary","face a dilemma"],"example":"The unexpected fee left students in a quandary.","translation":"意外的费用让学生陷入两难。","note":"quandary强调不知道怎么办；dilemma常涉及艰难选择，不必强行限定为恰好两个选项。","number":176,"resourceId":"doc-026-9-393a34b83f36","term":"quandary","originalPair":"quandary = dilemma","needsCare":false,"sources":[{"title":"Merriam-Webster：quandary","url":"https://www.merriam-webster.com/dictionary/quandary"},{"title":"Merriam-Webster：dilemma","url":"https://www.merriam-webster.com/dictionary/dilemma"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"177":{"sense":"n. 探索；追寻","collocations":["a quest for","a search for"],"example":"Their quest for affordable housing took several months.","translation":"他们寻找可负担住房花了几个月。","note":"quest常带长期、艰难或理想性追求的色彩；search可以是普通查找。","number":177,"resourceId":"doc-026-9-6bcc745825ad","term":"quest","originalPair":"quest = search","needsCare":false,"sources":[{"title":"Merriam-Webster：quest","url":"https://www.merriam-webster.com/dictionary/quest"},{"title":"Merriam-Webster：search","url":"https://www.merriam-webster.com/dictionary/search"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"178":{"sense":"adj. 根本的；激进的","collocations":["radical reform","drastic cuts"],"example":"The report calls for a radical change in transport policy.","translation":"报告呼吁从根本上改变交通政策。","note":"radical强调根本性或激进；drastic强调猛烈或大幅度，幅度大不一定触及根本。","number":178,"resourceId":"doc-026-9-ad18467da6b6","term":"radical","originalPair":"radical = drastic","needsCare":false,"sources":[{"title":"Merriam-Webster：radical","url":"https://www.merriam-webster.com/dictionary/radical"},{"title":"Merriam-Webster：drastic","url":"https://www.merriam-webster.com/dictionary/drastic"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"179":{"sense":"n. 理由；基本原理","collocations":["the rationale for","justification for"],"example":"The document explains the rationale for the new timetable.","translation":"文件解释了新时间表背后的理由。","note":"rationale指决策背后的推理依据；justification强调证明某事合理或正当。","number":179,"resourceId":"doc-026-9-a5d280a257a6","term":"rationale","originalPair":"rationale = justification","needsCare":false,"sources":[{"title":"Merriam-Webster：rationale","url":"https://www.merriam-webster.com/dictionary/rationale"},{"title":"Merriam-Webster：justification","url":"https://www.merriam-webster.com/dictionary/justification"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"180":{"sense":"adv. 容易地；乐意地","collocations":["readily available","readily agree"],"example":"The instructions are readily understood by beginners.","translation":"初学者很容易理解这些说明。","note":"easily对应容易义；readily也可表示乐意或迅速，如readily agreed，并非都表示难度低。","number":180,"resourceId":"doc-026-9-cd9a9ef49116","term":"readily","originalPair":"readily = easily","needsCare":false,"sources":[{"title":"Merriam-Webster：readily","url":"https://www.merriam-webster.com/dictionary/readily"},{"title":"Merriam-Webster：easily","url":"https://www.merriam-webster.com/dictionary/easily"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"181":{"sense":"v. 斥责；严厉批评","collocations":["rebuke someone for","reprimand staff"],"example":"The coach rebuked the players for ignoring the safety rules.","translation":"教练斥责队员无视安全规则。","note":"reprimand常带正式纪律批评意味；rebuke侧重严厉表达不满，二者语气都较强。","number":181,"resourceId":"doc-026-9-2bf3848fd479","term":"rebuke","originalPair":"rebuke = reprimand","needsCare":false,"sources":[{"title":"Merriam-Webster：rebuke","url":"https://www.merriam-webster.com/dictionary/rebuke"},{"title":"Merriam-Webster：reprimand","url":"https://www.merriam-webster.com/dictionary/reprimand"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"182":{"sense":"adj. 相互的；互惠的","collocations":["reciprocal arrangements","mutual trust"],"example":"The colleges agreed to reciprocal library access.","translation":"两所学院同意互相开放图书馆。","note":"reciprocal常强调双方相应给予或交换；mutual可指共同拥有的感受或关系。","number":182,"resourceId":"doc-026-9-7dcbd08119de","term":"reciprocal","originalPair":"reciprocal = mutual","needsCare":false,"sources":[{"title":"Merriam-Webster：reciprocal","url":"https://www.merriam-webster.com/dictionary/reciprocal"},{"title":"Merriam-Webster：mutual","url":"https://www.merriam-webster.com/dictionary/mutual"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"183":{"sense":"v. 调和；使一致；和解","collocations":["reconcile A with B","harmonize standards"],"example":"The plan tries to reconcile growth with environmental protection.","translation":"计划试图协调经济增长与环境保护。","note":"reconcile常处理看似冲突的要求；harmonize强调协调一致，也可指音乐和声。","number":183,"resourceId":"doc-026-9-01cd35a41d4a","term":"reconcile","originalPair":"reconcile = harmonize","needsCare":false,"sources":[{"title":"Merriam-Webster：reconcile","url":"https://www.merriam-webster.com/dictionary/reconcile"},{"title":"Merriam-Webster：harmonize","url":"https://www.merriam-webster.com/dictionary/harmonize"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"184":{"sense":"v. 纠正；修正","collocations":["rectify an error","remedy a problem"],"example":"The office rectified the error in my address.","translation":"办公室纠正了我地址中的错误。","note":"rectify常接具体错误；remedy强调补救问题或不良状况，并非每种补救都是更正文字。","number":184,"resourceId":"doc-026-9-fa1c7b6671ab","term":"rectify","originalPair":"rectify = remedy","needsCare":false,"sources":[{"title":"Merriam-Webster：rectify","url":"https://www.merriam-webster.com/dictionary/rectify"},{"title":"Merriam-Webster：remedy","url":"https://www.merriam-webster.com/dictionary/remedy"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"185":{"sense":"v. 反驳；驳倒","collocations":["refute a claim","debunk a myth"],"example":"The new measurements refute the claim that the lake is shrinking.","translation":"新测量结果反驳了湖泊正在缩小的说法。","note":"refute通常要求反证，不能只表达不同意；debunk常指揭穿谬论或错误观念。","number":185,"resourceId":"doc-026-9-e88100267ee3","term":"refute","originalPair":"refute = debunk","needsCare":true,"sources":[{"title":"Merriam-Webster：refute","url":"https://www.merriam-webster.com/dictionary/refute"},{"title":"Merriam-Webster：debunk","url":"https://www.merriam-webster.com/dictionary/debunk"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"186":{"sense":"adj. 持续不断的；不松懈的","collocations":["relentless pressure","persistent effort"],"example":"Workers faced relentless pressure to meet the deadline.","translation":"员工承受着持续不断的赶工压力。","note":"relentless强调毫不减弱，常有压迫感；persistent可中性或褒义描述坚持。","number":186,"resourceId":"doc-026-9-fd4f4f9ccfc9","term":"relentless","originalPair":"relentless = persistent","needsCare":false,"sources":[{"title":"Merriam-Webster：relentless","url":"https://www.merriam-webster.com/dictionary/relentless"},{"title":"Merriam-Webster：persistent","url":"https://www.merriam-webster.com/dictionary/persistent"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"187":{"sense":"adj. 相关的","collocations":["relevant to","pertinent to"],"example":"Only information relevant to the application should be included.","translation":"只应包含与申请相关的信息。","note":"pertinent也可表示切题、相关，较正式；两者常接to，不用relevant with。","number":187,"resourceId":"doc-026-9-e36785a360a9","term":"relevant","originalPair":"relevant = pertinent","needsCare":false,"sources":[{"title":"Merriam-Webster：relevant","url":"https://www.merriam-webster.com/dictionary/relevant"},{"title":"Merriam-Webster：pertinent","url":"https://www.merriam-webster.com/dictionary/pertinent"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"188":{"sense":"v. 放弃；交出","collocations":["relinquish control","abandon a plan"],"example":"The founder agreed to relinquish control of the company.","translation":"创始人同意交出公司的控制权。","note":"relinquish常指交出权利、职位或控制；abandon还可指丢弃、遗弃或中止计划。","number":188,"resourceId":"doc-026-9-2bd0a2f787c3","term":"relinquish","originalPair":"relinquish = abandon","needsCare":false,"sources":[{"title":"Merriam-Webster：relinquish","url":"https://www.merriam-webster.com/dictionary/relinquish"},{"title":"Merriam-Webster：abandon","url":"https://www.merriam-webster.com/dictionary/abandon"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"189":{"sense":"adj. 非凡的；值得注意的","collocations":["a remarkable achievement","a notable change"],"example":"The class made remarkable progress in a short time.","translation":"这个班在短时间内取得了显著进步。","note":"remarkable常强调令人惊讶或不寻常；notable强调值得注意，不必都达到非凡程度。","number":189,"resourceId":"doc-026-9-0ae9def38fbf","term":"remarkable","originalPair":"remarkable = notable","needsCare":false,"sources":[{"title":"Merriam-Webster：remarkable","url":"https://www.merriam-webster.com/dictionary/remarkable"},{"title":"Merriam-Webster：notable","url":"https://www.merriam-webster.com/dictionary/notable"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"190":{"sense":"n. 懊悔；自责","collocations":["remorse for","regret about"],"example":"He expressed remorse for misleading the public.","translation":"他对误导公众表达了懊悔。","note":"remorse通常涉及因不当行为产生的内疚；regret也可为普通遗憾，不一定承认道德过错。","number":190,"resourceId":"doc-026-9-33d9456b1e30","term":"remorse","originalPair":"remorse = regret","needsCare":false,"sources":[{"title":"Merriam-Webster：remorse","url":"https://www.merriam-webster.com/dictionary/remorse"},{"title":"Merriam-Webster：regret","url":"https://www.merriam-webster.com/dictionary/regret"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"191":{"sense":"v. 使成为","collocations":["render something unusable","make something clear"],"example":"The flood rendered the bridge unsafe.","translation":"洪水使桥梁变得不安全。","note":"render在此为宾语加补语的正式用法；make范围更广。render还有提供、呈现、翻译等义项。","number":191,"resourceId":"doc-026-9-1fb92cc302c1","term":"render","originalPair":"render = make","needsCare":false,"sources":[{"title":"Merriam-Webster：render","url":"https://www.merriam-webster.com/dictionary/render"},{"title":"Merriam-Webster：make","url":"https://www.merriam-webster.com/dictionary/make"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"192":{"sense":"adj. 著名的","collocations":["renowned for","famous for"],"example":"The town is renowned for its traditional pottery.","translation":"小镇以传统陶器闻名。","note":"renowned通常含因成就或特色享有声誉的意味；famous只说明知名，不保证是好名声。","number":192,"resourceId":"doc-026-9-f1e06d797b63","term":"renowned","originalPair":"renowned = famous","needsCare":false,"sources":[{"title":"Merriam-Webster：renowned","url":"https://www.merriam-webster.com/dictionary/renowned"},{"title":"Merriam-Webster：famous","url":"https://www.merriam-webster.com/dictionary/famous"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"193":{"sense":"v. 拒绝接受；否认","collocations":["repudiate a claim","reject an offer"],"example":"The organisation repudiated the suggestion that it supported violence.","translation":"该组织否认了其支持暴力的说法。","note":"repudiate常是强烈、公开的否认或拒绝承认；reject可指普通拒绝某个提议或物品。","number":193,"resourceId":"doc-026-9-215a0bc6bfae","term":"repudiate","originalPair":"repudiate = reject","needsCare":false,"sources":[{"title":"Merriam-Webster：repudiate","url":"https://www.merriam-webster.com/dictionary/repudiate"},{"title":"Merriam-Webster：reject","url":"https://www.merriam-webster.com/dictionary/reject"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"194":{"sense":"adj. 有恢复力的；有弹性的","collocations":["resilient communities","durable materials"],"example":"Resilient communities can recover more quickly after a disaster.","translation":"有恢复力的社区能在灾后更快恢复。","note":"resilient强调受打击后恢复；durable强调经久耐用。耐用不等于恢复力强。","number":194,"resourceId":"doc-026-9-5895031dcc77","term":"resilient","originalPair":"resilient = durable","needsCare":true,"sources":[{"title":"Merriam-Webster：resilient","url":"https://www.merriam-webster.com/dictionary/resilient"},{"title":"Merriam-Webster：durable","url":"https://www.merriam-webster.com/dictionary/durable"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"195":{"sense":"adj. 各自的","collocations":["their respective roles","individual needs"],"example":"The speakers returned to their respective seats.","translation":"发言者回到了各自的座位。","note":"respective把多个对象与各自对应项联系起来；individual强调单个或个人，不能随意替换对应关系。","number":195,"resourceId":"doc-026-9-702a57ae8bfd","term":"respective","originalPair":"respective = individual","needsCare":true,"sources":[{"title":"Merriam-Webster：respective","url":"https://www.merriam-webster.com/dictionary/respective"},{"title":"Merriam-Webster：individual","url":"https://www.merriam-webster.com/dictionary/individual"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"196":{"sense":"v. 约束；抑制","collocations":["restrain spending","curtail activities"],"example":"The council tried to restrain spending on temporary offices.","translation":"市议会试图限制临时办公室的开支。","note":"restrain侧重约束或阻止过度；curtail常表示削减活动、权利或时长。","number":196,"resourceId":"doc-026-9-f7c14594a686","term":"restrain","originalPair":"restrain = curtail","needsCare":false,"sources":[{"title":"Merriam-Webster：restrain","url":"https://www.merriam-webster.com/dictionary/restrain"},{"title":"Merriam-Webster：curtail","url":"https://www.merriam-webster.com/dictionary/curtail"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"197":{"sense":"v. 取回；检索","collocations":["retrieve a file","recover lost data"],"example":"Users can retrieve archived files through the search page.","translation":"用户可通过搜索页检索归档文件。","note":"retrieve强调找回或提取；recover还可指恢复健康或恢复系统，并非所有恢复都能用retrieve。","number":197,"resourceId":"doc-026-10-bb2ddb9243a0","term":"retrieve","originalPair":"retrieve = recover","needsCare":false,"sources":[{"title":"Merriam-Webster：retrieve","url":"https://www.merriam-webster.com/dictionary/retrieve"},{"title":"Merriam-Webster：recover","url":"https://www.merriam-webster.com/dictionary/recover"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"198":{"sense":"adj. 强健的；稳健的","collocations":["a robust method","a strong argument"],"example":"The results remained robust under different testing conditions.","translation":"在不同测试条件下，结果仍保持稳健。","note":"robust可强调方法经得起变化或检验；strong范围更宽泛，不自动代表已做稳健性检验。","number":198,"resourceId":"doc-026-10-d91af3da13b4","term":"robust","originalPair":"robust = strong","needsCare":false,"sources":[{"title":"Merriam-Webster：robust","url":"https://www.merriam-webster.com/dictionary/robust"},{"title":"Merriam-Webster：strong","url":"https://www.merriam-webster.com/dictionary/strong"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"199":{"sense":"v. 仔细审查","collocations":["scrutinize records","examine evidence"],"example":"The auditors scrutinized every payment record.","translation":"审计人员仔细审查了每笔付款记录。","note":"scrutinize强调严密细查；examine可为一般检查或考察，程度不同。","number":199,"resourceId":"doc-026-10-d5ccd5f2a4fb","term":"scrutinize","originalPair":"scrutinize = examine","needsCare":false,"sources":[{"title":"Merriam-Webster：scrutinize","url":"https://www.merriam-webster.com/dictionary/scrutinize"},{"title":"Merriam-Webster：examine","url":"https://www.merriam-webster.com/dictionary/examine"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"200":{"sense":"v. 获得；争取到","collocations":["secure funding","obtain approval"],"example":"The group secured funding for a community garden.","translation":"小组争取到了社区花园的资金。","note":"secure常带成功争取或确保获得的意味；obtain较中性。secure作形容词还有安全的意思。","number":200,"resourceId":"doc-026-10-ff53c2a3b9ab","term":"secure","originalPair":"secure = obtain","needsCare":false,"sources":[{"title":"Merriam-Webster：secure","url":"https://www.merriam-webster.com/dictionary/secure"},{"title":"Merriam-Webster：obtain","url":"https://www.merriam-webster.com/dictionary/obtain"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"201":{"sense":"v. 隔离；分开","collocations":["segregate waste","separate materials"],"example":"The facility segregates hazardous waste from ordinary rubbish.","translation":"设施将危险废物与普通垃圾分开处理。","note":"segregate带分类隔离意味，谈人群时可能涉及歧视性隔离；separate只是一般分开。","number":201,"resourceId":"doc-026-10-bf0d3fbdc9a2","term":"segregate","originalPair":"segregate = separate","needsCare":false,"sources":[{"title":"Merriam-Webster：segregate","url":"https://www.merriam-webster.com/dictionary/segregate"},{"title":"Merriam-Webster：separate","url":"https://www.merriam-webster.com/dictionary/separate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"202":{"sense":"adj. 轰动的；极出色的","collocations":["sensational headlines","extraordinary results"],"example":"Sensational headlines can exaggerate the findings of a study.","translation":"耸动的标题可能夸大研究发现。","note":"sensational可表示耸动或极出色；extraordinary只是非同寻常，未必刻意制造轰动。","number":202,"resourceId":"doc-026-10-7870c38626fa","term":"sensational","originalPair":"sensational = extraordinary","needsCare":true,"sources":[{"title":"Merriam-Webster：sensational","url":"https://www.merriam-webster.com/dictionary/sensational"},{"title":"Merriam-Webster：extraordinary","url":"https://www.merriam-webster.com/dictionary/extraordinary"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"203":{"sense":"v. 表示；意味着","collocations":["signify a change","indicate a result"],"example":"A falling response rate may signify declining public interest.","translation":"回复率下降可能意味着公众兴趣减弱。","note":"signify可强调所意味的意义；indicate还可指指示方向或数据所显示的结果。","number":203,"resourceId":"doc-026-10-516f1e98992c","term":"signify","originalPair":"signify = indicate","needsCare":false,"sources":[{"title":"Merriam-Webster：signify","url":"https://www.merriam-webster.com/dictionary/signify"},{"title":"Merriam-Webster：indicate","url":"https://www.merriam-webster.com/dictionary/indicate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"204":{"sense":"v. 模拟","collocations":["simulate conditions","imitate a voice"],"example":"The software simulates traffic conditions during rush hour.","translation":"软件模拟高峰时段的交通状况。","note":"simulate常为研究或训练再现条件；imitate偏向模仿行为或外观，不一定是建模。","number":204,"resourceId":"doc-026-10-6e07cf417442","term":"simulate","originalPair":"simulate = imitate","needsCare":false,"sources":[{"title":"Merriam-Webster：simulate","url":"https://www.merriam-webster.com/dictionary/simulate"},{"title":"Merriam-Webster：imitate","url":"https://www.merriam-webster.com/dictionary/imitate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"205":{"sense":"n. 怀疑者","collocations":["a skeptic about","a doubter"],"example":"Even a skeptic might find the new evidence persuasive.","translation":"即使是怀疑者，也可能觉得新证据有说服力。","note":"skeptic常指对某种说法持怀疑态度的人；doubter较一般。英式常拼作sceptic。","number":205,"resourceId":"doc-026-10-e38d23871b41","term":"skeptic","originalPair":"skeptic = doubter","needsCare":false,"sources":[{"title":"Merriam-Webster：skeptic","url":"https://www.merriam-webster.com/dictionary/skeptic"},{"title":"Merriam-Webster：doubter","url":"https://www.merriam-webster.com/dictionary/doubter"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"206":{"sense":"adj. 稀疏的；零散的","collocations":["sparse vegetation","scarce resources"],"example":"Vegetation is sparse on the rocky hillside.","translation":"岩石山坡上的植被很稀疏。","note":"sparse强调分布不密或数量零散；scarce强调供给不足或难获得，稀疏不等于稀缺。","number":206,"resourceId":"doc-026-10-b66ee8739aca","term":"sparse","originalPair":"sparse = scarce","needsCare":true,"sources":[{"title":"Merriam-Webster：sparse","url":"https://www.merriam-webster.com/dictionary/sparse"},{"title":"Merriam-Webster：scarce","url":"https://www.merriam-webster.com/dictionary/scarce"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"207":{"sense":"v. 推测","collocations":["speculate about","conjecture that"],"example":"We can only speculate about the reasons for the change.","translation":"我们只能推测这项变化背后的原因。","note":"两词都可表示证据不足时推想；speculate还可指投机交易，与conjecture不通用。","number":207,"resourceId":"doc-026-10-b1e3acd1a6c3","term":"speculate","originalPair":"speculate = conjecture","needsCare":false,"sources":[{"title":"Merriam-Webster：speculate","url":"https://www.merriam-webster.com/dictionary/speculate"},{"title":"Merriam-Webster：conjecture","url":"https://www.merriam-webster.com/dictionary/conjecture"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"208":{"sense":"adj. 零星的；偶发的","collocations":["sporadic outbreaks","intermittent rain"],"example":"The village experienced sporadic power cuts during the storm.","translation":"暴风雨期间，村庄偶有停电。","note":"sporadic强调零散不规则；intermittent强调时断时续，不一定随机出现。","number":208,"resourceId":"doc-026-10-e8bc1d19910f","term":"sporadic","originalPair":"sporadic = intermittent","needsCare":false,"sources":[{"title":"Merriam-Webster：sporadic","url":"https://www.merriam-webster.com/dictionary/sporadic"},{"title":"Merriam-Webster：intermittent","url":"https://www.merriam-webster.com/dictionary/intermittent"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"209":{"sense":"adj. 停滞的；不流动的","collocations":["stagnant water","a dormant business"],"example":"Stagnant water collected behind the damaged wall.","translation":"受损墙体后方积起了不流动的水。","note":"stagnant常指缺乏流动或发展；dormant是暂时休眠，不带相同的停滞含义。","number":209,"resourceId":"doc-026-10-69ca3ad46731","term":"stagnant","originalPair":"stagnant = dormant","needsCare":true,"sources":[{"title":"Merriam-Webster：stagnant","url":"https://www.merriam-webster.com/dictionary/stagnant"},{"title":"Merriam-Webster：dormant","url":"https://www.merriam-webster.com/dictionary/dormant"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"210":{"sense":"adj. 严酷的；鲜明的","collocations":["a stark contrast","harsh conditions"],"example":"The figures reveal a stark contrast between the two regions.","translation":"数字显示两个地区存在鲜明反差。","note":"stark可指鲜明、赤裸或严酷；harsh对应严厉严酷义，不能用于所有contrast搭配。","number":210,"resourceId":"doc-026-10-4d81be3a7e41","term":"stark","originalPair":"stark = harsh","needsCare":false,"sources":[{"title":"Merriam-Webster：stark","url":"https://www.merriam-webster.com/dictionary/stark"},{"title":"Merriam-Webster：harsh","url":"https://www.merriam-webster.com/dictionary/harsh"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"211":{"sense":"v. 刺激；促进","collocations":["stimulate demand","provoke debate"],"example":"Lower fares may stimulate demand for public transport.","translation":"降低票价可能刺激公共交通需求。","note":"stimulate可促进活动或增长；provoke常引发强烈反应，未必带促进发展的含义。","number":211,"resourceId":"doc-026-10-37dc9d93a3f9","term":"stimulate","originalPair":"stimulate = provoke","needsCare":false,"sources":[{"title":"Merriam-Webster：stimulate","url":"https://www.merriam-webster.com/dictionary/stimulate"},{"title":"Merriam-Webster：provoke","url":"https://www.merriam-webster.com/dictionary/provoke"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"212":{"sense":"adj. 直截了当的；简单易懂的","collocations":["straightforward instructions","a direct answer"],"example":"The application process is straightforward and takes ten minutes.","translation":"申请流程简单明了，只需十分钟。","note":"direct对应直接义；straightforward还表示不复杂，用direct不能完整表达流程容易操作。","number":212,"resourceId":"doc-026-10-68737ebe1914","term":"straightforward","originalPair":"straightforward = direct","needsCare":false,"sources":[{"title":"Merriam-Webster：straightforward","url":"https://www.merriam-webster.com/dictionary/straightforward"},{"title":"Merriam-Webster：direct","url":"https://www.merriam-webster.com/dictionary/direct"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"213":{"sense":"adj. 费力的；繁重的","collocations":["strenuous exercise","demanding work"],"example":"The route includes several hours of strenuous walking.","translation":"这条路线包括数小时的高强度步行。","note":"strenuous常强调体力付出；demanding也可形容脑力、时间或要求很高的工作。","number":213,"resourceId":"doc-026-10-e856a0f09b33","term":"strenuous","originalPair":"strenuous = demanding","needsCare":false,"sources":[{"title":"Merriam-Webster：strenuous","url":"https://www.merriam-webster.com/dictionary/strenuous"},{"title":"Merriam-Webster：demanding","url":"https://www.merriam-webster.com/dictionary/demanding"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"214":{"sense":"adj. 随后的","collocations":["subsequent changes","the following week"],"example":"Subsequent surveys included a wider range of households.","translation":"后续调查涵盖了更多类型的家庭。","note":"subsequent是较正式的之后发生；following还可作介词或限定词，不能忽视词性。","number":214,"resourceId":"doc-026-10-0517cab03c8f","term":"subsequent","originalPair":"subsequent = following","needsCare":false,"sources":[{"title":"Merriam-Webster：subsequent","url":"https://www.merriam-webster.com/dictionary/subsequent"},{"title":"Merriam-Webster：following","url":"https://www.merriam-webster.com/dictionary/following"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"215":{"sense":"adj. 大量的；可观的","collocations":["substantial savings","a significant difference"],"example":"The new insulation produced substantial energy savings.","translation":"新的保温层显著节省了能源。","note":"substantial强调量大或实在；significant可指重要或统计显著，不能自动等同于数值大。","number":215,"resourceId":"doc-026-10-817754275128","term":"substantial","originalPair":"substantial = significant","needsCare":true,"sources":[{"title":"Merriam-Webster：substantial","url":"https://www.merriam-webster.com/dictionary/substantial"},{"title":"Merriam-Webster：significant","url":"https://www.merriam-webster.com/dictionary/significant"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"216":{"sense":"v. 替代","collocations":["substitute A for B","replace B with A"],"example":"You can substitute beans for meat in this recipe.","translation":"这道食谱里可以用豆类代替肉。","note":"substitute A for B表示用A替B；replace B with A表示同一方向，切勿把对象顺序写反。","number":216,"resourceId":"doc-026-10-25299aea1fae","term":"substitute","originalPair":"substitute = replace","needsCare":true,"sources":[{"title":"Merriam-Webster：substitute","url":"https://www.merriam-webster.com/dictionary/substitute"},{"title":"Merriam-Webster：replace","url":"https://www.merriam-webster.com/dictionary/replace"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"217":{"sense":"adj. 微妙的；不易察觉的","collocations":["subtle differences","a nuanced view"],"example":"There are subtle differences between the two explanations.","translation":"两种解释之间有微妙差别。","note":"subtle可指不明显或巧妙；nuanced强调包含细致层次，不是所有不明显都叫nuanced。","number":217,"resourceId":"doc-026-10-f8b14b820e3b","term":"subtle","originalPair":"subtle = nuanced","needsCare":true,"sources":[{"title":"Merriam-Webster：subtle","url":"https://www.merriam-webster.com/dictionary/subtle"},{"title":"Merriam-Webster：nuanced","url":"https://www.merriam-webster.com/dictionary/nuanced"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"218":{"sense":"v. 超过；胜过","collocations":["surpass expectations","exceed a limit"],"example":"Attendance surpassed the organisers' expectations.","translation":"出席人数超过了组织者的预期。","note":"surpass可指优于某人或预期；exceed常接限额、数量或标准，比较对象应保持明确。","number":218,"resourceId":"doc-026-10-97e01db0f0ae","term":"surpass","originalPair":"surpass = exceed","needsCare":false,"sources":[{"title":"Merriam-Webster：surpass","url":"https://www.merriam-webster.com/dictionary/surpass"},{"title":"Merriam-Webster：exceed","url":"https://www.merriam-webster.com/dictionary/exceed"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"219":{"sense":"v. 维持；支撑","collocations":["sustain growth","maintain standards"],"example":"Stable funding is needed to sustain the reading programme.","translation":"维持阅读项目需要稳定的资金。","note":"sustain常强调让某活动持续下去；maintain还可指保养或保持状态，不限于持续增长。","number":219,"resourceId":"doc-026-11-a1a7cda2a191","term":"sustain","originalPair":"sustain = maintain","needsCare":false,"sources":[{"title":"Merriam-Webster：sustain","url":"https://www.merriam-webster.com/dictionary/sustain"},{"title":"Merriam-Webster：maintain","url":"https://www.merriam-webster.com/dictionary/maintain"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"220":{"sense":"adj. 迅速的","collocations":["swift action","rapid growth"],"example":"Swift action prevented the leak from spreading.","translation":"迅速采取行动阻止了泄漏蔓延。","note":"swift常修饰行动、反应或移动；rapid常修饰变化或增长，搭配习惯有所不同。","number":220,"resourceId":"doc-026-11-5891ea4c6d21","term":"swift","originalPair":"swift = rapid","needsCare":false,"sources":[{"title":"Merriam-Webster：swift","url":"https://www.merriam-webster.com/dictionary/swift"},{"title":"Merriam-Webster：rapid","url":"https://www.merriam-webster.com/dictionary/rapid"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"221":{"sense":"n. 交响曲","collocations":["compose a symphony","orchestral music"],"example":"The orchestra performed a new symphony at the festival.","translation":"乐团在艺术节演奏了一首新交响曲。","note":"symphony是一类具体作品；orchestral music是管弦乐的总称，属于上位概念，不是完全同义。","number":221,"resourceId":"doc-026-11-3a7c310d31a4","term":"symphony","originalPair":"symphony = orchestral music","needsCare":true,"sources":[{"title":"Merriam-Webster：symphony","url":"https://www.merriam-webster.com/dictionary/symphony"},{"title":"Merriam-Webster：orchestral music","url":"https://www.merriam-webster.com/dictionary/orchestral"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"222":{"sense":"adj. 同义的","collocations":["synonymous with","equivalent to"],"example":"In this context, the two expressions are nearly synonymous.","translation":"在这一语境中，这两个表达几乎同义。","note":"synonymous谈词语意义；equivalent还可指数量、价值或功能相当。注意介词with和to。","number":222,"resourceId":"doc-026-11-63c0c2de7dae","term":"synonymous","originalPair":"synonymous = equivalent","needsCare":true,"sources":[{"title":"Merriam-Webster：synonymous","url":"https://www.merriam-webster.com/dictionary/synonymous"},{"title":"Merriam-Webster：equivalent","url":"https://www.merriam-webster.com/dictionary/equivalent"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"223":{"sense":"adj. 可触摸的；切实的","collocations":["tangible benefits","concrete evidence"],"example":"The project delivered tangible benefits to local families.","translation":"项目给当地家庭带来了切实的好处。","note":"tangible也可指明显可感的；concrete可指具体或实在，但还可作名词“混凝土”。","number":223,"resourceId":"doc-026-11-3a1c203eda4a","term":"tangible","originalPair":"tangible = concrete","needsCare":false,"sources":[{"title":"Merriam-Webster：tangible","url":"https://www.merriam-webster.com/dictionary/tangible"},{"title":"Merriam-Webster：concrete","url":"https://www.merriam-webster.com/dictionary/concrete"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"224":{"sense":"adj. 冗长乏味的","collocations":["a tedious task","monotonous work"],"example":"Checking hundreds of identical forms was tedious.","translation":"检查数百份相同的表格十分乏味。","note":"tedious强调令人厌烦或费时；monotonous强调缺少变化，乏味不一定只是重复造成。","number":224,"resourceId":"doc-026-11-b76626f2f991","term":"tedious","originalPair":"tedious = monotonous","needsCare":false,"sources":[{"title":"Merriam-Webster：tedious","url":"https://www.merriam-webster.com/dictionary/tedious"},{"title":"Merriam-Webster：monotonous","url":"https://www.merriam-webster.com/dictionary/monotonous"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"225":{"sense":"adj. 温和的；温带的","collocations":["a temperate climate","moderate temperatures"],"example":"The coastal region has a temperate climate.","translation":"这一沿海地区气候温和。","note":"temperate可指温带气候或有节制；moderate泛指适中，不能完全替代气候带名称。","number":225,"resourceId":"doc-026-11-2b3ce251b793","term":"temperate","originalPair":"temperate = moderate","needsCare":true,"sources":[{"title":"Merriam-Webster：temperate","url":"https://www.merriam-webster.com/dictionary/temperate"},{"title":"Merriam-Webster：moderate","url":"https://www.merriam-webster.com/dictionary/moderate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"226":{"sense":"adj. 暂定的；试探性的","collocations":["tentative plans","provisional approval"],"example":"We have made tentative plans for a workshop in June.","translation":"我们暂定六月举办一场工作坊。","note":"tentative可强调尚不确定或试探；provisional强调临时有效、以后可更改。","number":226,"resourceId":"doc-026-11-051b1c808372","term":"tentative","originalPair":"tentative = provisional","needsCare":true,"sources":[{"title":"Merriam-Webster：tentative","url":"https://www.merriam-webster.com/dictionary/tentative"},{"title":"Merriam-Webster：provisional","url":"https://www.merriam-webster.com/dictionary/provisional"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"227":{"sense":"adj. 彻底的；细致的","collocations":["a thorough inspection","a comprehensive review"],"example":"The engineers carried out a thorough inspection of the roof.","translation":"工程师对屋顶进行了彻底检查。","note":"thorough强调做得细致充分；comprehensive强调覆盖面广，广泛不一定细致。","number":227,"resourceId":"doc-026-11-f0ef73b68f4c","term":"thorough","originalPair":"thorough = comprehensive","needsCare":true,"sources":[{"title":"Merriam-Webster：thorough","url":"https://www.merriam-webster.com/dictionary/thorough"},{"title":"Merriam-Webster：comprehensive","url":"https://www.merriam-webster.com/dictionary/comprehensive"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"228":{"sense":"v. 茁壮成长；兴旺","collocations":["thrive in","prosper"],"example":"Young plants thrive in these sheltered gardens.","translation":"幼苗在这些避风的花园里茁壮成长。","note":"thrive适用于生物、个人或事业发展良好；prosper常强调成功或经济兴旺。","number":228,"resourceId":"doc-026-11-6860a586150c","term":"thrive","originalPair":"thrive = prosper","needsCare":false,"sources":[{"title":"Merriam-Webster：thrive","url":"https://www.merriam-webster.com/dictionary/thrive"},{"title":"Merriam-Webster：prosper","url":"https://www.merriam-webster.com/dictionary/prosper"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"229":{"sense":"v. 容忍；耐受","collocations":["tolerate noise","endure hardship"],"example":"Many residents will not tolerate constant late-night noise.","translation":"许多居民无法容忍持续的深夜噪声。","note":"tolerate可表示允许某行为存在或身体耐受；endure强调承受困难，不一定表示认可。","number":229,"resourceId":"doc-026-11-15735a093391","term":"tolerate","originalPair":"tolerate = endure","needsCare":false,"sources":[{"title":"Merriam-Webster：tolerate","url":"https://www.merriam-webster.com/dictionary/tolerate"},{"title":"Merriam-Webster：endure","url":"https://www.merriam-webster.com/dictionary/endure"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"230":{"sense":"v. 超越","collocations":["transcend boundaries","surpass a record"],"example":"Good public spaces can transcend social boundaries.","translation":"良好的公共空间可以超越社会界限。","note":"transcend常指超越界限或限制；surpass常指数量、表现更高，不宜机械搭配所有边界。","number":230,"resourceId":"doc-026-11-e7b7996e0780","term":"transcend","originalPair":"transcend = surpass","needsCare":false,"sources":[{"title":"Merriam-Webster：transcend","url":"https://www.merriam-webster.com/dictionary/transcend"},{"title":"Merriam-Webster：surpass","url":"https://www.merriam-webster.com/dictionary/surpass"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"231":{"sense":"v. 彻底改变","collocations":["transform into","convert into"],"example":"The project transformed an empty yard into a community garden.","translation":"项目将空院子改造成了社区花园。","note":"transform强调显著变化；convert常强调用途、形式或系统转换，改变程度不一定相同。","number":231,"resourceId":"doc-026-11-9d39126d1bbf","term":"transform","originalPair":"transform = convert","needsCare":false,"sources":[{"title":"Merriam-Webster：transform","url":"https://www.merriam-webster.com/dictionary/transform"},{"title":"Merriam-Webster：convert","url":"https://www.merriam-webster.com/dictionary/convert"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"232":{"sense":"adj. 透明的；公开清楚的","collocations":["transparent procedures","clear instructions"],"example":"Residents asked for a transparent process for allocating grants.","translation":"居民要求资助分配过程公开透明。","note":"transparent可指材料透光或程序公开；clear范围更广，清楚不自动意味着程序公开。","number":232,"resourceId":"doc-026-11-2b67054c8785","term":"transparent","originalPair":"transparent = clear","needsCare":true,"sources":[{"title":"Merriam-Webster：transparent","url":"https://www.merriam-webster.com/dictionary/transparent"},{"title":"Merriam-Webster：clear","url":"https://www.merriam-webster.com/dictionary/clear"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"233":{"sense":"adj. 背信的；危险难行的","collocations":["a treacherous ally","a treacherous path"],"example":"Ice made the mountain path treacherous.","translation":"结冰使山路变得危险难行。","note":"deceitful对应欺骗义；treacherous还可指道路、天气危险不可靠，本例不能换成deceitful。","number":233,"resourceId":"doc-026-11-d5f121d51c04","term":"treacherous","originalPair":"treacherous = deceitful","needsCare":true,"sources":[{"title":"Merriam-Webster：treacherous","url":"https://www.merriam-webster.com/dictionary/treacherous"},{"title":"Merriam-Webster：deceitful","url":"https://www.merriam-webster.com/dictionary/deceitful"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"234":{"sense":"n. 胜利；重大成功","collocations":["a triumph over","a victory for"],"example":"The clean-up campaign was a triumph for local volunteers.","translation":"清理行动是当地志愿者的一次重大成功。","note":"triumph常强调显著成功或胜利的喜悦；victory也可为具体比赛或选举胜出。","number":234,"resourceId":"doc-026-11-0619b59f5593","term":"triumph","originalPair":"triumph = victory","needsCare":false,"sources":[{"title":"Merriam-Webster：triumph","url":"https://www.merriam-webster.com/dictionary/triumph"},{"title":"Merriam-Webster：victory","url":"https://www.merriam-webster.com/dictionary/victory"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"235":{"sense":"adj. 动荡的；湍急的","collocations":["a turbulent period","chaotic conditions"],"example":"The industry entered a turbulent period of rapid change.","translation":"该行业进入了快速变化的动荡时期。","note":"turbulent强调不稳定或激烈运动；chaotic强调缺少秩序，两者并不总同时成立。","number":235,"resourceId":"doc-026-11-8b943d83179a","term":"turbulent","originalPair":"turbulent = chaotic","needsCare":false,"sources":[{"title":"Merriam-Webster：turbulent","url":"https://www.merriam-webster.com/dictionary/turbulent"},{"title":"Merriam-Webster：chaotic","url":"https://www.merriam-webster.com/dictionary/chaotic"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"236":{"sense":"adj. 最终的；根本的","collocations":["the ultimate goal","a final decision"],"example":"The ultimate goal is to make the service accessible to everyone.","translation":"最终目标是让每个人都能使用这项服务。","note":"ultimate可指根本目标或极致；final指最后阶段或最终决定，语境重点不同。","number":236,"resourceId":"doc-026-11-ac154cd8cfb0","term":"ultimate","originalPair":"ultimate = final","needsCare":false,"sources":[{"title":"Merriam-Webster：ultimate","url":"https://www.merriam-webster.com/dictionary/ultimate"},{"title":"Merriam-Webster：final","url":"https://www.merriam-webster.com/dictionary/final"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"237":{"sense":"v. 逐渐削弱；破坏","collocations":["undermine trust","weaken support"],"example":"Conflicting messages can undermine public trust.","translation":"相互矛盾的信息可能损害公众信任。","note":"undermine常指逐步或间接削弱基础；weaken范围更广，未必暗含这种方式。","number":237,"resourceId":"doc-026-11-ae2208910ea3","term":"undermine","originalPair":"undermine = weaken","needsCare":false,"sources":[{"title":"Merriam-Webster：undermine","url":"https://www.merriam-webster.com/dictionary/undermine"},{"title":"Merriam-Webster：weaken","url":"https://www.merriam-webster.com/dictionary/weaken"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"238":{"sense":"v. 强调","collocations":["underscore the need","emphasize a point"],"example":"The incident underscores the need for regular inspections.","translation":"这一事件凸显了定期检查的必要性。","note":"underscore可用事实使某点更突出；emphasize也可主动强调。underscore作名词还指下划线。","number":238,"resourceId":"doc-026-11-ccec1756a83e","term":"underscore","originalPair":"underscore = emphasize","needsCare":false,"sources":[{"title":"Merriam-Webster：underscore","url":"https://www.merriam-webster.com/dictionary/underscore"},{"title":"Merriam-Webster：emphasize","url":"https://www.merriam-webster.com/dictionary/emphasize"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"239":{"sense":"v. 统一","collocations":["unify standards","integrate services"],"example":"The reform aims to unify safety standards across the region.","translation":"改革旨在统一整个地区的安全标准。","note":"unify强调使成为统一整体；integrate强调整合各部分，整合后仍可能保留不同标准。","number":239,"resourceId":"doc-026-11-9087a2a56108","term":"unify","originalPair":"unify = integrate","needsCare":false,"sources":[{"title":"Merriam-Webster：unify","url":"https://www.merriam-webster.com/dictionary/unify"},{"title":"Merriam-Webster：integrate","url":"https://www.merriam-webster.com/dictionary/integrate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"240":{"sense":"adj. 独一无二的","collocations":["unique features","distinct categories"],"example":"Each neighbourhood has a unique history.","translation":"每个街区都有独特的历史。","note":"unique强调独有；distinct强调可区分、不同或清晰，两个类别不同不代表各自独一无二。","number":240,"resourceId":"doc-026-11-3edc24ea3fb8","term":"unique","originalPair":"unique = distinct","needsCare":true,"sources":[{"title":"Merriam-Webster：unique","url":"https://www.merriam-webster.com/dictionary/unique"},{"title":"Merriam-Webster：distinct","url":"https://www.merriam-webster.com/dictionary/distinct"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"241":{"sense":"v. 解开；弄清","collocations":["unravel a mystery","solve a problem"],"example":"Researchers hope to unravel the reasons for the sudden decline.","translation":"研究人员希望弄清突然下降的原因。","note":"unravel常指逐步解开复杂谜团，也可表示瓦解；solve指解决，不能覆盖瓦解义。","number":241,"resourceId":"doc-026-12-cc5ed4f2ebe8","term":"unravel","originalPair":"unravel = solve","needsCare":false,"sources":[{"title":"Merriam-Webster：unravel","url":"https://www.merriam-webster.com/dictionary/unravel"},{"title":"Merriam-Webster：solve","url":"https://www.merriam-webster.com/dictionary/solve"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"242":{"sense":"adj. 前所未有的","collocations":["unprecedented demand","unparalleled quality"],"example":"The clinic faced unprecedented demand during the heatwave.","translation":"热浪期间，诊所面临前所未有的需求。","note":"unprecedented重在此前未发生；unparalleled重在无可比拟。历史上首次不一定意味着质量无双。","number":242,"resourceId":"doc-026-12-d7d05ecee5fd","term":"unprecedented","originalPair":"unprecedented = unparalleled","needsCare":true,"sources":[{"title":"Merriam-Webster：unprecedented","url":"https://www.merriam-webster.com/dictionary/unprecedented"},{"title":"Merriam-Webster：unparalleled","url":"https://www.merriam-webster.com/dictionary/unparalleled"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"243":{"sense":"v. 维护；维持","collocations":["uphold a principle","support a proposal"],"example":"Courts must uphold the principle of equal treatment.","translation":"法院必须维护平等对待的原则。","note":"uphold可指维护原则或维持裁决；support泛指支持，不能直接说明裁决是否被维持。","number":243,"resourceId":"doc-026-12-1a0cbfc874cd","term":"uphold","originalPair":"uphold = support","needsCare":false,"sources":[{"title":"Merriam-Webster：uphold","url":"https://www.merriam-webster.com/dictionary/uphold"},{"title":"Merriam-Webster：support","url":"https://www.merriam-webster.com/dictionary/support"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"244":{"sense":"v. 敦促","collocations":["urge someone to do","encourage someone to do"],"example":"Teachers urged students to check the source of each claim.","translation":"教师敦促学生核查每项说法的来源。","note":"urge通常比encourage更强、更迫切；两者都可用宾语加to do，但语气有别。","number":244,"resourceId":"doc-026-12-3f671e96dd2b","term":"urge","originalPair":"urge = encourage","needsCare":false,"sources":[{"title":"Merriam-Webster：urge","url":"https://www.merriam-webster.com/dictionary/urge"},{"title":"Merriam-Webster：encourage","url":"https://www.merriam-webster.com/dictionary/encourage"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"245":{"sense":"v. 利用","collocations":["utilize resources","employ a method"],"example":"The centre utilizes empty classrooms for evening courses.","translation":"中心利用闲置教室开设夜校课程。","note":"employ可指采用方法，也可指雇佣；utilize较正式，普通语境用use也常很自然。","number":245,"resourceId":"doc-026-12-1aa4e5a56d43","term":"utilize","originalPair":"utilize = employ","needsCare":false,"sources":[{"title":"Merriam-Webster：utilize","url":"https://www.merriam-webster.com/dictionary/utilize"},{"title":"Merriam-Webster：employ","url":"https://www.merriam-webster.com/dictionary/employ"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"246":{"sense":"v. 验证；使有效","collocations":["validate a method","confirm a booking"],"example":"The team used a second dataset to validate the model.","translation":"团队使用第二套数据验证模型。","note":"validate常强调检验有效性或使生效；confirm还可指确认安排，不能一律译为验证。","number":246,"resourceId":"doc-026-12-3901e3c9ec01","term":"validate","originalPair":"validate = confirm","needsCare":false,"sources":[{"title":"Merriam-Webster：validate","url":"https://www.merriam-webster.com/dictionary/validate"},{"title":"Merriam-Webster：confirm","url":"https://www.merriam-webster.com/dictionary/confirm"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"247":{"sense":"adj. 激烈的；强烈表达的","collocations":["vehement opposition","intense pressure"],"example":"The proposal met with vehement opposition from residents.","translation":"提案遭到了居民的强烈反对。","note":"vehement常形容言语、态度或反对表达激烈；intense范围更广，如高温、压力或疼痛。","number":247,"resourceId":"doc-026-12-04fcb8d3316f","term":"vehement","originalPair":"vehement = intense","needsCare":false,"sources":[{"title":"Merriam-Webster：vehement","url":"https://www.merriam-webster.com/dictionary/vehement"},{"title":"Merriam-Webster：intense","url":"https://www.merriam-webster.com/dictionary/intense"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"248":{"sense":"adj. 多用途的；多才多艺的","collocations":["a versatile tool","adaptable skills"],"example":"A versatile classroom can support lectures and group work.","translation":"多用途教室可同时支持讲授和小组活动。","note":"versatile强调能胜任多种用途；adaptable强调能适应新情况，能适应不等于功能本来就多。","number":248,"resourceId":"doc-026-12-0549fd299537","term":"versatile","originalPair":"versatile = adaptable","needsCare":true,"sources":[{"title":"Merriam-Webster：versatile","url":"https://www.merriam-webster.com/dictionary/versatile"},{"title":"Merriam-Webster：adaptable","url":"https://www.merriam-webster.com/dictionary/adaptable"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"249":{"sense":"adj. 警惕的","collocations":["remain vigilant","watchful for"],"example":"Staff must remain vigilant for signs of equipment failure.","translation":"员工必须警惕设备故障的迹象。","note":"两词均可表示留心观察；vigilant常突出对危险或问题保持警觉。","number":249,"resourceId":"doc-026-12-e990566dfa6c","term":"vigilant","originalPair":"vigilant = watchful","needsCare":false,"sources":[{"title":"Merriam-Webster：vigilant","url":"https://www.merriam-webster.com/dictionary/vigilant"},{"title":"Merriam-Webster：watchful","url":"https://www.merriam-webster.com/dictionary/watchful"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"250":{"sense":"v. 违反；侵犯","collocations":["violate a rule","infringe on rights"],"example":"The company violated the local waste-disposal rules.","translation":"公司违反了当地废物处理规定。","note":"infringe可表示违反或侵犯，常见infringe on rights；不能省掉需要的介词或混淆权利对象。","number":250,"resourceId":"doc-026-12-13223ab52288","term":"violate","originalPair":"violate = infringe","needsCare":false,"sources":[{"title":"Merriam-Webster：violate","url":"https://www.merriam-webster.com/dictionary/violate"},{"title":"Merriam-Webster：infringe","url":"https://www.merriam-webster.com/dictionary/infringe"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"251":{"sense":"adj. 至关重要的","collocations":["vital to","essential for"],"example":"Accurate records are vital to a fair assessment.","translation":"准确的记录对公平评估至关重要。","note":"两词在必要性语境接近；vital还有生命相关义，不能不分义项地替换。","number":251,"resourceId":"doc-026-12-9d019a88bdd0","term":"vital","originalPair":"vital = essential","needsCare":false,"sources":[{"title":"Merriam-Webster：vital","url":"https://www.merriam-webster.com/dictionary/vital"},{"title":"Merriam-Webster：essential","url":"https://www.merriam-webster.com/dictionary/essential"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"252":{"sense":"adj. 生动的；鲜明的","collocations":["a vivid description","vibrant colours"],"example":"The diary gives a vivid description of life in the village.","translation":"日记生动描述了村里的生活。","note":"vivid强调画面感、清晰或鲜明；vibrant常指色彩鲜艳或充满活力，不等于描写生动。","number":252,"resourceId":"doc-026-12-5d26f816ad08","term":"vivid","originalPair":"vivid = vibrant","needsCare":true,"sources":[{"title":"Merriam-Webster：vivid","url":"https://www.merriam-webster.com/dictionary/vivid"},{"title":"Merriam-Webster：vibrant","url":"https://www.merriam-webster.com/dictionary/vibrant"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"253":{"sense":"adj. 易变的；挥发性的","collocations":["volatile prices","an unstable system"],"example":"Fuel prices remained volatile throughout the winter.","translation":"整个冬季燃料价格都波动不定。","note":"volatile强调容易突然变化，也指化学物质易挥发；unstable较广义地指不稳定。","number":253,"resourceId":"doc-026-12-65adab34c024","term":"volatile","originalPair":"volatile = unstable","needsCare":false,"sources":[{"title":"Merriam-Webster：volatile","url":"https://www.merriam-webster.com/dictionary/volatile"},{"title":"Merriam-Webster：unstable","url":"https://www.merriam-webster.com/dictionary/unstable"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"254":{"sense":"adj. 易受伤害的","collocations":["vulnerable to","susceptible to"],"example":"Low-lying homes are vulnerable to flooding.","translation":"地势低洼的住宅容易受到洪水侵袭。","note":"vulnerable强调易遭伤害；susceptible也可指易受影响或感染，两者都常接to。","number":254,"resourceId":"doc-026-12-d24f5ce92b4d","term":"vulnerable","originalPair":"vulnerable = susceptible","needsCare":true,"sources":[{"title":"Merriam-Webster：vulnerable","url":"https://www.merriam-webster.com/dictionary/vulnerable"},{"title":"Merriam-Webster：susceptible","url":"https://www.merriam-webster.com/dictionary/susceptible"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"255":{"sense":"v. 使有必要；成为正当理由","collocations":["warrant attention","justify a decision"],"example":"These findings warrant further investigation.","translation":"这些发现值得进一步调查。","note":"warrant在此表示足以构成采取行动的理由；justify强调说明某行为正当。原中文有杂字，学习释义已另行整理。","number":255,"resourceId":"doc-026-12-491d87afc28b","term":"warrant","originalPair":"warrant = justify","needsCare":false,"sources":[{"title":"Merriam-Webster：warrant","url":"https://www.merriam-webster.com/dictionary/warrant"},{"title":"Merriam-Webster：justify","url":"https://www.merriam-webster.com/dictionary/justify"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"256":{"sense":"adj. 疲倦的；厌倦的","collocations":["weary after","weary of"],"example":"The volunteers were weary after a long day of repairs.","translation":"维修忙了一整天后，志愿者感到疲倦。","note":"fatigued对应疲劳义，较正式；weary of常表示厌倦某事，不仅是体力疲劳。","number":256,"resourceId":"doc-026-12-920c7a178ace","term":"weary","originalPair":"weary = fatigued","needsCare":false,"sources":[{"title":"Merriam-Webster：weary","url":"https://www.merriam-webster.com/dictionary/weary"},{"title":"Merriam-Webster：fatigued","url":"https://www.merriam-webster.com/dictionary/fatigued"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"257":{"sense":"adj. 分布广的；普遍的","collocations":["widespread concern","prevalent among"],"example":"There is widespread concern about the loss of green space.","translation":"人们普遍担忧绿地减少。","note":"widespread强调覆盖广；prevalent常强调某现象在某地区或群体中常见，搭配结构不同。","number":257,"resourceId":"doc-026-12-eb3c9103e020","term":"widespread","originalPair":"widespread = prevalent","needsCare":false,"sources":[{"title":"Merriam-Webster：widespread","url":"https://www.merriam-webster.com/dictionary/widespread"},{"title":"Merriam-Webster：prevalent","url":"https://www.merriam-webster.com/dictionary/prevalent"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"258":{"sense":"v. 撤回；退出","collocations":["withdraw support","retract a statement"],"example":"The organisation withdrew its support for the proposal.","translation":"该组织撤回了对提案的支持。","note":"retract常接声明、指控或话语；withdraw还可退出活动、提款或撤军，不可都替换。","number":258,"resourceId":"doc-026-12-0650b3f5495a","term":"withdraw","originalPair":"withdraw = retract","needsCare":true,"sources":[{"title":"Merriam-Webster：withdraw","url":"https://www.merriam-webster.com/dictionary/withdraw"},{"title":"Merriam-Webster：retract","url":"https://www.merriam-webster.com/dictionary/retract"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"259":{"sense":"v. 承受住；抵抗","collocations":["withstand pressure","endure hardship"],"example":"The bridge was designed to withstand strong winds.","translation":"这座桥的设计能够抵御强风。","note":"withstand强调抵住外力而未失效；endure强调承受困难或持续，不保证结构不受损。","number":259,"resourceId":"doc-026-12-09a812a27433","term":"withstand","originalPair":"withstand = endure","needsCare":false,"sources":[{"title":"Merriam-Webster：withstand","url":"https://www.merriam-webster.com/dictionary/withstand"},{"title":"Merriam-Webster：endure","url":"https://www.merriam-webster.com/dictionary/endure"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"260":{"sense":"v. 产生；提供","collocations":["yield results","produce crops"],"example":"The experiment yielded more reliable results than expected.","translation":"实验得到了比预期更可靠的结果。","note":"yield可指产出，也可指让步或屈服；produce对应产出义，不能覆盖全部义项。","number":260,"resourceId":"doc-026-12-ca41bea1946b","term":"yield","originalPair":"yield = produce","needsCare":false,"sources":[{"title":"Merriam-Webster：yield","url":"https://www.merriam-webster.com/dictionary/yield"},{"title":"Merriam-Webster：produce","url":"https://www.merriam-webster.com/dictionary/produce"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"261":{"sense":"adj. 突然的；生硬的","collocations":["an abrupt change","a sudden stop"],"example":"The abrupt change in policy confused many applicants.","translation":"政策的突然变化让许多申请者困惑。","note":"sudden对应突然义；abrupt还可指说话生硬或地形陡峭，不能都换成sudden。","number":261,"resourceId":"doc-026-12-25ba874d4570","term":"abrupt","originalPair":"abrupt = sudden","needsCare":false,"sources":[{"title":"Merriam-Webster：abrupt","url":"https://www.merriam-webster.com/dictionary/abrupt"},{"title":"Merriam-Webster：sudden","url":"https://www.merriam-webster.com/dictionary/sudden"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"262":{"sense":"v. 加速","collocations":["accelerate growth","speed up a process"],"example":"Better transport could accelerate the town's economic recovery.","translation":"更好的交通可能加快小镇经济复苏。","note":"speed up较口语，accelerate较正式；两者可及物或不及物，不能据此假定增长幅度。","number":262,"resourceId":"doc-026-12-568d3acacee1","term":"accelerate","originalPair":"accelerate = speed up","needsCare":false,"sources":[{"title":"Merriam-Webster：accelerate","url":"https://www.merriam-webster.com/dictionary/accelerate"},{"title":"Merriam-Webster：speed up","url":"https://www.merriam-webster.com/dictionary/speed%20up"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"263":{"sense":"v. 容纳；满足需要；适应","collocations":["accommodate needs","accommodate to"],"example":"The new rooms can accommodate students with different needs.","translation":"新房间能够满足有不同需求的学生。","note":"accommodate常指容纳或照顾需要；表示自身适应可用accommodate oneself to。不能把adapt to一律换成直接及物形式。","number":263,"resourceId":"doc-026-13-153f209cb2e1","term":"accommodate","originalPair":"accommodate = adapt","needsCare":true,"sources":[{"title":"Merriam-Webster：accommodate","url":"https://www.merriam-webster.com/dictionary/accommodate"},{"title":"Merriam-Webster：adapt","url":"https://www.merriam-webster.com/dictionary/adapt"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"264":{"sense":"adj. 相邻的","collocations":["adjacent to","neighbouring buildings"],"example":"The playground is adjacent to the public library.","translation":"操场紧邻公共图书馆。","note":"adjacent常指直接毗邻，通常接to；neighbouring也可泛指附近，不一定边界相接。","number":264,"resourceId":"doc-026-13-52a0965cf65a","term":"adjacent","originalPair":"adjacent = neighboring","needsCare":false,"sources":[{"title":"Merriam-Webster：adjacent","url":"https://www.merriam-webster.com/dictionary/adjacent"},{"title":"Merriam-Webster：neighboring","url":"https://www.merriam-webster.com/dictionary/neighboring"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"265":{"sense":"v. 放大；增强","collocations":["amplify a signal","enhance quality"],"example":"The device amplifies weak audio signals.","translation":"这台设备放大较弱的音频信号。","note":"amplify强调增大幅度、声音或说明；enhance强调质量或效果提升，放大不保证音质提升。","number":265,"resourceId":"doc-026-13-ff7e6077fbb0","term":"amplify","originalPair":"amplify = enhance","needsCare":false,"sources":[{"title":"Merriam-Webster：amplify","url":"https://www.merriam-webster.com/dictionary/amplify"},{"title":"Merriam-Webster：enhance","url":"https://www.merriam-webster.com/dictionary/enhance"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"266":{"sense":"v. 激怒；引起敌意","collocations":["antagonize someone","provoke a reaction"],"example":"Repeated interruptions may antagonize the audience.","translation":"反复打断可能激怒观众。","note":"antagonize强调使人不满或产生敌意；provoke还可指引起一般反应，不一定激怒。","number":266,"resourceId":"doc-026-13-b5920f30e00e","term":"antagonize","originalPair":"antagonize = provoke","needsCare":false,"sources":[{"title":"Merriam-Webster：antagonize","url":"https://www.merriam-webster.com/dictionary/antagonize"},{"title":"Merriam-Webster：provoke","url":"https://www.merriam-webster.com/dictionary/provoke"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"267":{"sense":"adj. 陈旧过时的","collocations":["antiquated equipment","outdated rules"],"example":"The clinic replaced its antiquated booking system.","translation":"诊所更换了陈旧的预约系统。","note":"antiquated常带老旧到不适用的批评意味；outdated可仅指信息或规则不再适时。","number":267,"resourceId":"doc-026-13-2dbe51adbc0e","term":"antiquated","originalPair":"antiquated = outdated","needsCare":false,"sources":[{"title":"Merriam-Webster：antiquated","url":"https://www.merriam-webster.com/dictionary/antiquated"},{"title":"Merriam-Webster：outdated","url":"https://www.merriam-webster.com/dictionary/outdated"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"268":{"sense":"n. 冷漠；缺乏兴趣","collocations":["apathy towards","indifference to"],"example":"Low turnout may reflect apathy towards local elections.","translation":"低投票率可能反映对地方选举的冷漠。","note":"apathy强调缺乏兴趣或动力；indifference也可表示无偏好、不在意，原因未必相同。","number":268,"resourceId":"doc-026-13-1e0ed35c35a1","term":"apathy","originalPair":"apathy = indifference","needsCare":false,"sources":[{"title":"Merriam-Webster：apathy","url":"https://www.merriam-webster.com/dictionary/apathy"},{"title":"Merriam-Webster：indifference","url":"https://www.merriam-webster.com/dictionary/indifference"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"269":{"sense":"adj. 忧虑的","collocations":["apprehensive about","anxious about"],"example":"New staff felt apprehensive about using the unfamiliar system.","translation":"新员工对使用不熟悉的系统感到不安。","note":"apprehensive侧重对将来可能发生的事担忧；anxious还可指热切希望，不能覆盖所有义项。","number":269,"resourceId":"doc-026-13-b8873dca0e62","term":"apprehensive","originalPair":"apprehensive = anxious","needsCare":false,"sources":[{"title":"Merriam-Webster：apprehensive","url":"https://www.merriam-webster.com/dictionary/apprehensive"},{"title":"Merriam-Webster：anxious","url":"https://www.merriam-webster.com/dictionary/anxious"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"270":{"sense":"adj. 任意的；武断的","collocations":["an arbitrary decision","a random sample"],"example":"Applicants objected to the arbitrary selection criteria.","translation":"申请者反对武断的选拔标准。","note":"arbitrary指缺乏合理一致依据；random指随机。统计随机抽样不应被说成武断选取。","number":270,"resourceId":"doc-026-13-21847fbdd958","term":"arbitrary","originalPair":"arbitrary = random","needsCare":true,"sources":[{"title":"Merriam-Webster：arbitrary","url":"https://www.merriam-webster.com/dictionary/arbitrary"},{"title":"Merriam-Webster：random","url":"https://www.merriam-webster.com/dictionary/random"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"271":{"sense":"v. 清楚表达","collocations":["articulate an idea","express a concern"],"example":"Students should learn to articulate their arguments clearly.","translation":"学生应学会清楚表达自己的论点。","note":"articulate强调表达清晰；express只表示表达。articulate还可作形容词“善于表达的”。","number":271,"resourceId":"doc-026-13-b3d6b1f46239","term":"articulate","originalPair":"articulate = express","needsCare":false,"sources":[{"title":"Merriam-Webster：articulate","url":"https://www.merriam-webster.com/dictionary/articulate"},{"title":"Merriam-Webster：express","url":"https://www.merriam-webster.com/dictionary/express"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"272":{"sense":"v. 上升；攀登","collocations":["ascend the stairs","rise gradually"],"example":"Visitors ascend a narrow staircase to reach the gallery.","translation":"游客沿狭窄楼梯上行，来到展厅。","note":"ascend可直接接所攀登的对象；rise通常不及物，不能说rise the staircase。","number":272,"resourceId":"doc-026-13-cca378c0651a","term":"ascend","originalPair":"ascend = rise","needsCare":false,"sources":[{"title":"Merriam-Webster：ascend","url":"https://www.merriam-webster.com/dictionary/ascend"},{"title":"Merriam-Webster：rise","url":"https://www.merriam-webster.com/dictionary/rise"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"273":{"sense":"v. 断言；主张","collocations":["assert that","claim that"],"example":"The report asserts that current funding is insufficient.","translation":"报告断言现有资金不足。","note":"assert常强调坚定表态；claim是声称，未必已证实。二者都不能代替证明事实。","number":273,"resourceId":"doc-026-13-25baf43be200","term":"assert","originalPair":"assert = claim","needsCare":false,"sources":[{"title":"Merriam-Webster：assert","url":"https://www.merriam-webster.com/dictionary/assert"},{"title":"Merriam-Webster：claim","url":"https://www.merriam-webster.com/dictionary/claim"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"274":{"sense":"v. 评估","collocations":["assess progress","evaluate a proposal"],"example":"The tutor assessed my progress after six lessons.","translation":"上了六节课后，导师评估了我的进步。","note":"evaluate也可指评估价值、质量或成效；两词在评估语境中接近，仍须保留合适宾语。","number":274,"resourceId":"doc-026-13-16e196b8163a","term":"assess","originalPair":"assess = evaluate","needsCare":false,"sources":[{"title":"Merriam-Webster：assess","url":"https://www.merriam-webster.com/dictionary/assess"},{"title":"Merriam-Webster：evaluate","url":"https://www.merriam-webster.com/dictionary/evaluate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"275":{"sense":"v. 增加","collocations":["augment capacity","increase output"],"example":"The extra workshop will augment the college's teaching capacity.","translation":"新增工作坊将扩大学院的教学能力。","note":"augment较正式，侧重在已有基础上增添；increase较常用，可及物也可不及物。","number":275,"resourceId":"doc-026-13-b9813463a8f5","term":"augment","originalPair":"augment = increase","needsCare":false,"sources":[{"title":"Merriam-Webster：augment","url":"https://www.merriam-webster.com/dictionary/augment"},{"title":"Merriam-Webster：increase","url":"https://www.merriam-webster.com/dictionary/increase"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"276":{"sense":"adj. 真实的；非伪造的","collocations":["authentic documents","genuine interest"],"example":"The museum displayed an authentic nineteenth-century map.","translation":"博物馆展出了一张真正的十九世纪地图。","note":"genuine也可指非伪造，但还可表示真诚；authentic也常强调来源可信或符合原貌。","number":276,"resourceId":"doc-026-13-36acd13d0df0","term":"authentic","originalPair":"authentic = genuine","needsCare":false,"sources":[{"title":"Merriam-Webster：authentic","url":"https://www.merriam-webster.com/dictionary/authentic"},{"title":"Merriam-Webster：genuine","url":"https://www.merriam-webster.com/dictionary/genuine"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"277":{"sense":"v. 避免；防止","collocations":["avert a crisis","prevent an accident"],"example":"Early repairs helped avert a serious equipment failure.","translation":"及时维修帮助避免了严重设备故障。","note":"avert常接危险、危机等不良结果；prevent更一般，且可用prevent someone from doing。","number":277,"resourceId":"doc-026-13-02e59ac0f2d0","term":"avert","originalPair":"avert = prevent","needsCare":false,"sources":[{"title":"Merriam-Webster：avert","url":"https://www.merriam-webster.com/dictionary/avert"},{"title":"Merriam-Webster：prevent","url":"https://www.merriam-webster.com/dictionary/prevent"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"278":{"sense":"adj. 有偏向的","collocations":["biased against","prejudiced against"],"example":"A biased sample can produce misleading conclusions.","translation":"有偏的样本可能导致误导性结论。","note":"biased可指统计抽样偏差或倾向；prejudiced常指对人或群体的成见，不宜替代统计术语。","number":278,"resourceId":"doc-026-13-038640b12e7c","term":"biased","originalPair":"biased = prejudiced","needsCare":true,"sources":[{"title":"Merriam-Webster：biased","url":"https://www.merriam-webster.com/dictionary/biased"},{"title":"Merriam-Webster：prejudiced","url":"https://www.merriam-webster.com/dictionary/prejudiced"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"279":{"sense":"v. 提升；促进","collocations":["boost confidence","enhance quality"],"example":"Lower entry fees could boost attendance at the museum.","translation":"降低门票价格可能增加博物馆参观人数。","note":"boost可提高数量或信心；enhance侧重改善价值或效果，不总等于人数增加。","number":279,"resourceId":"doc-026-13-d9c089d7ad85","term":"boost","originalPair":"boost = enhance","needsCare":false,"sources":[{"title":"Merriam-Webster：boost","url":"https://www.merriam-webster.com/dictionary/boost"},{"title":"Merriam-Webster：enhance","url":"https://www.merriam-webster.com/dictionary/enhance"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"280":{"sense":"v. 停止","collocations":["cease to do","stop doing"],"example":"The machinery ceased to function after the power cut.","translation":"停电后机器停止运作。","note":"cease较正式；stop doing是停止该行为，stop to do却是停下来去做另一事，注意结构。","number":280,"resourceId":"doc-026-13-48e26c4d44b7","term":"cease","originalPair":"cease = stop","needsCare":false,"sources":[{"title":"Merriam-Webster：cease","url":"https://www.merriam-webster.com/dictionary/cease"},{"title":"Merriam-Webster：stop","url":"https://www.merriam-webster.com/dictionary/stop"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"281":{"sense":"adj. 混乱的","collocations":["chaotic traffic","disorderly conduct"],"example":"The station became chaotic when several trains were cancelled.","translation":"几趟列车取消后，车站陷入混乱。","note":"chaotic常指极度缺乏秩序；disorderly还可描述不守秩序的行为，语境强度需匹配。","number":281,"resourceId":"doc-026-13-8bdb06b12d66","term":"chaotic","originalPair":"chaotic = disorderly","needsCare":false,"sources":[{"title":"Merriam-Webster：chaotic","url":"https://www.merriam-webster.com/dictionary/chaotic"},{"title":"Merriam-Webster：disorderly","url":"https://www.merriam-webster.com/dictionary/disorderly"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"282":{"sense":"v. 循环；流传","collocations":["circulate information","distribute leaflets"],"example":"The draft report circulated among the committee members.","translation":"报告草稿在委员会成员间传阅。","note":"circulate强调流转或传播；distribute强调分发给各人，血液循环不能换成distribute。","number":282,"resourceId":"doc-026-13-2ce4a4383b0a","term":"circulate","originalPair":"circulate = distribute","needsCare":true,"sources":[{"title":"Merriam-Webster：circulate","url":"https://www.merriam-webster.com/dictionary/circulate"},{"title":"Merriam-Webster：distribute","url":"https://www.merriam-webster.com/dictionary/distribute"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"283":{"sense":"v./n. 冲突","collocations":["clash with","conflict with"],"example":"The new timetable clashes with several compulsory classes.","translation":"新时间表与几门必修课的时间冲突。","note":"clash还可指碰撞、色彩不协调；conflict可指利益、原则冲突，词性和搭配需对应。","number":283,"resourceId":"doc-026-13-6d421c701844","term":"clash","originalPair":"clash = conflict","needsCare":false,"sources":[{"title":"Merriam-Webster：clash","url":"https://www.merriam-webster.com/dictionary/clash"},{"title":"Merriam-Webster：conflict","url":"https://www.merriam-webster.com/dictionary/conflict"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"284":{"sense":"adj. 连贯的","collocations":["a coherent explanation","logical reasoning"],"example":"The student gave a coherent explanation of the process.","translation":"学生连贯地解释了这一过程。","note":"logical强调符合推理规则；coherent强调整体清楚连贯。连贯叙述仍可能包含逻辑错误。","number":284,"resourceId":"doc-026-13-b104aa346719","term":"coherent","originalPair":"coherent = logical","needsCare":false,"sources":[{"title":"Merriam-Webster：coherent","url":"https://www.merriam-webster.com/dictionary/coherent"},{"title":"Merriam-Webster：logical","url":"https://www.merriam-webster.com/dictionary/logical"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"285":{"sense":"v. 开始（正式）","collocations":["commence work","begin doing"],"example":"Construction will commence after the safety inspection.","translation":"施工将在安全检查后开始。","note":"commence较正式，多用于项目或活动；begin更常用，不能只为正式而使普通表达生硬。","number":285,"resourceId":"doc-026-14-a5cfb65d9d1a","term":"commence","originalPair":"commence = begin","needsCare":false,"sources":[{"title":"Merriam-Webster：commence","url":"https://www.merriam-webster.com/dictionary/commence"},{"title":"Merriam-Webster：begin","url":"https://www.merriam-webster.com/dictionary/begin"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"286":{"sense":"v. 纪念","collocations":["commemorate an event","celebrate an achievement"],"example":"The exhibition commemorates the opening of the first local school.","translation":"展览纪念当地第一所学校的创立。","note":"commemorate可纪念悲伤或庄重事件；celebrate常带庆祝意味，不能把所有悼念写成庆祝。","number":286,"resourceId":"doc-026-14-4bb3dd582578","term":"commemorate","originalPair":"commemorate = celebrate","needsCare":true,"sources":[{"title":"Merriam-Webster：commemorate","url":"https://www.merriam-webster.com/dictionary/commemorate"},{"title":"Merriam-Webster：celebrate","url":"https://www.merriam-webster.com/dictionary/celebrate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"287":{"sense":"adj. 兼容的；相容的","collocations":["compatible with","harmonious relations"],"example":"The file format is compatible with most reading apps.","translation":"该文件格式与大多数阅读应用兼容。","note":"compatible强调能一起使用或共存；harmonious强调和谐协调，不是软件兼容的常用替换。","number":287,"resourceId":"doc-026-14-83c1593f87c9","term":"compatible","originalPair":"compatible = harmonious","needsCare":true,"sources":[{"title":"Merriam-Webster：compatible","url":"https://www.merriam-webster.com/dictionary/compatible"},{"title":"Merriam-Webster：harmonious","url":"https://www.merriam-webster.com/dictionary/harmonious"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"288":{"sense":"v. 强迫；迫使","collocations":["compel someone to do","force someone to do"],"example":"Rising costs compelled the club to reduce its opening hours.","translation":"成本上涨迫使俱乐部缩短开放时间。","note":"compel较正式，可由情势迫使；force也可指身体强制。不要漏掉宾语后的to。","number":288,"resourceId":"doc-026-14-abba4fb3ccb5","term":"compel","originalPair":"compel = force","needsCare":false,"sources":[{"title":"Merriam-Webster：compel","url":"https://www.merriam-webster.com/dictionary/compel"},{"title":"Merriam-Webster：force","url":"https://www.merriam-webster.com/dictionary/force"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"289":{"sense":"v. 补偿","collocations":["compensate for","reimburse expenses"],"example":"The airline compensated passengers for the cancelled flight.","translation":"航空公司因航班取消向乘客作出补偿。","note":"reimburse通常指报销或偿还已经支出的费用；compensate可补偿更广泛的损失，不必等额报销。","number":289,"resourceId":"doc-026-14-1bd87f81a548","term":"compensate","originalPair":"compensate = reimburse","needsCare":true,"sources":[{"title":"Merriam-Webster：compensate","url":"https://www.merriam-webster.com/dictionary/compensate"},{"title":"Merriam-Webster：reimburse","url":"https://www.merriam-webster.com/dictionary/reimburse"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"290":{"sense":"adj. 简洁的","collocations":["a concise answer","a brief visit"],"example":"A concise answer can still include the essential evidence.","translation":"简洁的回答仍能包含必要证据。","note":"concise强调用词精练且不冗余；brief只强调短，短文未必写得精练。","number":290,"resourceId":"doc-026-14-dcc62ee8548b","term":"concise","originalPair":"concise = brief","needsCare":false,"sources":[{"title":"Merriam-Webster：concise","url":"https://www.merriam-webster.com/dictionary/concise"},{"title":"Merriam-Webster：brief","url":"https://www.merriam-webster.com/dictionary/brief"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"291":{"sense":"v. 同意（正式）","collocations":["concur with","concur that"],"example":"Most reviewers concurred with the main recommendation.","translation":"大多数评审者同意主要建议。","note":"concur常见于正式认同；agree更普遍，还可指同意做某事。不要照搬agree to do的全部句型。","number":291,"resourceId":"doc-026-14-bda996b41ada","term":"concur","originalPair":"concur = agree","needsCare":false,"sources":[{"title":"Merriam-Webster：concur","url":"https://www.merriam-webster.com/dictionary/concur"},{"title":"Merriam-Webster：agree","url":"https://www.merriam-webster.com/dictionary/agree"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"292":{"sense":"v. 限制；禁闭","collocations":["confine to","restrict access"],"example":"The study confines its analysis to urban households.","translation":"研究将分析范围限定在城市家庭。","note":"confine to常用于限制范围或活动空间；restrict更广泛，不能漏掉范围前的to。","number":292,"resourceId":"doc-026-14-eb3f2477b8f3","term":"confine","originalPair":"confine = restrict","needsCare":false,"sources":[{"title":"Merriam-Webster：confine","url":"https://www.merriam-webster.com/dictionary/confine"},{"title":"Merriam-Webster：restrict","url":"https://www.merriam-webster.com/dictionary/restrict"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"293":{"sense":"adj. 拥堵的","collocations":["congested roads","crowded rooms"],"example":"The roads become congested near the school each morning.","translation":"每天早晨学校附近的道路都很拥堵。","note":"congested强调流动被阻塞；crowded强调人或物多而拥挤，人多不一定导致交通阻塞。","number":293,"resourceId":"doc-026-14-30d15741efe4","term":"congested","originalPair":"congested = crowded","needsCare":false,"sources":[{"title":"Merriam-Webster：congested","url":"https://www.merriam-webster.com/dictionary/congested"},{"title":"Merriam-Webster：crowded","url":"https://www.merriam-webster.com/dictionary/crowded"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"294":{"sense":"n. 共识","collocations":["reach a consensus on","agreement about"],"example":"The group reached a consensus on the first three priorities.","translation":"小组就前三项优先事项达成共识。","note":"consensus强调群体总体意见一致，不必声称每个人毫无异议；agreement还可指合同或两方同意。","number":294,"resourceId":"doc-026-14-1c7c111afb88","term":"consensus","originalPair":"consensus = agreement","needsCare":false,"sources":[{"title":"Merriam-Webster：consensus","url":"https://www.merriam-webster.com/dictionary/consensus"},{"title":"Merriam-Webster：agreement","url":"https://www.merriam-webster.com/dictionary/agreement"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"295":{"sense":"adj. 稳定一致的","collocations":["consistent performance","steady growth"],"example":"The class showed consistent improvement throughout the term.","translation":"这个班在整个学期持续取得进步。","note":"consistent强调前后一贯；steady强调稳定持续。consistent with表示与……相符时不能换steady。","number":295,"resourceId":"doc-026-14-5c5282a90993","term":"consistent","originalPair":"consistent = steady","needsCare":true,"sources":[{"title":"Merriam-Webster：consistent","url":"https://www.merriam-webster.com/dictionary/consistent"},{"title":"Merriam-Webster：steady","url":"https://www.merriam-webster.com/dictionary/steady"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"296":{"sense":"adj. 显眼的","collocations":["a conspicuous absence","a noticeable change"],"example":"The lack of bicycle parking was conspicuous.","translation":"自行车停车位不足的问题十分显眼。","note":"conspicuous往往比noticeable更引人注目；显眼不等于重要，也不必然带褒义。","number":296,"resourceId":"doc-026-14-69bb41979f2f","term":"conspicuous","originalPair":"conspicuous = noticeable","needsCare":false,"sources":[{"title":"Merriam-Webster：conspicuous","url":"https://www.merriam-webster.com/dictionary/conspicuous"},{"title":"Merriam-Webster：noticeable","url":"https://www.merriam-webster.com/dictionary/noticeable"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"297":{"sense":"adj. 当代的；同时代的","collocations":["contemporary art","modern technology"],"example":"The gallery mainly exhibits contemporary local art.","translation":"画廊主要展出当地当代艺术。","note":"contemporary可指当下，也可指与过去某人同时代；modern另有现代艺术史等特定义项。","number":297,"resourceId":"doc-026-14-07f8738ee742","term":"contemporary","originalPair":"contemporary = modern","needsCare":true,"sources":[{"title":"Merriam-Webster：contemporary","url":"https://www.merriam-webster.com/dictionary/contemporary"},{"title":"Merriam-Webster：modern","url":"https://www.merriam-webster.com/dictionary/modern"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"298":{"sense":"v. 反驳；与……不一致","collocations":["contradict a statement","oppose a proposal"],"example":"The witness's account contradicts the video evidence.","translation":"证人的叙述与视频证据不一致。","note":"oppose表示反对某行动或立场；contradict常表示说法之间矛盾，反对不一定构成反证。","number":298,"resourceId":"doc-026-14-5d2b37a89c38","term":"contradict","originalPair":"contradict = oppose","needsCare":true,"sources":[{"title":"Merriam-Webster：contradict","url":"https://www.merriam-webster.com/dictionary/contradict"},{"title":"Merriam-Webster：oppose","url":"https://www.merriam-webster.com/dictionary/oppose"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"299":{"sense":"v. 召集；召开","collocations":["convene a meeting","gather information"],"example":"The council convened a meeting to discuss the flood damage.","translation":"市议会召开会议讨论洪灾损失。","note":"convene主要用于召集会议或人员开会；gather泛指聚集或收集，不能用于所有召开语境。","number":299,"resourceId":"doc-026-14-9e0274287df2","term":"convene","originalPair":"convene = gather","needsCare":false,"sources":[{"title":"Merriam-Webster：convene","url":"https://www.merriam-webster.com/dictionary/convene"},{"title":"Merriam-Webster：gather","url":"https://www.merriam-webster.com/dictionary/gather"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"300":{"sense":"v. 转换；改作","collocations":["convert into","transform into"],"example":"The town converted an old warehouse into a study centre.","translation":"小镇把一座旧仓库改成了学习中心。","note":"convert常突出用途或形式转换；transform突出显著变化。货币或单位换算通常用convert。","number":300,"resourceId":"doc-026-14-38a4483f5d0f","term":"convert","originalPair":"convert = transform","needsCare":false,"sources":[{"title":"Merriam-Webster：convert","url":"https://www.merriam-webster.com/dictionary/convert"},{"title":"Merriam-Webster：transform","url":"https://www.merriam-webster.com/dictionary/transform"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"301":{"sense":"v. 传达；运送","collocations":["convey a message","communicate with"],"example":"The diagram conveys the main idea more clearly than the paragraph.","translation":"图示比那段文字更清楚地传达了主要意思。","note":"communicate可指传达或交流；convey还可指运送。communicate with someone不能照搬为convey with someone。","number":301,"resourceId":"doc-026-14-534b9f94259b","term":"convey","originalPair":"convey = communicate","needsCare":false,"sources":[{"title":"Merriam-Webster：convey","url":"https://www.merriam-webster.com/dictionary/convey"},{"title":"Merriam-Webster：communicate","url":"https://www.merriam-webster.com/dictionary/communicate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"302":{"sense":"adj./n. 伪造的；赝品","collocations":["counterfeit money","fake documents"],"example":"The shop discovered several counterfeit banknotes.","translation":"商店发现了几张假钞。","note":"counterfeit常指仿造真品、意在冒充；fake范围更广，也可表示假装的情绪或行为。","number":302,"resourceId":"doc-026-14-1d04d3289006","term":"counterfeit","originalPair":"counterfeit = fake","needsCare":false,"sources":[{"title":"Merriam-Webster：counterfeit","url":"https://www.merriam-webster.com/dictionary/counterfeit"},{"title":"Merriam-Webster：fake","url":"https://www.merriam-webster.com/dictionary/fake"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"303":{"sense":"n. 对应的人或物","collocations":["a counterpart in","an equivalent qualification"],"example":"The director met her counterpart from the neighbouring college.","translation":"主任会见了邻近学院担任对应职务的人。","note":"counterpart强调对应位置或功能的人物；equivalent强调价值或效力相当，不一定是对应职务。","number":303,"resourceId":"doc-026-14-de9648c13df6","term":"counterpart","originalPair":"counterpart = equivalent","needsCare":true,"sources":[{"title":"Merriam-Webster：counterpart","url":"https://www.merriam-webster.com/dictionary/counterpart"},{"title":"Merriam-Webster：equivalent","url":"https://www.merriam-webster.com/dictionary/equivalent"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"304":{"sense":"adj. 至关重要的","collocations":["crucial evidence","a critical role"],"example":"Clear guidance is crucial for new students.","translation":"清楚的指导对新生至关重要。","note":"critical在重要义上与crucial接近；critical还可表示批评的或病情危急，须看具体义项。","number":304,"resourceId":"doc-026-14-f4e5794943b8","term":"crucial","originalPair":"crucial = critical","needsCare":false,"sources":[{"title":"Merriam-Webster：crucial","url":"https://www.merriam-webster.com/dictionary/crucial"},{"title":"Merriam-Webster：critical","url":"https://www.merriam-webster.com/dictionary/critical"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"305":{"sense":"v. 达到高潮；以……告终","collocations":["culminate in","conclude with"],"example":"The course culminates in a public presentation.","translation":"课程最终以公开展示收尾。","note":"culminate强调发展到顶点或最终结果；conclude只是结束。并非每次结束都有高潮。","number":305,"resourceId":"doc-026-14-31f800dc266c","term":"culminate","originalPair":"culminate = conclude","needsCare":true,"sources":[{"title":"Merriam-Webster：culminate","url":"https://www.merriam-webster.com/dictionary/culminate"},{"title":"Merriam-Webster：conclude","url":"https://www.merriam-webster.com/dictionary/conclude"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"306":{"sense":"adj. 笨重的；繁琐的","collocations":["cumbersome procedures","unwieldy equipment"],"example":"The school replaced its cumbersome registration process.","translation":"学校替换了繁琐的注册流程。","note":"两词都可表示难处理；cumbersome还常形容程序繁琐，unwieldy常突出体积或组织难驾驭。","number":306,"resourceId":"doc-026-14-8d0306edec93","term":"cumbersome","originalPair":"cumbersome = unwieldy","needsCare":false,"sources":[{"title":"Merriam-Webster：cumbersome","url":"https://www.merriam-webster.com/dictionary/cumbersome"},{"title":"Merriam-Webster：unwieldy","url":"https://www.merriam-webster.com/dictionary/unwieldy"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"307":{"sense":"v. 辨认；破译","collocations":["decipher handwriting","decode a message"],"example":"I could barely decipher the faded handwriting.","translation":"我几乎辨认不出褪色的字迹。","note":"decipher可指读懂潦草或模糊文字；decode强调解码，不是所有辨认文字都涉及密码。","number":307,"resourceId":"doc-026-15-1b0db26885ff","term":"decipher","originalPair":"decipher = decode","needsCare":false,"sources":[{"title":"Merriam-Webster：decipher","url":"https://www.merriam-webster.com/dictionary/decipher"},{"title":"Merriam-Webster：decode","url":"https://www.merriam-webster.com/dictionary/decode"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"308":{"sense":"n. 缺乏；不足","collocations":["a deficiency in","an insufficiency of"],"example":"The review revealed a deficiency in staff training.","translation":"审查发现员工培训存在不足。","note":"deficiency常指缺陷或特定成分缺乏；insufficiency偏重数量或程度不够。","number":308,"resourceId":"doc-026-15-665cd28f603c","term":"deficiency","originalPair":"deficiency = insufficiency","needsCare":false,"sources":[{"title":"Merriam-Webster：deficiency","url":"https://www.merriam-webster.com/dictionary/deficiency"},{"title":"Merriam-Webster：insufficiency","url":"https://www.merriam-webster.com/dictionary/insufficiency"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"309":{"sense":"v. 降低质量；使退化","collocations":["degrade soil","deteriorate over time"],"example":"Excessive grazing can degrade the soil.","translation":"过度放牧可能使土壤退化。","note":"degrade常及物，表示使质量降低；deteriorate更常描述主语自身恶化。改写需核对及物性和主宾语。","number":309,"resourceId":"doc-026-15-fe3ff84f1136","term":"degrade","originalPair":"degrade = deteriorate","needsCare":true,"sources":[{"title":"Merriam-Webster：degrade","url":"https://www.merriam-webster.com/dictionary/degrade"},{"title":"Merriam-Webster：deteriorate","url":"https://www.merriam-webster.com/dictionary/deteriorate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"310":{"sense":"v. 表示；指称","collocations":["denote a category","indicate a trend"],"example":"The dotted line denotes the proposed route.","translation":"虚线表示拟定路线。","note":"denote常指符号、词语代表什么；indicate也可指迹象显示某事，不一定涉及约定符号。","number":310,"resourceId":"doc-026-15-c9f47ca34014","term":"denote","originalPair":"denote = indicate","needsCare":false,"sources":[{"title":"Merriam-Webster：denote","url":"https://www.merriam-webster.com/dictionary/denote"},{"title":"Merriam-Webster：indicate","url":"https://www.merriam-webster.com/dictionary/indicate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"311":{"sense":"v. 消耗；使枯竭","collocations":["deplete reserves","exhaust supplies"],"example":"Overuse can deplete the region's groundwater reserves.","translation":"过度使用会耗竭该地区的地下水储备。","note":"deplete指显著减少，未必全部用完；exhaust更容易表达耗尽，程度需要核对。","number":311,"resourceId":"doc-026-15-73ea9d496598","term":"deplete","originalPair":"deplete = exhaust","needsCare":false,"sources":[{"title":"Merriam-Webster：deplete","url":"https://www.merriam-webster.com/dictionary/deplete"},{"title":"Merriam-Webster：exhaust","url":"https://www.merriam-webster.com/dictionary/exhaust"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"312":{"sense":"v. 描绘","collocations":["depict a scene","portray a character"],"example":"The mural depicts daily life along the river.","translation":"壁画描绘了河边的日常生活。","note":"depict可用于图画或文字；portray也可描述人物形象或演员扮演，不是所有义项相同。","number":312,"resourceId":"doc-026-15-42bb924b94ae","term":"depict","originalPair":"depict = portray","needsCare":false,"sources":[{"title":"Merriam-Webster：depict","url":"https://www.merriam-webster.com/dictionary/depict"},{"title":"Merriam-Webster：portray","url":"https://www.merriam-webster.com/dictionary/portray"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"313":{"sense":"adj. 荒凉的；凄凉的","collocations":["a desolate landscape","barren land"],"example":"The abandoned station stood in a desolate landscape.","translation":"废弃车站矗立在荒凉的景色中。","note":"desolate强调荒无人烟或令人凄凉；barren强调贫瘠、不结果实。荒凉地区未必没有植被。","number":313,"resourceId":"doc-026-15-0b37119f540c","term":"desolate","originalPair":"desolate = barren","needsCare":false,"sources":[{"title":"Merriam-Webster：desolate","url":"https://www.merriam-webster.com/dictionary/desolate"},{"title":"Merriam-Webster：barren","url":"https://www.merriam-webster.com/dictionary/barren"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"314":{"sense":"v. 察觉；检测到","collocations":["detect a fault","identify a cause"],"example":"The test can detect a leak before it becomes visible.","translation":"测试能在泄漏变得可见之前检测到它。","note":"detect是发现存在；identify常要辨明是什么或确认身份。检测到问题不等于已查明原因。","number":314,"resourceId":"doc-026-15-5585b69ea44d","term":"detect","originalPair":"detect = identify","needsCare":true,"sources":[{"title":"Merriam-Webster：detect","url":"https://www.merriam-webster.com/dictionary/detect"},{"title":"Merriam-Webster：identify","url":"https://www.merriam-webster.com/dictionary/identify"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"315":{"sense":"adj. 有害的","collocations":["detrimental to","harmful to"],"example":"Constant interruptions can be detrimental to learning.","translation":"不断被打断可能不利于学习。","note":"两词可表达造成损害，detrimental较正式；通常接to，不用detrimental for来照搬其他结构。","number":315,"resourceId":"doc-026-15-3e8cd9a7012e","term":"detrimental","originalPair":"detrimental = harmful","needsCare":true,"sources":[{"title":"Merriam-Webster：detrimental","url":"https://www.merriam-webster.com/dictionary/detrimental"},{"title":"Merriam-Webster：harmful","url":"https://www.merriam-webster.com/dictionary/harmful"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"316":{"sense":"v. 狼吞虎咽；如饥似渴地读","collocations":["devour a meal","consume energy"],"example":"After the long walk, the children devoured their lunch.","translation":"长途步行后，孩子们狼吞虎咽地吃午饭。","note":"devour常强调快速、急切或大量；consume泛指消耗或食用，不带相同生动语气。","number":316,"resourceId":"doc-026-15-b74dd4c33536","term":"devour","originalPair":"devour = consume","needsCare":false,"sources":[{"title":"Merriam-Webster：devour","url":"https://www.merriam-webster.com/dictionary/devour"},{"title":"Merriam-Webster：consume","url":"https://www.merriam-webster.com/dictionary/consume"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"317":{"sense":"v. 区分；使有差别","collocations":["differentiate between","distinguish A from B"],"example":"The chart differentiates between temporary and permanent jobs.","translation":"图表区分了临时和长期工作。","note":"两词在辨别差异时接近；differentiate还可表示使产品不同或数学求导，不能一概互换。","number":317,"resourceId":"doc-026-15-5441506bc811","term":"differentiate","originalPair":"differentiate = distinguish","needsCare":false,"sources":[{"title":"Merriam-Webster：differentiate","url":"https://www.merriam-webster.com/dictionary/differentiate"},{"title":"Merriam-Webster：distinguish","url":"https://www.merriam-webster.com/dictionary/distinguish"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"318":{"sense":"v. 减少；减弱","collocations":["diminish in importance","decrease by"],"example":"The importance of distance has diminished with better communication.","translation":"随着通信改善，距离的重要性减弱了。","note":"decrease更常用于数量或程度减少；diminish也常形容地位、重要性或能力减弱。","number":318,"resourceId":"doc-026-15-00f37672a924","term":"diminish","originalPair":"diminish = decrease","needsCare":false,"sources":[{"title":"Merriam-Webster：diminish","url":"https://www.merriam-webster.com/dictionary/diminish"},{"title":"Merriam-Webster：decrease","url":"https://www.merriam-webster.com/dictionary/decrease"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"319":{"sense":"n. 差异；不符","collocations":["a discrepancy between","an inconsistency in"],"example":"There is a discrepancy between the two sets of figures.","translation":"两套数字之间存在不符。","note":"discrepancy常指本应一致的信息有差异；inconsistency也可指前后矛盾或做法不一。","number":319,"resourceId":"doc-026-15-28a1a3680013","term":"discrepancy","originalPair":"discrepancy = inconsistency","needsCare":true,"sources":[{"title":"Merriam-Webster：discrepancy","url":"https://www.merriam-webster.com/dictionary/discrepancy"},{"title":"Merriam-Webster：inconsistency","url":"https://www.merriam-webster.com/dictionary/inconsistency"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"320":{"sense":"v. 分散；散开","collocations":["disperse a crowd","scatter seeds"],"example":"The crowd dispersed after the final announcement.","translation":"最后一次通知结束后，人群散开了。","note":"disperse可及物或不及物；scatter常强调四散分布。种子分散和人群解散的语境不同。","number":320,"resourceId":"doc-026-15-c8f7fa78c056","term":"disperse","originalPair":"disperse = scatter","needsCare":false,"sources":[{"title":"Merriam-Webster：disperse","url":"https://www.merriam-webster.com/dictionary/disperse"},{"title":"Merriam-Webster：scatter","url":"https://www.merriam-webster.com/dictionary/scatter"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"321":{"sense":"v. 扭曲；歪曲","collocations":["distort an image","twist the facts"],"example":"A damaged lens can distort the image.","translation":"受损镜片可能使图像失真。","note":"twist可指拧转或曲解；distort侧重形状或信息失真，不表示每种旋转动作。","number":321,"resourceId":"doc-026-15-e3187d9ae9e4","term":"distort","originalPair":"distort = twist","needsCare":false,"sources":[{"title":"Merriam-Webster：distort","url":"https://www.merriam-webster.com/dictionary/distort"},{"title":"Merriam-Webster：twist","url":"https://www.merriam-webster.com/dictionary/twist"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"322":{"sense":"adj. 分歧的；趋于不同的","collocations":["divergent views","different opinions"],"example":"The groups expressed divergent views on the proposal.","translation":"各小组对提案表达了不同意见。","note":"divergent强调向不同方向发展或观点分歧；different只是不同，不必含逐渐分开之意。","number":322,"resourceId":"doc-026-15-0b6c0d71e5d3","term":"divergent","originalPair":"divergent = different","needsCare":false,"sources":[{"title":"Merriam-Webster：divergent","url":"https://www.merriam-webster.com/dictionary/divergent"},{"title":"Merriam-Webster：different","url":"https://www.merriam-webster.com/dictionary/different"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"323":{"sense":"adj. 占主导的","collocations":["a dominant position","prevailing conditions"],"example":"Road transport remains dominant in the delivery sector.","translation":"公路运输在配送行业仍占主导地位。","note":"dominant强调控制或优势；prevailing指当时普遍存在或盛行，普遍不等于控制力强。","number":323,"resourceId":"doc-026-15-7809a4134493","term":"dominant","originalPair":"dominant = prevailing","needsCare":false,"sources":[{"title":"Merriam-Webster：dominant","url":"https://www.merriam-webster.com/dictionary/dominant"},{"title":"Merriam-Webster：prevailing","url":"https://www.merriam-webster.com/dictionary/prevailing"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"324":{"sense":"adj. 休眠的；暂不活跃的","collocations":["a dormant volcano","inactive accounts"],"example":"Some seeds remain dormant throughout the winter.","translation":"有些种子在整个冬季保持休眠。","note":"dormant常暗示暂时休眠、以后可能恢复；inactive更一般地指不活跃。","number":324,"resourceId":"doc-026-15-35e5bbdb6cbd","term":"dormant","originalPair":"dormant = inactive","needsCare":false,"sources":[{"title":"Merriam-Webster：dormant","url":"https://www.merriam-webster.com/dictionary/dormant"},{"title":"Merriam-Webster：inactive","url":"https://www.merriam-webster.com/dictionary/inactive"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"325":{"sense":"adj. 可疑的；拿不准的","collocations":["dubious about","doubtful whether"],"example":"Residents were dubious about the promised completion date.","translation":"居民对承诺的完工日期持怀疑态度。","note":"dubious还可评价事物不可靠或不正当；doubtful可指可能性不大，含义不完全重合。","number":325,"resourceId":"doc-026-15-5381486abd46","term":"dubious","originalPair":"dubious = doubtful","needsCare":false,"sources":[{"title":"Merriam-Webster：dubious","url":"https://www.merriam-webster.com/dictionary/dubious"},{"title":"Merriam-Webster：doubtful","url":"https://www.merriam-webster.com/dictionary/doubtful"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"326":{"sense":"n. 持续时间","collocations":["the duration of","the length of time"],"example":"Participants recorded the duration of each study session.","translation":"参与者记录了每次学习持续的时间。","note":"duration只谈持续时间；length还可指物理长度，不能把物体长度都换为duration。","number":326,"resourceId":"doc-026-15-39989e3e038e","term":"duration","originalPair":"duration = length","needsCare":false,"sources":[{"title":"Merriam-Webster：duration","url":"https://www.merriam-webster.com/dictionary/duration"},{"title":"Merriam-Webster：length","url":"https://www.merriam-webster.com/dictionary/length"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"327":{"sense":"v. 逐渐减少","collocations":["dwindle to","decline steadily"],"example":"Attendance dwindled as the evening became colder.","translation":"夜晚越来越冷，到场人数逐渐减少。","note":"dwindle强调逐渐变少，通常不及物；decline还可及物表示拒绝，不能覆盖所有义项。","number":327,"resourceId":"doc-026-15-884c834c58a7","term":"dwindle","originalPair":"dwindle = decline","needsCare":false,"sources":[{"title":"Merriam-Webster：dwindle","url":"https://www.merriam-webster.com/dictionary/dwindle"},{"title":"Merriam-Webster：decline","url":"https://www.merriam-webster.com/dictionary/decline"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"328":{"sense":"v. 引出；诱出","collocations":["elicit a response","evoke a memory"],"example":"Open questions can elicit detailed responses.","translation":"开放式问题可以引出详细回答。","note":"elicit常接回答、反应或信息；evoke常接情感、记忆或意象，不能一概互换。","number":328,"resourceId":"doc-026-15-09fb28607ca2","term":"elicit","originalPair":"elicit = evoke","needsCare":false,"sources":[{"title":"Merriam-Webster：elicit","url":"https://www.merriam-webster.com/dictionary/elicit"},{"title":"Merriam-Webster：evoke","url":"https://www.merriam-webster.com/dictionary/evoke"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"329":{"sense":"adj. 难找到的；难掌握的","collocations":["an elusive answer","an evasive reply"],"example":"A clear explanation for the pattern remains elusive.","translation":"对这一模式的清楚解释仍然难以找到。","note":"elusive指难以找到或理解；evasive强调回避、躲闪。难找到的答案不等于故意回避的回答。","number":329,"resourceId":"doc-026-16-0c5ff62059da","term":"elusive","originalPair":"elusive = evasive","needsCare":true,"sources":[{"title":"Merriam-Webster：elusive","url":"https://www.merriam-webster.com/dictionary/elusive"},{"title":"Merriam-Webster：evasive","url":"https://www.merriam-webster.com/dictionary/evasive"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"330":{"sense":"v. 体现；使具体化","collocations":["embody values","represent a group"],"example":"The building embodies the community's commitment to shared space.","translation":"这座建筑体现了社区对共享空间的重视。","note":"embody强调抽象特质得到具体体现；represent还可表示代表某个群体，不必体现其全部价值。","number":330,"resourceId":"doc-026-16-70f65b774c09","term":"embody","originalPair":"embody = represent","needsCare":false,"sources":[{"title":"Merriam-Webster：embody","url":"https://www.merriam-webster.com/dictionary/embody"},{"title":"Merriam-Webster：represent","url":"https://www.merriam-webster.com/dictionary/represent"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"331":{"sense":"v. 接受；欣然采纳","collocations":["embrace change","adopt a policy"],"example":"The school embraced a more flexible approach to assessment.","translation":"学校欣然采用了更灵活的评估方式。","note":"embrace常有积极接受的态度；adopt只是采用，还可指收养。不要把拥抱义改成adopt。","number":331,"resourceId":"doc-026-16-1d7587441732","term":"embrace","originalPair":"embrace = adopt","needsCare":false,"sources":[{"title":"Merriam-Webster：embrace","url":"https://www.merriam-webster.com/dictionary/embrace"},{"title":"Merriam-Webster：adopt","url":"https://www.merriam-webster.com/dictionary/adopt"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"332":{"sense":"adj. 杰出的；著名的","collocations":["an eminent scholar","a distinguished career"],"example":"An eminent scientist gave the opening lecture.","translation":"一位杰出的科学家作了开场讲座。","note":"两词都可表示因成就受尊敬；eminent不等于imminent（即将发生的），注意拼写。","number":332,"resourceId":"doc-026-16-93ce37b064c6","term":"eminent","originalPair":"eminent = distinguished","needsCare":false,"sources":[{"title":"Merriam-Webster：eminent","url":"https://www.merriam-webster.com/dictionary/eminent"},{"title":"Merriam-Webster：distinguished","url":"https://www.merriam-webster.com/dictionary/distinguished"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"333":{"sense":"v. 包含；涵盖","collocations":["encompass a range","include examples"],"example":"The course encompasses reading, writing and discussion.","translation":"课程涵盖阅读、写作和讨论。","note":"encompass常强调范围广、把相关部分纳入；include未必表示列举了全部内容。","number":333,"resourceId":"doc-026-16-f1e00b8e289b","term":"encompass","originalPair":"encompass = include","needsCare":false,"sources":[{"title":"Merriam-Webster：encompass","url":"https://www.merriam-webster.com/dictionary/encompass"},{"title":"Merriam-Webster：include","url":"https://www.merriam-webster.com/dictionary/include"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"334":{"sense":"v. 公开支持；认可","collocations":["endorse a proposal","support a policy"],"example":"The teachers' union endorsed the new training scheme.","translation":"教师工会公开支持了新的培训计划。","note":"endorse常指公开或正式认可；support还可指实际帮助或提供资金。","number":334,"resourceId":"doc-026-16-d24e3dba7b29","term":"endorse","originalPair":"endorse = support","needsCare":false,"sources":[{"title":"Merriam-Webster：endorse","url":"https://www.merriam-webster.com/dictionary/endorse"},{"title":"Merriam-Webster：support","url":"https://www.merriam-webster.com/dictionary/support"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"335":{"sense":"v. 使全神贯注","collocations":["be engrossed in","be absorbed in"],"example":"She was engrossed in a book about marine life.","translation":"她全神贯注地读一本海洋生物方面的书。","note":"两词在使专注义上接近，常用被动加in；absorb还可指吸收水分，engross不适用。","number":335,"resourceId":"doc-026-16-17b53a2ecd62","term":"engross","originalPair":"engross = absorb","needsCare":true,"sources":[{"title":"Merriam-Webster：engross","url":"https://www.merriam-webster.com/dictionary/engross"},{"title":"Merriam-Webster：absorb","url":"https://www.merriam-webster.com/dictionary/absorb"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"336":{"sense":"v. 提升；增强","collocations":["enhance understanding","improve performance"],"example":"The diagrams enhance readers' understanding of the process.","translation":"图示增进了读者对这一过程的理解。","note":"enhance常指使已有价值或效果更好；improve更常用，不能靠换成长词保证表达更准确。","number":336,"resourceId":"doc-026-16-545d5bc2eb45","term":"enhance","originalPair":"enhance = improve","needsCare":false,"sources":[{"title":"Merriam-Webster：enhance","url":"https://www.merriam-webster.com/dictionary/enhance"},{"title":"Merriam-Webster：improve","url":"https://www.merriam-webster.com/dictionary/improve"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"337":{"sense":"v. 想象；展望","collocations":["envision a future","imagine doing"],"example":"The planners envision a city with fewer private cars.","translation":"规划者设想了一座私家车更少的城市。","note":"envision常指设想未来情景；imagine使用范围更广。不要把imagine doing改成envision to do。","number":337,"resourceId":"doc-026-16-81a8add670e3","term":"envision","originalPair":"envision = imagine","needsCare":false,"sources":[{"title":"Merriam-Webster：envision","url":"https://www.merriam-webster.com/dictionary/envision"},{"title":"Merriam-Webster：imagine","url":"https://www.merriam-webster.com/dictionary/imagine"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"338":{"sense":"v. 根除；彻底消除","collocations":["eradicate a disease","eliminate an error"],"example":"The campaign aims to eradicate the disease locally.","translation":"这项行动旨在当地根除这种疾病。","note":"eradicate强调连根清除；eliminate还可表示淘汰或排除，不一定对应根除疾病。","number":338,"resourceId":"doc-026-16-39ff16824266","term":"eradicate","originalPair":"eradicate = eliminate","needsCare":false,"sources":[{"title":"Merriam-Webster：eradicate","url":"https://www.merriam-webster.com/dictionary/eradicate"},{"title":"Merriam-Webster：eliminate","url":"https://www.merriam-webster.com/dictionary/eliminate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"339":{"sense":"adj. 不规则的；不稳定的","collocations":["erratic behaviour","unpredictable demand"],"example":"Erratic rainfall makes farming difficult in this region.","translation":"降雨不规律给该地区的农业带来困难。","note":"erratic常强调变化无常或偏离规律；unpredictable指难预测，难预测不一定不规则。","number":339,"resourceId":"doc-026-16-1f79242aed0c","term":"erratic","originalPair":"erratic = unpredictable","needsCare":true,"sources":[{"title":"Merriam-Webster：erratic","url":"https://www.merriam-webster.com/dictionary/erratic"},{"title":"Merriam-Webster：unpredictable","url":"https://www.merriam-webster.com/dictionary/unpredictable"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"340":{"sense":"v. 唤起","collocations":["evoke memories","elicit information"],"example":"The smell of bread evokes memories of my childhood.","translation":"面包的气味唤起了我童年的回忆。","note":"evoke常指唤起记忆或感受；elicit常指通过提问等引出回答或反应。","number":340,"resourceId":"doc-026-16-9db33d3fff93","term":"evoke","originalPair":"evoke = elicit","needsCare":false,"sources":[{"title":"Merriam-Webster：evoke","url":"https://www.merriam-webster.com/dictionary/evoke"},{"title":"Merriam-Webster：elicit","url":"https://www.merriam-webster.com/dictionary/elicit"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"341":{"sense":"v. 擅长；胜过","collocations":["excel at","excel in"],"example":"She excels at explaining complex ideas simply.","translation":"她擅长用简单方式解释复杂想法。","note":"excel常接at/in说明擅长领域；surpass通常直接接超过的对象，不可漏掉结构差异。","number":341,"resourceId":"doc-026-16-94b4647099b1","term":"excel","originalPair":"excel = surpass","needsCare":true,"sources":[{"title":"Merriam-Webster：excel","url":"https://www.merriam-webster.com/dictionary/excel"},{"title":"Merriam-Webster：surpass","url":"https://www.merriam-webster.com/dictionary/surpass"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"342":{"sense":"v. 举例说明；作为典型","collocations":["exemplify a trend","illustrate a point"],"example":"This case exemplifies the difficulties faced by small firms.","translation":"这个案例体现了小企业面临的困难。","note":"exemplify可指本身就是典型；illustrate还可用图画或例子解释，不一定本身是典型。","number":342,"resourceId":"doc-026-16-d13331f9518e","term":"exemplify","originalPair":"exemplify = illustrate","needsCare":false,"sources":[{"title":"Merriam-Webster：exemplify","url":"https://www.merriam-webster.com/dictionary/exemplify"},{"title":"Merriam-Webster：illustrate","url":"https://www.merriam-webster.com/dictionary/illustrate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"343":{"sense":"v. 利用；剥削","collocations":["exploit an opportunity","utilize a tool"],"example":"The firm was accused of exploiting temporary workers.","translation":"这家公司被指控剥削临时工。","note":"exploit在此带负面意义；utilize不表示剥削。利用机会的义项才可能较接近。","number":343,"resourceId":"doc-026-16-1259fb4ea171","term":"exploit","originalPair":"exploit = utilize","needsCare":false,"sources":[{"title":"Merriam-Webster：exploit","url":"https://www.merriam-webster.com/dictionary/exploit"},{"title":"Merriam-Webster：utilize","url":"https://www.merriam-webster.com/dictionary/utilize"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"344":{"sense":"v. 波动","collocations":["fluctuate between","vary by"],"example":"Electricity demand fluctuates throughout the day.","translation":"用电需求在一天中不断波动。","note":"fluctuate强调上下变化，通常不及物；vary可表示不同对象之间有差异，也可及物。","number":344,"resourceId":"doc-026-16-8a9733f85b25","term":"fluctuate","originalPair":"fluctuate = vary","needsCare":false,"sources":[{"title":"Merriam-Webster：fluctuate","url":"https://www.merriam-webster.com/dictionary/fluctuate"},{"title":"Merriam-Webster：vary","url":"https://www.merriam-webster.com/dictionary/vary"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"345":{"sense":"v. 预见","collocations":["foresee a problem","predict an outcome"],"example":"Few planners foresaw such a rapid increase in demand.","translation":"很少有规划者预见到需求增长如此迅速。","note":"foresee强调预先看出；predict强调作出预测，两者不保证预测准确，也未必使用同一方法。","number":345,"resourceId":"doc-026-16-36c85c911718","term":"foresee","originalPair":"foresee = predict","needsCare":false,"sources":[{"title":"Merriam-Webster：foresee","url":"https://www.merriam-webster.com/dictionary/foresee"},{"title":"Merriam-Webster：predict","url":"https://www.merriam-webster.com/dictionary/predict"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"346":{"sense":"adj. 令人敬畏的；难对付的","collocations":["a formidable opponent","an impressive achievement"],"example":"The researcher has a formidable knowledge of local history.","translation":"这位研究者的地方历史知识令人敬佩。","note":"impressive对应给人深刻印象的方面；formidable也可强调令人畏惧、难克服，并不总是赞美。","number":346,"resourceId":"doc-026-16-65755c3c8612","term":"formidable","originalPair":"formidable = impressive","needsCare":true,"sources":[{"title":"Merriam-Webster：formidable","url":"https://www.merriam-webster.com/dictionary/formidable"},{"title":"Merriam-Webster：impressive","url":"https://www.merriam-webster.com/dictionary/impressive"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"347":{"sense":"v. 促进；培养","collocations":["foster trust","promote cooperation"],"example":"Open meetings can foster trust between staff and students.","translation":"公开会议能够增进师生之间的信任。","note":"promote也可指促进，但还可指晋升或推销；foster在此强调形成信任的有利条件。","number":347,"resourceId":"doc-026-16-2d3cf4c60552","term":"foster","originalPair":"foster = promote","needsCare":false,"sources":[{"title":"Merriam-Webster：foster","url":"https://www.merriam-webster.com/dictionary/foster"},{"title":"Merriam-Webster：promote","url":"https://www.merriam-webster.com/dictionary/promote"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"348":{"sense":"n. 碎片；片段","collocations":["a fragment of","a piece of"],"example":"The archaeologists found a fragment of decorated pottery.","translation":"考古人员找到了一块有装饰的陶器碎片。","note":"fragment通常指从较大整体分离的一小部分；piece更一般，未必是破碎后形成。","number":348,"resourceId":"doc-026-16-b6da55a75c04","term":"fragment","originalPair":"fragment = piece","needsCare":false,"sources":[{"title":"Merriam-Webster：fragment","url":"https://www.merriam-webster.com/dictionary/fragment"},{"title":"Merriam-Webster：piece","url":"https://www.merriam-webster.com/dictionary/piece"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"349":{"sense":"adj. 徒劳的","collocations":["a futile effort","a useless object"],"example":"Arguing without listening is usually futile.","translation":"不听对方意见就争论，通常是徒劳的。","note":"futile强调行动不能达到目的；useless可指物品无用，不是所有无用物品都属于徒劳行动。","number":349,"resourceId":"doc-026-16-52777d5fd314","term":"futile","originalPair":"futile = useless","needsCare":false,"sources":[{"title":"Merriam-Webster：futile","url":"https://www.merriam-webster.com/dictionary/futile"},{"title":"Merriam-Webster：useless","url":"https://www.merriam-webster.com/dictionary/useless"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"350":{"sense":"v. 产生","collocations":["generate income","produce electricity"],"example":"The new centre could generate income for local businesses.","translation":"新中心可能为当地企业带来收入。","note":"generate常指引发或产生收益、能量等；produce还可指制造实物，搭配需逐项核对。","number":350,"resourceId":"doc-026-16-37ed85cbf44c","term":"generate","originalPair":"generate = produce","needsCare":false,"sources":[{"title":"Merriam-Webster：generate","url":"https://www.merriam-webster.com/dictionary/generate"},{"title":"Merriam-Webster：produce","url":"https://www.merriam-webster.com/dictionary/produce"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"351":{"sense":"v. 理解；掌握","collocations":["grasp the meaning","understand a concept"],"example":"Readers may need an example to grasp the main idea.","translation":"读者可能需要一个例子才能理解主旨。","note":"understand对应理解义；grasp还可指抓住物体，不能一概替换。理解也不等于熟练使用。","number":351,"resourceId":"doc-026-17-d8277bf381b5","term":"grasp","originalPair":"grasp = understand","needsCare":false,"sources":[{"title":"Merriam-Webster：grasp","url":"https://www.merriam-webster.com/dictionary/grasp"},{"title":"Merriam-Webster：understand","url":"https://www.merriam-webster.com/dictionary/understand"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"352":{"sense":"v. 阻碍","collocations":["hamper efforts","hinder progress"],"example":"Missing records hampered the investigation.","translation":"记录缺失妨碍了调查。","note":"两词都表示使行动更困难；hamper常带受限制、被牵制的意味，不等于完全阻止。","number":352,"resourceId":"doc-026-17-614b6720ab46","term":"hamper","originalPair":"hamper = hinder","needsCare":false,"sources":[{"title":"Merriam-Webster：hamper","url":"https://www.merriam-webster.com/dictionary/hamper"},{"title":"Merriam-Webster：hinder","url":"https://www.merriam-webster.com/dictionary/hinder"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"353":{"sense":"v. 协调；使一致","collocations":["harmonize standards","coordinate activities"],"example":"The regions agreed to harmonize their safety standards.","translation":"各地区同意协调统一安全标准。","note":"harmonize强调消除差异、使协调一致；coordinate强调组织安排彼此配合，未必统一标准。","number":353,"resourceId":"doc-026-17-404f9321b7ac","term":"harmonize","originalPair":"harmonize = coordinate","needsCare":false,"sources":[{"title":"Merriam-Webster：harmonize","url":"https://www.merriam-webster.com/dictionary/harmonize"},{"title":"Merriam-Webster：coordinate","url":"https://www.merriam-webster.com/dictionary/coordinate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"354":{"sense":"n. 严重破坏；混乱","collocations":["wreak havoc on","cause chaos"],"example":"The storm wreaked havoc on the coastal transport network.","translation":"暴风雨严重破坏了沿海交通网络。","note":"havoc常包含大范围损害；chaos强调无序。常用wreak havoc，不用把havoc当可数名词加a。","number":354,"resourceId":"doc-026-17-fb3dd743d7e6","term":"havoc","originalPair":"havoc = chaos","needsCare":true,"sources":[{"title":"Merriam-Webster：havoc","url":"https://www.merriam-webster.com/dictionary/havoc"},{"title":"Merriam-Webster：chaos","url":"https://www.merriam-webster.com/dictionary/chaos"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"355":{"sense":"v. 阻碍","collocations":["hinder progress","impede access"],"example":"Limited internet access can hinder students' progress.","translation":"上网条件有限可能阻碍学生进步。","note":"impede也指妨碍进展，语气较正式；两词可接过程或行动，不表示完全使其不可能。","number":355,"resourceId":"doc-026-17-c310a5494d37","term":"hinder","originalPair":"hinder = impede","needsCare":false,"sources":[{"title":"Merriam-Webster：hinder","url":"https://www.merriam-webster.com/dictionary/hinder"},{"title":"Merriam-Webster：impede","url":"https://www.merriam-webster.com/dictionary/impede"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"356":{"sense":"adj. 整体性的","collocations":["a holistic approach","a comprehensive review"],"example":"The clinic takes a holistic approach to patient care.","translation":"诊所从整体角度照顾患者。","note":"holistic强调各部分相互联系及整体作用；comprehensive强调覆盖全面，列得全不等于从整体关系出发。","number":356,"resourceId":"doc-026-17-7e21fc0e203d","term":"holistic","originalPair":"holistic = comprehensive","needsCare":true,"sources":[{"title":"Merriam-Webster：holistic","url":"https://www.merriam-webster.com/dictionary/holistic"},{"title":"Merriam-Webster：comprehensive","url":"https://www.merriam-webster.com/dictionary/comprehensive"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"357":{"sense":"v. 照亮；阐明","collocations":["illuminate an issue","clarify a point"],"example":"The interviews illuminate the reasons behind the policy change.","translation":"访谈有助于阐明政策变化背后的原因。","note":"clarify对应澄清义；illuminate还可物理照亮。阐明问题不自动等于已解决问题。","number":357,"resourceId":"doc-026-17-5ab8aab959af","term":"illuminate","originalPair":"illuminate = clarify","needsCare":false,"sources":[{"title":"Merriam-Webster：illuminate","url":"https://www.merriam-webster.com/dictionary/illuminate"},{"title":"Merriam-Webster：clarify","url":"https://www.merriam-webster.com/dictionary/clarify"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"358":{"sense":"adj. 巨大的","collocations":["immense pressure","an enormous amount"],"example":"The restoration project required immense patience.","translation":"修复项目需要极大的耐心。","note":"两词都可强调量或程度很大；immense patience等搭配更自然，不能只按大小机械替换。","number":358,"resourceId":"doc-026-17-dfbd7c491044","term":"immense","originalPair":"immense = enormous","needsCare":false,"sources":[{"title":"Merriam-Webster：immense","url":"https://www.merriam-webster.com/dictionary/immense"},{"title":"Merriam-Webster：enormous","url":"https://www.merriam-webster.com/dictionary/enormous"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"359":{"sense":"v. 损害；削弱功能","collocations":["impair memory","damage a building"],"example":"Lack of sleep can impair concentration.","translation":"睡眠不足可能损害专注力。","note":"impair常强调功能或能力受损；damage范围更广。","number":359,"resourceId":"doc-026-17-9db2d69206e7","term":"impair","originalPair":"impair = damage","needsCare":false,"sources":[{"title":"Merriam-Webster：impair","url":"https://www.merriam-webster.com/dictionary/impair"},{"title":"Merriam-Webster：damage","url":"https://www.merriam-webster.com/dictionary/damage"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"360":{"sense":"adj. 必要的；迫切的","collocations":["it is imperative to","essential to"],"example":"It is imperative to repair the damaged barrier before reopening.","translation":"重新开放前必须修好受损的护栏。","note":"imperative常带迫切、必须执行的意味；essential强调不可缺少，不一定带相同紧迫感。","number":360,"resourceId":"doc-026-17-1272d99e6e20","term":"imperative","originalPair":"imperative = essential","needsCare":true,"sources":[{"title":"Merriam-Webster：imperative","url":"https://www.merriam-webster.com/dictionary/imperative"},{"title":"Merriam-Webster：essential","url":"https://www.merriam-webster.com/dictionary/essential"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"361":{"sense":"v. 实施；执行","collocations":["implement a policy","execute a plan"],"example":"The school will implement the new policy in September.","translation":"学校将于九月实施新政策。","note":"execute可指执行计划，也有处决等义项；此处只比较实施计划的义项。","number":361,"resourceId":"doc-026-17-e10ea2dbc9a1","term":"implement","originalPair":"implement = execute","needsCare":false,"sources":[{"title":"Merriam-Webster：implement","url":"https://www.merriam-webster.com/dictionary/implement"},{"title":"Merriam-Webster：execute","url":"https://www.merriam-webster.com/dictionary/execute"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"362":{"sense":"v. 暗示；意味着","collocations":["imply that","suggest that"],"example":"A higher price does not necessarily imply better quality.","translation":"价格更高不一定意味着质量更好。","note":"imply是信息暗含；suggest还可表示提出建议。两者都不能单凭暗示当作证明。","number":362,"resourceId":"doc-026-17-40490c62c8fb","term":"imply","originalPair":"imply = suggest","needsCare":true,"sources":[{"title":"Merriam-Webster：imply","url":"https://www.merriam-webster.com/dictionary/imply"},{"title":"Merriam-Webster：suggest","url":"https://www.merriam-webster.com/dictionary/suggest"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"363":{"sense":"v. 正式启用；开创","collocations":["inaugurate a service","initiate a project"],"example":"The city inaugurated a new tram service in spring.","translation":"城市在春季正式开通了新的有轨电车服务。","note":"inaugurate常带正式开幕、就职或启用意味；initiate只强调启动，未必有正式仪式。","number":363,"resourceId":"doc-026-17-924427a7a35e","term":"inaugurate","originalPair":"inaugurate = initiate","needsCare":true,"sources":[{"title":"Merriam-Webster：inaugurate","url":"https://www.merriam-webster.com/dictionary/inaugurate"},{"title":"Merriam-Webster：initiate","url":"https://www.merriam-webster.com/dictionary/initiate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"364":{"sense":"n. 激励因素","collocations":["an incentive to do","motivation for"],"example":"A small grant gave residents an incentive to insulate their homes.","translation":"一小笔补助激励居民给住宅加装保温层。","note":"incentive常指外部奖励或刺激；motivation可指内在动力，不是所有动力都来自奖励。","number":364,"resourceId":"doc-026-17-4ffe15bb6654","term":"incentive","originalPair":"incentive = motivation","needsCare":false,"sources":[{"title":"Merriam-Webster：incentive","url":"https://www.merriam-webster.com/dictionary/incentive"},{"title":"Merriam-Webster：motivation","url":"https://www.merriam-webster.com/dictionary/motivation"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"365":{"sense":"n. 倾向；意愿","collocations":["an inclination to do","a tendency to do"],"example":"Some learners have an inclination to translate every word.","translation":"一些学习者倾向于逐字翻译。","note":"inclination可表示个人意愿或偏好；tendency也可描述客观事物的趋势，未必涉及意愿。","number":365,"resourceId":"doc-026-17-5a4fa9e4590c","term":"inclination","originalPair":"inclination = tendency","needsCare":false,"sources":[{"title":"Merriam-Webster：inclination","url":"https://www.merriam-webster.com/dictionary/inclination"},{"title":"Merriam-Webster：tendency","url":"https://www.merriam-webster.com/dictionary/tendency"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"366":{"sense":"v. 纳入；并入","collocations":["incorporate into","integrate into"],"example":"The revised course incorporates feedback from students.","translation":"修改后的课程纳入了学生的反馈。","note":"incorporate强调将某部分纳入；integrate强调结合成协调的整体，不一定涉及同样的修改方式。","number":366,"resourceId":"doc-026-17-275386ac6c9f","term":"incorporate","originalPair":"incorporate = integrate","needsCare":false,"sources":[{"title":"Merriam-Webster：incorporate","url":"https://www.merriam-webster.com/dictionary/incorporate"},{"title":"Merriam-Webster：integrate","url":"https://www.merriam-webster.com/dictionary/integrate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"367":{"sense":"v. 引起；促使","collocations":["induce someone to do","prompt someone to do"],"example":"Lower fees may induce more adults to return to education.","translation":"较低费用可能促使更多成年人重返校园。","note":"两词可表示促使采取行动；induce还有诱发疾病或催眠等义项，不能都用prompt。","number":367,"resourceId":"doc-026-17-8869ce70579f","term":"induce","originalPair":"induce = prompt","needsCare":false,"sources":[{"title":"Merriam-Webster：induce","url":"https://www.merriam-webster.com/dictionary/induce"},{"title":"Merriam-Webster：prompt","url":"https://www.merriam-webster.com/dictionary/prompt"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"368":{"sense":"v. 推断","collocations":["infer from","deduce from"],"example":"We should not infer a general trend from one response.","translation":"我们不应根据一个回答推断整体趋势。","note":"infer是读者或观察者得出结论；imply是信息或说话者暗示。deduce强调推理依据。","number":368,"resourceId":"doc-026-17-5be684481d32","term":"infer","originalPair":"infer = deduce","needsCare":false,"sources":[{"title":"Merriam-Webster：infer","url":"https://www.merriam-webster.com/dictionary/infer"},{"title":"Merriam-Webster：deduce","url":"https://www.merriam-webster.com/dictionary/deduce"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"369":{"sense":"adj. 巧妙的；机巧的","collocations":["an ingenious device","a clever solution"],"example":"The students built an ingenious device from reused materials.","translation":"学生用再利用材料制作了一个巧妙的装置。","note":"ingenious强调设计或构思有创造性的巧妙；clever更宽泛。不要与表示天真的ingenuous混淆。","number":369,"resourceId":"doc-026-17-2b532db11f10","term":"ingenious","originalPair":"ingenious = clever","needsCare":false,"sources":[{"title":"Merriam-Webster：ingenious","url":"https://www.merriam-webster.com/dictionary/ingenious"},{"title":"Merriam-Webster：clever","url":"https://www.merriam-webster.com/dictionary/clever"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"370":{"sense":"adj. 内在的；固有的","collocations":["inherent in","intrinsic to"],"example":"Some uncertainty is inherent in long-term forecasting.","translation":"长期预测本身就存在一定不确定性。","note":"两词都可表示内在属性；常见介词分别有inherent in与intrinsic to，不能漏掉介词。","number":370,"resourceId":"doc-026-17-410aa3a49884","term":"inherent","originalPair":"inherent = intrinsic","needsCare":false,"sources":[{"title":"Merriam-Webster：inherent","url":"https://www.merriam-webster.com/dictionary/inherent"},{"title":"Merriam-Webster：intrinsic","url":"https://www.merriam-webster.com/dictionary/intrinsic"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"371":{"sense":"v. 抑制；妨碍","collocations":["inhibit growth","restrain spending"],"example":"Poor lighting can inhibit plant growth.","translation":"光线不足会抑制植物生长。","note":"inhibit可指阻碍过程或心理上的抑制；restrain更常指约束行为、情绪或身体动作。","number":371,"resourceId":"doc-026-17-c204fbc402e8","term":"inhibit","originalPair":"inhibit = restrain","needsCare":false,"sources":[{"title":"Merriam-Webster：inhibit","url":"https://www.merriam-webster.com/dictionary/inhibit"},{"title":"Merriam-Webster：restrain","url":"https://www.merriam-webster.com/dictionary/restrain"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"372":{"sense":"v. 创新","collocations":["innovate in","introduce a method"],"example":"The company continues to innovate in water-saving technology.","translation":"公司持续在节水技术方面创新。","note":"introduce要说明引入什么，也可只是首次在当地使用既有方法；innovate强调创新，通常不及物。","number":372,"resourceId":"doc-026-17-428ae1c96154","term":"innovate","originalPair":"innovate = introduce","needsCare":true,"sources":[{"title":"Merriam-Webster：innovate","url":"https://www.merriam-webster.com/dictionary/innovate"},{"title":"Merriam-Webster：introduce","url":"https://www.merriam-webster.com/dictionary/introduce"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"373":{"sense":"n. 意见；投入；输入","collocations":["input from","a contribution to"],"example":"The design team welcomed input from local residents.","translation":"设计团队欢迎当地居民提出意见。","note":"input可指意见、资源投入或计算机输入；contribution范围更广，不能覆盖所有技术输入义。","number":373,"resourceId":"doc-026-18-888128f0f075","term":"input","originalPair":"input = contribution","needsCare":false,"sources":[{"title":"Merriam-Webster：input","url":"https://www.merriam-webster.com/dictionary/input"},{"title":"Merriam-Webster：contribution","url":"https://www.merriam-webster.com/dictionary/contribution"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"374":{"sense":"n. 洞察；深入理解","collocations":["insight into","an understanding of"],"example":"The interviews provided insight into students' daily challenges.","translation":"访谈让人更深入地了解学生日常面临的困难。","note":"insight常强调新颖或深入的认识；understanding较宽泛，通常用of连接所理解的对象。","number":374,"resourceId":"doc-026-18-7b966409c46e","term":"insight","originalPair":"insight = understanding","needsCare":false,"sources":[{"title":"Merriam-Webster：insight","url":"https://www.merriam-webster.com/dictionary/insight"},{"title":"Merriam-Webster：understanding","url":"https://www.merriam-webster.com/dictionary/understanding"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"375":{"sense":"v. 整合；使融入","collocations":["integrate into","combine with"],"example":"The course integrates practical work with classroom discussion.","translation":"课程把实践工作与课堂讨论结合起来。","note":"integrate强调形成协调整体；combine可只是放在一起，未必实现深入整合。","number":375,"resourceId":"doc-026-18-cc4eb2a3fd8e","term":"integrate","originalPair":"integrate = combine","needsCare":false,"sources":[{"title":"Merriam-Webster：integrate","url":"https://www.merriam-webster.com/dictionary/integrate"},{"title":"Merriam-Webster：combine","url":"https://www.merriam-webster.com/dictionary/combine"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"376":{"sense":"v. 解释；理解为；口译","collocations":["interpret as","explain a result"],"example":"Different readers may interpret the same graph differently.","translation":"不同读者可能对同一张图作出不同解读。","note":"interpret可指赋予某种解释或口译；explain重在使人理解，不能覆盖全部口译义。","number":376,"resourceId":"doc-026-18-e8e7dc34a509","term":"interpret","originalPair":"interpret = explain","needsCare":false,"sources":[{"title":"Merriam-Webster：interpret","url":"https://www.merriam-webster.com/dictionary/interpret"},{"title":"Merriam-Webster：explain","url":"https://www.merriam-webster.com/dictionary/explain"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"377":{"sense":"v. 介入；干预","collocations":["intervene in","interfere with"],"example":"A mediator intervened to prevent the dispute from escalating.","translation":"调解员介入，防止争端升级。","note":"intervene可中性或积极；interfere常含不必要干扰的负面意味，不能无视态度差异。","number":377,"resourceId":"doc-026-18-024cc0ac8120","term":"intervene","originalPair":"intervene = interfere","needsCare":true,"sources":[{"title":"Merriam-Webster：intervene","url":"https://www.merriam-webster.com/dictionary/intervene"},{"title":"Merriam-Webster：interfere","url":"https://www.merriam-webster.com/dictionary/interfere"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"378":{"sense":"adj. 错综复杂的","collocations":["intricate details","a complex system"],"example":"The map shows an intricate network of narrow streets.","translation":"地图显示了一套错综复杂的狭窄街道网络。","note":"intricate强调细节交织精密；complex泛指组成或理解困难，侧重点不同。","number":378,"resourceId":"doc-026-18-2b39f2b7f43d","term":"intricate","originalPair":"intricate = complex","needsCare":false,"sources":[{"title":"Merriam-Webster：intricate","url":"https://www.merriam-webster.com/dictionary/intricate"},{"title":"Merriam-Webster：complex","url":"https://www.merriam-webster.com/dictionary/complex"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"379":{"sense":"adj. 内在的；本质的","collocations":["intrinsic to","intrinsic value"],"example":"Curiosity is intrinsic to meaningful scientific inquiry.","translation":"好奇心是有意义的科学探究所固有的。","note":"inherent也可表示内在固有；常见搭配intrinsic to与inherent in，替换时调整介词。","number":379,"resourceId":"doc-026-18-888ead34aaba","term":"intrinsic","originalPair":"intrinsic = inherent","needsCare":false,"sources":[{"title":"Merriam-Webster：intrinsic","url":"https://www.merriam-webster.com/dictionary/intrinsic"},{"title":"Merriam-Webster：inherent","url":"https://www.merriam-webster.com/dictionary/inherent"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"380":{"sense":"v. 调查","collocations":["investigate a cause","examine records"],"example":"The agency is investigating the cause of the service failure.","translation":"机构正在调查服务故障的原因。","note":"investigate强调为查明事实进行系统调查；examine可只是检查某项资料或对象。","number":380,"resourceId":"doc-026-18-f09ce500b8a2","term":"investigate","originalPair":"investigate = examine","needsCare":false,"sources":[{"title":"Merriam-Webster：investigate","url":"https://www.merriam-webster.com/dictionary/investigate"},{"title":"Merriam-Webster：examine","url":"https://www.merriam-webster.com/dictionary/examine"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"381":{"sense":"v. 隔离；使单独","collocations":["isolate from","separate from"],"example":"Researchers isolated one variable to test its effect.","translation":"研究人员单独控制一个变量来测试其影响。","note":"isolate强调使其与其他部分分离，便于控制或防护；separate更宽泛，不必形成隔离状态。","number":381,"resourceId":"doc-026-18-8369cf884817","term":"isolate","originalPair":"isolate = separate","needsCare":false,"sources":[{"title":"Merriam-Webster：isolate","url":"https://www.merriam-webster.com/dictionary/isolate"},{"title":"Merriam-Webster：separate","url":"https://www.merriam-webster.com/dictionary/separate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"382":{"sense":"v. 危及","collocations":["jeopardize safety","endanger wildlife"],"example":"Ignoring maintenance could jeopardize passenger safety.","translation":"忽视维护可能危及乘客安全。","note":"两词在使某事面临危险时接近；jeopardize常用于机会、计划或安全，不等于已经造成损失。","number":382,"resourceId":"doc-026-18-bdddde734d4c","term":"jeopardize","originalPair":"jeopardize = endanger","needsCare":false,"sources":[{"title":"Merriam-Webster：jeopardize","url":"https://www.merriam-webster.com/dictionary/jeopardize"},{"title":"Merriam-Webster：endanger","url":"https://www.merriam-webster.com/dictionary/endanger"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"383":{"sense":"v. 证明合理；为……辩护","collocations":["justify a decision","warrant action"],"example":"The report does not justify the proposed increase in fees.","translation":"报告不足以证明拟议的费用上涨合理。","note":"justify可指给出理由或辩护；warrant常指事实本身足以成为理由。辩护并不自动表示理由成立。","number":383,"resourceId":"doc-026-18-82f400b06db0","term":"justify","originalPair":"justify = warrant","needsCare":false,"sources":[{"title":"Merriam-Webster：justify","url":"https://www.merriam-webster.com/dictionary/justify"},{"title":"Merriam-Webster：warrant","url":"https://www.merriam-webster.com/dictionary/warrant"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"384":{"sense":"v. 悲叹；惋惜","collocations":["lament the loss of","mourn a death"],"example":"Residents lamented the loss of the old cinema.","translation":"居民为老电影院的消失感到惋惜。","note":"lament可哀叹或抱怨损失；mourn常指哀悼逝者或为损失悲痛，语气和对象要匹配。","number":384,"resourceId":"doc-026-18-196ab2094688","term":"lament","originalPair":"lament = mourn","needsCare":false,"sources":[{"title":"Merriam-Webster：lament","url":"https://www.merriam-webster.com/dictionary/lament"},{"title":"Merriam-Webster：mourn","url":"https://www.merriam-webster.com/dictionary/mourn"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"385":{"sense":"v. 借助……取得优势","collocations":["leverage expertise","utilize resources"],"example":"The partnership leverages local expertise to improve the course.","translation":"合作项目借助本地专长改进课程。","note":"leverage强调利用优势或资源取得更大效果；utilize只是利用。普通表达用use往往更清楚。","number":385,"resourceId":"doc-026-18-4af806995b53","term":"leverage","originalPair":"leverage = utilize","needsCare":true,"sources":[{"title":"Merriam-Webster：leverage","url":"https://www.merriam-webster.com/dictionary/leverage"},{"title":"Merriam-Webster：utilize","url":"https://www.merriam-webster.com/dictionary/utilize"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"386":{"sense":"v. 厌恶；憎恶","collocations":["loathe doing","detest doing"],"example":"She loathes wasting time on repetitive paperwork.","translation":"她厌恶在重复的文书工作上浪费时间。","note":"两词都比dislike强，适合强烈厌恶；正式论证中不应无意把一般不喜欢升级为憎恶。","number":386,"resourceId":"doc-026-18-d2039aef8521","term":"loathe","originalPair":"loathe = detest","needsCare":false,"sources":[{"title":"Merriam-Webster：loathe","url":"https://www.merriam-webster.com/dictionary/loathe"},{"title":"Merriam-Webster：detest","url":"https://www.merriam-webster.com/dictionary/detest"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"387":{"sense":"v. 放大","collocations":["magnify an image","amplify a signal"],"example":"The lens can magnify tiny details on the surface.","translation":"镜片能够放大表面的微小细节。","note":"magnify常指视觉放大，也可夸大问题；amplify常指声音或信号增强，不适用于所有镜片语境。","number":387,"resourceId":"doc-026-18-bd907349e70a","term":"magnify","originalPair":"magnify = amplify","needsCare":false,"sources":[{"title":"Merriam-Webster：magnify","url":"https://www.merriam-webster.com/dictionary/magnify"},{"title":"Merriam-Webster：amplify","url":"https://www.merriam-webster.com/dictionary/amplify"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"388":{"sense":"v. 操作；操纵","collocations":["manipulate a device","handle equipment"],"example":"The robot can manipulate small components accurately.","translation":"机器人能够精确操作小型零件。","note":"handle可指拿取、处理或应对；manipulate强调有技巧地操作，也可带不当操纵义。","number":388,"resourceId":"doc-026-18-660e19b9a9b0","term":"manipulate","originalPair":"manipulate = handle","needsCare":true,"sources":[{"title":"Merriam-Webster：manipulate","url":"https://www.merriam-webster.com/dictionary/manipulate"},{"title":"Merriam-Webster：handle","url":"https://www.merriam-webster.com/dictionary/handle"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"389":{"sense":"v. 使最大化","collocations":["maximize capacity","optimize a process"],"example":"The layout maximizes the number of seats in the room.","translation":"这一布局使房间的座位数达到最大。","note":"maximize追求某个量最大；optimize追求最佳效果。座位最多未必兼顾舒适和安全。","number":389,"resourceId":"doc-026-18-40659b929568","term":"maximize","originalPair":"maximize = optimize","needsCare":true,"sources":[{"title":"Merriam-Webster：maximize","url":"https://www.merriam-webster.com/dictionary/maximize"},{"title":"Merriam-Webster：optimize","url":"https://www.merriam-webster.com/dictionary/optimize"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"390":{"sense":"v. 合并；汇入","collocations":["merge into","combine resources"],"example":"The two paths merge into a single route near the gate.","translation":"两条小路在门附近汇成一条。","note":"merge强调逐渐或最终融为一体；combine可只是组合资源或部件，未必无法区分原部分。","number":390,"resourceId":"doc-026-18-f946d8464627","term":"merge","originalPair":"merge = combine","needsCare":false,"sources":[{"title":"Merriam-Webster：merge","url":"https://www.merriam-webster.com/dictionary/merge"},{"title":"Merriam-Webster：combine","url":"https://www.merriam-webster.com/dictionary/combine"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"391":{"sense":"v. 模仿","collocations":["mimic a sound","imitate behaviour"],"example":"The training device mimics the movement of a human hand.","translation":"训练设备模仿人手的运动。","note":"mimic常强调外形、声音或动作相似，也可能带逗趣意味；imitate更一般。","number":391,"resourceId":"doc-026-18-73ef464571bd","term":"mimic","originalPair":"mimic = imitate","needsCare":false,"sources":[{"title":"Merriam-Webster：mimic","url":"https://www.merriam-webster.com/dictionary/mimic"},{"title":"Merriam-Webster：imitate","url":"https://www.merriam-webster.com/dictionary/imitate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"392":{"sense":"v. 减轻；缓和","collocations":["mitigate risks","alleviate pain"],"example":"Additional training could mitigate the risk of accidents.","translation":"额外培训可以降低事故风险。","note":"mitigate常接风险、影响或严重程度；alleviate常接痛苦、负担或问题，不保证每个宾语都同样自然。","number":392,"resourceId":"doc-026-18-f59e9362b105","term":"mitigate","originalPair":"mitigate = alleviate","needsCare":false,"sources":[{"title":"Merriam-Webster：mitigate","url":"https://www.merriam-webster.com/dictionary/mitigate"},{"title":"Merriam-Webster：alleviate","url":"https://www.merriam-webster.com/dictionary/alleviate"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"393":{"sense":"v. 修改；调整","collocations":["modify a design","alter a plan"],"example":"The team modified the design after testing the prototype.","translation":"团队在测试原型后修改了设计。","note":"modify常指局部调整；alter一般指改变，不一定说明改变范围很小。","number":393,"resourceId":"doc-026-18-b0d2f184ea58","term":"modify","originalPair":"modify = alter","needsCare":false,"sources":[{"title":"Merriam-Webster：modify","url":"https://www.merriam-webster.com/dictionary/modify"},{"title":"Merriam-Webster：alter","url":"https://www.merriam-webster.com/dictionary/alter"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"394":{"sense":"v. 监测；持续观察","collocations":["monitor progress","supervise staff"],"example":"Sensors monitor air quality near the main road.","translation":"传感器监测主干道附近的空气质量。","note":"monitor重在观察或记录变化；supervise重在监督指导人员或活动，不能用来泛指传感器测量。","number":394,"resourceId":"doc-026-18-54be05db896b","term":"monitor","originalPair":"monitor = supervise","needsCare":false,"sources":[{"title":"Merriam-Webster：monitor","url":"https://www.merriam-webster.com/dictionary/monitor"},{"title":"Merriam-Webster：supervise","url":"https://www.merriam-webster.com/dictionary/supervise"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"395":{"sense":"v. 抵消；使无效；否定","collocations":["negate benefits","nullify an agreement"],"example":"High fees can negate the benefits of a discount.","translation":"高额费用可能抵消折扣带来的好处。","note":"nullify常指使协议或结果无效；negate还可指否定或抵消，不一定涉及正式撤销。","number":395,"resourceId":"doc-026-19-81272bda81e3","term":"negate","originalPair":"negate = nullify","needsCare":false,"sources":[{"title":"Merriam-Webster：negate","url":"https://www.merriam-webster.com/dictionary/negate"},{"title":"Merriam-Webster：nullify","url":"https://www.merriam-webster.com/dictionary/nullify"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"396":{"sense":"v. 培育；支持成长","collocations":["nurture confidence","foster cooperation"],"example":"Supportive feedback can nurture a student's interest in science.","translation":"支持性的反馈可以培养学生对科学的兴趣。","note":"nurture突出持续照料和支持；foster强调促进形成，不能把寄养等其他义项一并套用。","number":396,"resourceId":"doc-026-19-823f97afbb49","term":"nurture","originalPair":"nurture = foster","needsCare":false,"sources":[{"title":"Merriam-Webster：nurture","url":"https://www.merriam-webster.com/dictionary/nurture"},{"title":"Merriam-Webster：foster","url":"https://www.merriam-webster.com/dictionary/foster"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"397":{"sense":"adj. 模糊的；鲜为人知的","collocations":["an obscure reference","a vague description"],"example":"The article contains several obscure historical references.","translation":"文章包含几处难以理解的历史典故。","note":"obscure可指难懂、昏暗或不知名；vague侧重不清楚、不具体，鲜为人知不等于含糊。","number":397,"resourceId":"doc-026-19-f79e63976613","term":"obscure","originalPair":"obscure = vague","needsCare":true,"sources":[{"title":"Merriam-Webster：obscure","url":"https://www.merriam-webster.com/dictionary/obscure"},{"title":"Merriam-Webster：vague","url":"https://www.merriam-webster.com/dictionary/vague"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"398":{"sense":"v. 抵消；补偿","collocations":["offset costs","counterbalance an effect"],"example":"Energy savings may offset the higher purchase price.","translation":"节省的能源费用可能抵消更高的购买价格。","note":"offset常用于成本、损失或不利影响；counterbalance强调提供反向力量使平衡，需说明抵消的是何项。","number":398,"resourceId":"doc-026-19-c9be915940a0","term":"offset","originalPair":"offset = counterbalance","needsCare":false,"sources":[{"title":"Merriam-Webster：offset","url":"https://www.merriam-webster.com/dictionary/offset"},{"title":"Merriam-Webster：counterbalance","url":"https://www.merriam-webster.com/dictionary/counterbalance"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"399":{"sense":"v. 省略；遗漏","collocations":["omit from","exclude from"],"example":"The summary omits several minor details.","translation":"摘要省略了几处次要细节。","note":"omit可有意省略也可无意漏掉；exclude强调不纳入或排除，不能把所有遗漏都说成排斥。","number":399,"resourceId":"doc-026-19-452fa85d1cc6","term":"omit","originalPair":"omit = exclude","needsCare":true,"sources":[{"title":"Merriam-Webster：omit","url":"https://www.merriam-webster.com/dictionary/omit"},{"title":"Merriam-Webster：exclude","url":"https://www.merriam-webster.com/dictionary/exclude"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"},"400":{"sense":"v. 优化","collocations":["optimize performance","improve quality"],"example":"We adjusted the settings to optimize battery performance.","translation":"我们调整设置，以优化电池表现。","note":"improve泛指改善；optimize更强调在特定条件下做到尽可能好，不等于任何轻微改善。","number":400,"resourceId":"doc-026-19-fa20d025c0b6","term":"optimize","originalPair":"optimize = improve","needsCare":true,"sources":[{"title":"Merriam-Webster：optimize","url":"https://www.merriam-webster.com/dictionary/optimize"},{"title":"Merriam-Webster：improve","url":"https://www.merriam-webster.com/dictionary/improve"}],"credit":"本站编写例句与中文用法说明；词义参考 Merriam-Webster，非词典原文例句。"}}};
